window.GITA=window.GITA||{};GITA.capitulos=GITA.capitulos||{};GITA.capitulos[2]={"numero": 2, "titulo": "El yoga del discernimiento", "versos": [{"n": 1, "hablante": "sanjaya", "sa": ["सञ्जय उवाच ।", "तं तथा कृपयाविष्टमश्रुपूर्णाकुलेक्षणम् ।", "विषीदन्तमिदं वाक्यमुवाच मधुसूदनः ॥१॥"], "iast": ["sañjaya uvāca", "taṃ tathā kṛpayāviṣṭam aśru-pūrṇākulekṣaṇam", "viṣīdantam idaṃ vākyam uvāca madhusūdanaḥ"], "rojas": [], "t": "<span class=\"vt-parte\">A él, así invadido por la <a class=\"t\" href=\"glosario.html#krpa-compasion\" data-t=\"krpa-compasion\">compasión</a>, con los ojos turbados y arrasados en lágrimas, <a class=\"t\" href=\"glosario.html#visada\" data-t=\"visada\">abatido</a>, le dirigió <a class=\"t\" href=\"glosario.html#madhusudana\" data-t=\"madhusudana\">Madhusūdana</a> estas palabras:</span>", "palabras": [{"iast": "sañjayaḥ", "sa": "सञ्जयः", "gram": "nom. sg. m.", "es": "Saṃjaya", "ref": "sanjaya"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "tam", "sa": "तम्", "gram": "ac. sg. m. pron.", "es": "a él"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así"}, {"iast": "kṛpayā", "sa": "कृपया", "gram": "instr. sg. f.", "es": "por la compasión", "ref": "krpa-compasion"}, {"iast": "āviṣṭam", "sa": "आविष्टम्", "gram": "ac. sg. m. ppp", "es": "invadido", "analisis": "ā + √viś (entrar): «penetrado, poseído»"}, {"iast": "aśru-pūrṇa-ākula-īkṣaṇam", "sa": "अश्रुपूर्णाकुलेक्षणम्", "gram": "ac. sg. m. comp. adj.", "es": "de ojos llenos de lágrimas y turbados", "analisis": "aśru (lágrima) + pūrṇa (lleno) + ākula (turbado) + īkṣaṇa (ojo, mirada)"}, {"iast": "viṣīdantam", "sa": "विषीदन्तम्", "gram": "ac. sg. m. part. pres.", "es": "que desfallecía", "ref": "visada", "analisis": "vi + √sad (hundirse); de la misma raíz que viṣāda"}, {"iast": "idam", "sa": "इदम्", "gram": "ac. sg. n. pron.", "es": "estas"}, {"iast": "vākyam", "sa": "वाक्यम्", "gram": "ac. sg. n.", "es": "palabras", "analisis": "de √vac (hablar)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo"}, {"iast": "madhusūdanaḥ", "sa": "मधुसूदनः", "gram": "nom. sg. m.", "es": "Madhusūdana", "ref": "madhusudana"}], "nota": "<p>Saṃjaya retoma la escena donde la dejó en <a class=\"vref\" href=\"capitulo-01.html#v47\" data-v=\"1.47\">1.47</a> y con la misma fórmula de <a class=\"vref\" href=\"capitulo-01.html#v28\" data-v=\"1.28\">1.28</a>: Arjuna no siente compasión, sino que está «invadido» (<em>āviṣṭa</em>) por ella. La imagen de los ojos llenos de lágrimas completa el retrato del guerrero derrumbado.</p><p>El epíteto elegido para Kṛṣṇa, <a class=\"t\" href=\"glosario.html#madhusudana\" data-t=\"madhusudana\">Madhusūdana</a>, «el que mató al demonio Madhu», tampoco pasa inadvertido a los comentaristas. Para Vedānta Deśika anuncia que Kṛṣṇa va a destruir el rajas y el tamas, raíz del pesar de Arjuna; para Madhusūdana Sarasvatī, que quien castiga a los malvados hablará a Arjuna en ese mismo sentido.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 2, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "कुतस्त्वा कश्मलमिदं विषमे समुपस्थितम् ।", "अनार्यजुष्टमस्वर्ग्यमकीर्तिकरमर्जुन ॥२॥"], "iast": ["śrī-bhagavān uvāca", "kutas tvā kaśmalam idaṃ viṣame samupasthitam", "anārya-juṣṭam asvargyam akīrti-karam arjuna"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">¿De dónde te ha venido, en este trance, este <a class=\"t\" href=\"glosario.html#kasmala\" data-t=\"kasmala\">desfallecimiento</a>, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>? Es propio de quien no es <a class=\"t\" href=\"glosario.html#arya\" data-t=\"arya\">noble</a>, no conduce al <a class=\"t\" href=\"glosario.html#svarga\" data-t=\"svarga\">cielo</a> y acarrea la <a class=\"t\" href=\"glosario.html#kirti\" data-t=\"kirti\">deshonra</a>.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria, fortuna) + bhagavat (el que posee bhaga, «fortuna, majestad»)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo"}, {"iast": "kutaḥ", "sa": "कुतः", "gram": "ind.", "es": "¿de dónde?"}, {"iast": "tvā", "sa": "त्वा", "gram": "ac. sg. pron.", "es": "a ti", "analisis": "forma enclítica de tvām"}, {"iast": "kaśmalam", "sa": "कश्मलम्", "gram": "nom. sg. n.", "es": "desfallecimiento", "ref": "kasmala"}, {"iast": "idam", "sa": "इदम्", "gram": "nom. sg. n. pron.", "es": "este"}, {"iast": "viṣame", "sa": "विषमे", "gram": "loc. sg. n.", "es": "en este trance", "analisis": "vi-ṣama, «desigual, escabroso»: el momento crítico"}, {"iast": "samupasthitam", "sa": "समुपस्थितम्", "gram": "nom. sg. n. ppp", "es": "ha sobrevenido", "analisis": "sam-upa-√sthā (presentarse)"}, {"iast": "anārya-juṣṭam", "sa": "अनार्यजुष्टम्", "gram": "nom. sg. n. comp. adj.", "es": "propio de quien no es noble", "ref": "arya", "analisis": "an-ārya (no noble) + juṣṭa (practicado, frecuentado; de √juṣ)"}, {"iast": "asvargyam", "sa": "अस्वर्ग्यम्", "gram": "nom. sg. n. adj.", "es": "que no conduce al cielo", "ref": "svarga", "analisis": "a- (no) + svargya (que lleva al cielo)"}, {"iast": "akīrti-karam", "sa": "अकीर्तिकरम्", "gram": "nom. sg. n. comp. adj.", "es": "que causa deshonra", "ref": "kirti", "analisis": "a-kīrti (deshonra) + kara (que hace; de √kṛ)"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}], "nota": "<p>Primeras palabras de Kṛṣṇa como hablante en la Gītā; la fórmula <em>śrī-bhagavān uvāca</em>, «dijo el glorioso Señor», introducirá en adelante todos sus discursos. En esta edición, sus palabras van en rojo.</p><p>La primera respuesta no es filosófica. Kṛṣṇa apela al código del guerrero con tres reproches: el abatimiento es impropio de un <a class=\"t\" href=\"glosario.html#arya\" data-t=\"arya\">ārya</a>, de un noble; no lleva al <a class=\"t\" href=\"glosario.html#svarga\" data-t=\"svarga\">cielo</a> que el kṣatriya gana combatiendo; y trae deshonra, la pérdida de la <a class=\"t\" href=\"glosario.html#kirti\" data-t=\"kirti\">kīrti</a>. Los mismos argumentos volverán, desarrollados, en <a class=\"vref\" href=\"capitulo-02.html#v31\" data-v=\"2.31\">2.31</a>–<a class=\"vref\" href=\"capitulo-02.html#v37\" data-v=\"2.37\">2.37</a>.</p>", "interp": [{"titulo": "Primero, el código del guerrero", "html": "<p>La enseñanza avanza de lo exterior a lo interior. Kṛṣṇa empieza por los valores que Arjuna ya comparte (nobleza, cielo, honor) y sólo cuando éste se declara discípulo (<a class=\"vref\" href=\"capitulo-02.html#v7\" data-v=\"2.7\">2.7</a>) y se niega a luchar (<a class=\"vref\" href=\"capitulo-02.html#v9\" data-v=\"2.9\">2.9</a>) pasa al plano del <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">ātman</a> (<a class=\"vref\" href=\"capitulo-02.html#v11\" data-v=\"2.11\">2.11</a> y siguientes). Muchos lectores ven en este orden una pedagogía: no se ofrece la doctrina a quien no la ha pedido.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 3, "hablante": "krsna", "sa": ["क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते ।", "क्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परन्तप ॥३॥"], "iast": ["klaibyaṃ mā sma gamaḥ pārtha naitat tvayy upapadyate", "kṣudraṃ hṛdaya-daurbalyaṃ tyaktvottiṣṭha parantapa"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">No caigas en esa falta de hombría, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>: no es digna de ti. Sacude esa mezquina flaqueza del corazón y levántate, oh <a class=\"t\" href=\"glosario.html#parantapa\" data-t=\"parantapa\">Parantapa</a>.</span>", "palabras": [{"iast": "klaibyam", "sa": "क्लैब्यम्", "gram": "ac. sg. n.", "es": "falta de hombría", "analisis": "de klība (impotente, eunuco)"}, {"iast": "mā", "sa": "मा", "gram": "ind.", "es": "no", "analisis": "partícula prohibitiva"}, {"iast": "sma", "sa": "स्म", "gram": "ind.", "es": "(refuerza la prohibición)"}, {"iast": "gamaḥ", "sa": "गमः", "gram": "2 sg. aor. act.", "es": "caigas", "analisis": "√gam (ir); con mā, prohibición: «no vayas a», «no caigas en»"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "etat", "sa": "एतत्", "gram": "nom. sg. n. pron.", "es": "esto"}, {"iast": "tvayi", "sa": "त्वयि", "gram": "loc. sg. pron.", "es": "en ti"}, {"iast": "upapadyate", "sa": "उपपद्यते", "gram": "3 sg. pres. med.", "es": "es propio, conviene", "analisis": "upa-√pad (corresponder)"}, {"iast": "kṣudram", "sa": "क्षुद्रम्", "gram": "ac. sg. n. adj.", "es": "mezquina, vil"}, {"iast": "hṛdaya-daurbalyam", "sa": "हृदयदौर्बल्यम्", "gram": "ac. sg. n. comp.", "es": "flaqueza del corazón", "analisis": "hṛdaya (corazón) + daurbalya (debilidad; de dur-bala, «de poca fuerza»)"}, {"iast": "tyaktvā", "sa": "त्यक्त्वा", "gram": "abs.", "es": "tras abandonar", "analisis": "√tyaj (abandonar)"}, {"iast": "uttiṣṭha", "sa": "उत्तिष्ठ", "gram": "2 sg. impv. act.", "es": "levántate", "analisis": "ut-√sthā (ponerse en pie)"}, {"iast": "parantapa", "sa": "परन्तप", "gram": "voc. sg. m.", "es": "oh Parantapa, abrasador de enemigos", "ref": "parantapa", "analisis": "param (al enemigo) + √tap (abrasar)"}], "nota": "<p><em>Klaibya</em> deriva de <em>klība</em>, «impotente, eunuco»: el reproche es deliberadamente hiriente para un guerrero. Dos ironías refuerzan la exhortación. Kṛṣṇa lo llama <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, «hijo de Pṛthā», recordándole a su madre <a class=\"t\" href=\"glosario.html#kunti\" data-t=\"kunti\">Kuntī</a>, que esperaba de él valor. Y lo llama <a class=\"t\" href=\"glosario.html#parantapa\" data-t=\"parantapa\">Parantapa</a>, «abrasador de enemigos», justo cuando se niega a combatirlos.</p><p><em>Uttiṣṭha</em>, «levántate», responde a la imagen con que terminaba el capítulo 1: Arjuna sentado en el carro (<a class=\"vref\" href=\"capitulo-01.html#v47\" data-v=\"1.47\">1.47</a>).</p>", "interp": [{"titulo": "La fuerza como mensaje", "html": "<p>Swami Vivekananda tuvo este verso por un resumen de toda la Gītā: quien lea este solo śloka, decía en sus «Thoughts on the Gita», obtiene todo el mérito de leerla entera, porque en él está contenido todo su mensaje, que es ante todo un rechazo de la debilidad. Su lectura, muy influyente en la India moderna, hizo de <em>uttiṣṭha</em>, «levántate», una consigna de renovación personal y nacional.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}, {"titulo": "Una exhortación sin argumentos", "html": "<p>El verso no razona: ordena. Kṛṣṇa aún no ha explicado por qué Arjuna debería luchar; sólo lo llama a dejar la flaqueza. Por eso Arjuna no se convence y responde con nuevas razones (<a class=\"vref\" href=\"capitulo-02.html#v4\" data-v=\"2.4\">2.4</a>–<a class=\"vref\" href=\"capitulo-02.html#v8\" data-v=\"2.8\">2.8</a>). La exhortación sola no basta; hará falta la enseñanza.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 4, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "कथं भीष्ममहं सङ्ख्ये द्रोणं च मधुसूदन ।", "इषुभिः प्रतियोत्स्यामि पूजार्हावरिसूदन ॥४॥"], "iast": ["arjuna uvāca", "kathaṃ bhīṣmam ahaṃ saṅkhye droṇaṃ ca madhusūdana", "iṣubhiḥ pratiyotsyāmi pūjārhāv ari-sūdana"], "rojas": [], "t": "<span class=\"vt-parte\">¿Cómo voy a responder con flechas en la batalla a <a class=\"t\" href=\"glosario.html#bhisma\" data-t=\"bhisma\">Bhīṣma</a> y a <a class=\"t\" href=\"glosario.html#drona\" data-t=\"drona\">Droṇa</a>, oh <a class=\"t\" href=\"glosario.html#madhusudana\" data-t=\"madhusudana\">Madhusūdana</a>, si ambos son dignos de veneración, oh <a class=\"t\" href=\"glosario.html#arisudana\" data-t=\"arisudana\">Arisūdana</a>?</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo"}, {"iast": "katham", "sa": "कथम्", "gram": "ind.", "es": "¿cómo?"}, {"iast": "bhīṣmam", "sa": "भीष्मम्", "gram": "ac. sg. m.", "es": "a Bhīṣma", "ref": "bhisma"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "saṅkhye", "sa": "सङ्ख्ये", "gram": "loc. sg. n.", "es": "en la batalla"}, {"iast": "droṇam", "sa": "द्रोणम्", "gram": "ac. sg. m.", "es": "a Droṇa", "ref": "drona"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "madhusūdana", "sa": "मधुसूदन", "gram": "voc. sg. m.", "es": "oh Madhusūdana", "ref": "madhusudana"}, {"iast": "iṣubhiḥ", "sa": "इषुभिः", "gram": "instr. pl. m.", "es": "con flechas"}, {"iast": "pratiyotsyāmi", "sa": "प्रतियोत्स्यामि", "gram": "1 sg. fut. act.", "es": "combatiré contra", "analisis": "prati-√yudh (combatir contra, responder en combate)"}, {"iast": "pūjā-arhau", "sa": "पूजार्हौ", "gram": "ac. du. m. comp. adj.", "es": "ambos dignos de veneración", "analisis": "pūjā (veneración, culto) + arha (digno)"}, {"iast": "ari-sūdana", "sa": "अरिसूदन", "gram": "voc. sg. m. comp.", "es": "oh Arisūdana, matador de enemigos", "ref": "arisudana", "analisis": "ari (enemigo) + sūdana (que da muerte)"}], "nota": "<p>Arjuna no acepta el reproche y da una razón nueva, más concreta que las del capítulo 1: no se trata ya de la ruina de las familias, sino de dos personas. <a class=\"t\" href=\"glosario.html#bhisma\" data-t=\"bhisma\">Bhīṣma</a> es su abuelo y <a class=\"t\" href=\"glosario.html#drona\" data-t=\"drona\">Droṇa</a>, su maestro; a ambos les debe culto (<em>pūjā</em>), y la tradición subraya el contraste: a quienes debería honrar con flores, tendría que responder con flechas.</p><p>Arjuna acumula epítetos de Kṛṣṇa como matador: <a class=\"t\" href=\"glosario.html#madhusudana\" data-t=\"madhusudana\">Madhusūdana</a>, «matador de Madhu», y <a class=\"t\" href=\"glosario.html#arisudana\" data-t=\"arisudana\">Arisūdana</a>, «matador de enemigos». Es como si dijera: tú matas demonios y enemigos, no maestros venerables.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 5, "hablante": "arjuna", "sa": ["गुरूनहत्वा हि महानुभावाञ्छ्रेयो भोक्तुं भैक्ष्यमपीह लोके ।", "हत्वार्थकामांस्तु गुरूनिहैव भुञ्जीय भोगान्रुधिरप्रदिग्धान् ॥५॥"], "iast": ["gurūn ahatvā hi mahānubhāvāñ chreyo bhoktuṃ bhaikṣyam apīha loke", "hatvārtha-kāmāṃs tu gurūn ihaiva bhuñjīya bhogān rudhira-pradigdhān"], "rojas": [], "t": "<span class=\"vt-parte\"><a class=\"t\" href=\"glosario.html#sreyas\" data-t=\"sreyas\">Más vale</a> comer en este mundo aun el pan mendigado que matar a estos <a class=\"t\" href=\"glosario.html#guru\" data-t=\"guru\">maestros</a> de tan gran nobleza. Si matara a mis maestros, por codiciosos de bienes que sean, aquí mismo gozaría de placeres manchados de sangre.</span>", "palabras": [{"iast": "gurūn", "sa": "गुरून्", "gram": "ac. pl. m.", "es": "a los maestros", "ref": "guru"}, {"iast": "ahatvā", "sa": "अहत्वा", "gram": "abs.", "es": "sin matar", "analisis": "a- (no) + hatvā (de √han, matar)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "mahā-anubhāvān", "sa": "महानुभावान्", "gram": "ac. pl. m. comp. adj.", "es": "de gran nobleza", "analisis": "mahā (gran) + anubhāva (dignidad, poder)"}, {"iast": "śreyaḥ", "sa": "श्रेयः", "gram": "nom. sg. n.", "es": "mejor", "ref": "sreyas"}, {"iast": "bhoktum", "sa": "भोक्तुम्", "gram": "inf.", "es": "comer", "analisis": "√bhuj (comer, disfrutar)"}, {"iast": "bhaikṣyam", "sa": "भैक्ष्यम्", "gram": "ac. sg. n.", "es": "lo obtenido de limosna", "analisis": "de bhikṣā (limosna), √bhikṣ (mendigar)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "incluso"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí"}, {"iast": "loke", "sa": "लोके", "gram": "loc. sg. m.", "es": "en el mundo"}, {"iast": "hatvā", "sa": "हत्वा", "gram": "abs.", "es": "tras matar", "analisis": "√han (matar)"}, {"iast": "artha-kāmān", "sa": "अर्थकामान्", "gram": "ac. pl. m. comp. adj.", "es": "codiciosos de bienes", "analisis": "artha (riqueza, bienes) + kāma (deseo); véase la nota"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "gurūn", "sa": "गुरून्", "gram": "ac. pl. m.", "es": "a los maestros", "ref": "guru"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "mismo"}, {"iast": "bhuñjīya", "sa": "भुञ्जीय", "gram": "1 sg. opt. med.", "es": "gozaría", "analisis": "√bhuj (comer, gozar)"}, {"iast": "bhogān", "sa": "भोगान्", "gram": "ac. pl. m.", "es": "placeres", "analisis": "de √bhuj"}, {"iast": "rudhira-pradigdhān", "sa": "रुधिरप्रदिग्धान्", "gram": "ac. pl. m. comp. adj.", "es": "manchados de sangre", "analisis": "rudhira (sangre) + pradigdha (untado; pra-√dih)"}], "nota": "<p>Con este verso el metro cambia: de 2.5 a 2.8 Arjuna habla en <em>triṣṭubh</em>, estrofas de cuatro pies de once sílabas, más amplias y solemnes que el <em>śloka</em> narrativo. El cambio subraya la intensidad del momento.</p><p>Vivir de limosna (<em>bhaikṣya</em>) es lo propio del asceta o del estudiante brahmán, no del <a class=\"t\" href=\"glosario.html#ksatriya\" data-t=\"ksatriya\">kṣatriya</a>. Arjuna propone, sin decirlo, la vida del renunciante: una salida que la Gītā rechazará cuando consista en abandonar el deber propio.</p><p>El compuesto <em>artha-kāmān</em> admite dos lecturas. La más extendida lo refiere a los maestros: «aunque sean codiciosos de bienes», alusión a que Bhīṣma y Droṇa combaten del lado de Duryodhana porque le deben su sustento; los comentaristas citan las palabras de Bhīṣma a Yudhiṣṭhira antes de la batalla: «el hombre es esclavo de la riqueza, pero la riqueza no es esclava de nadie; […] los Kauravas me han atado con la riqueza» (<em>Mahābhārata</em> 6.41.36). Otros lo refieren a los placeres: «gozaría de placeres de riqueza y deseo manchados de sangre». La traducción sigue la primera.</p>", "interp": [{"titulo": "La tentación de la renuncia", "html": "<p>Arjuna plantea aquí, por primera vez, la alternativa que recorre toda la Gītā: actuar o renunciar. Su propuesta, retirarse a mendigar, parece más pura que la guerra. Kṛṣṇa responderá que nadie alcanza la perfección por el mero hecho de dejar de actuar (<a class=\"vref\" href=\"capitulo-03.html#v4\" data-v=\"3.4\">3.4</a>) y que abandonar un deber por extravío es una renuncia de la peor especie (<a class=\"vref\" href=\"capitulo-18.html#v7\" data-v=\"18.7\">18.7</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 6, "hablante": "arjuna", "sa": ["न चैतद्विद्मः कतरन्नो गरीयो यद्वा जयेम यदि वा नो जयेयुः ।", "यानेव हत्वा न जिजीविषामस्तेऽवस्थिताः प्रमुखे धार्तराष्ट्राः ॥६॥"], "iast": ["na caitad vidmaḥ kataran no garīyo yad vā jayema yadi vā no jayeyuḥ", "yān eva hatvā na jijīviṣāmas te 'vasthitāḥ pramukhe dhārtarāṣṭrāḥ"], "rojas": [], "t": "<span class=\"vt-parte\">Ni siquiera sabemos qué es preferible para nosotros: vencerlos o que ellos nos venzan. Ahí delante están los <a class=\"t\" href=\"glosario.html#dhartarastras\" data-t=\"dhartarastras\">hijos de Dhṛtarāṣṭra</a>, los mismos a quienes, si matáramos, ya no querríamos vivir.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "etat", "sa": "एतत्", "gram": "ac. sg. n. pron.", "es": "esto"}, {"iast": "vidmaḥ", "sa": "विद्मः", "gram": "1 pl. pf. act.", "es": "sabemos", "analisis": "√vid (saber); perfecto con valor de presente"}, {"iast": "katarat", "sa": "कतरत्", "gram": "nom. sg. n. pron.", "es": "cuál de las dos cosas"}, {"iast": "naḥ", "sa": "नः", "gram": "gen. pl. pron.", "es": "para nosotros"}, {"iast": "garīyaḥ", "sa": "गरीयः", "gram": "nom. sg. n. adj.", "es": "preferible", "analisis": "comparativo de guru (pesado, importante)"}, {"iast": "yat", "sa": "यत्", "gram": "ind.", "es": "que"}, {"iast": "vā", "sa": "वा", "gram": "ind.", "es": "o"}, {"iast": "jayema", "sa": "जयेम", "gram": "1 pl. opt. act.", "es": "venciéramos", "analisis": "√ji (vencer)"}, {"iast": "yadi", "sa": "यदि", "gram": "ind.", "es": "si"}, {"iast": "vā", "sa": "वा", "gram": "ind.", "es": "o"}, {"iast": "naḥ", "sa": "नः", "gram": "ac. pl. pron.", "es": "a nosotros"}, {"iast": "jayeyuḥ", "sa": "जयेयुः", "gram": "3 pl. opt. act.", "es": "vencieran"}, {"iast": "yān", "sa": "यान्", "gram": "ac. pl. m. pron.", "es": "a quienes"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "hatvā", "sa": "हत्वा", "gram": "abs.", "es": "tras matar"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "jijīviṣāmaḥ", "sa": "जिजीविषामः", "gram": "1 pl. pres. act. desid.", "es": "querríamos vivir", "analisis": "desiderativo de √jīv (vivir)"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ellos"}, {"iast": "avasthitāḥ", "sa": "अवस्थिताः", "gram": "nom. pl. m. ppp", "es": "apostados", "analisis": "ava-√sthā (situarse)"}, {"iast": "pramukhe", "sa": "प्रमुखे", "gram": "loc. sg. n.", "es": "delante"}, {"iast": "dhārtarāṣṭrāḥ", "sa": "धार्तराष्ट्राः", "gram": "nom. pl. m.", "es": "los hijos de Dhṛtarāṣṭra", "ref": "dhartarastras"}], "nota": "<p>Arjuna confiesa su incertidumbre: ni la victoria ni la derrota le parecen deseables, porque vencer significaría matar a los suyos. La duda prepara la petición del verso siguiente.</p><p>En la primera mitad de la estrofa los pies tienen doce sílabas en lugar de once (metro <em>jagatī</em>); la Gītā mezcla a veces ambos tipos de pie en una misma estrofa.</p>", "interp": [], "metro": "triṣṭubh con pies de jagatī (once y doce sílabas)"}, {"n": 7, "hablante": "arjuna", "sa": ["कार्पण्यदोषोपहतस्वभावः पृच्छामि त्वां धर्मसम्मूढचेताः ।", "यच्छ्रेयः स्यान्निश्चितं ब्रूहि तन्मे शिष्यस्तेऽहं शाधि मां त्वां प्रपन्नम् ॥७॥"], "iast": ["kārpaṇya-doṣopahata-svabhāvaḥ pṛcchāmi tvāṃ dharma-sammūḍha-cetāḥ", "yac chreyaḥ syān niścitaṃ brūhi tan me śiṣyas te 'haṃ śādhi māṃ tvāṃ prapannam"], "rojas": [], "t": "<span class=\"vt-parte\">Con mi naturaleza dañada por el vicio de la <a class=\"t\" href=\"glosario.html#karpanya\" data-t=\"karpanya\">pusilanimidad</a> y la mente <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extraviada</a> acerca del <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a>, te pregunto: dime con certeza qué es lo <a class=\"t\" href=\"glosario.html#sreyas\" data-t=\"sreyas\">mejor</a> para mí. Soy tu <a class=\"t\" href=\"glosario.html#guru\" data-t=\"guru\">discípulo</a>: instrúyeme, que en ti me <a class=\"t\" href=\"glosario.html#prapatti\" data-t=\"prapatti\">refugio</a>.</span>", "palabras": [{"iast": "kārpaṇya-doṣa-upahata-svabhāvaḥ", "sa": "कार्पण्यदोषोपहतस्वभावः", "gram": "nom. sg. m. comp. adj.", "es": "con la naturaleza dañada por el vicio de la pusilanimidad", "ref": "karpanya", "analisis": "kārpaṇya (pusilanimidad, mezquindad) + doṣa (defecto, vicio) + upahata (dañado; upa-√han) + svabhāva (naturaleza propia)"}, {"iast": "pṛcchāmi", "sa": "पृच्छामि", "gram": "1 sg. pres. act.", "es": "pregunto", "analisis": "√prach (preguntar)"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "a ti"}, {"iast": "dharma-sammūḍha-cetāḥ", "sa": "धर्मसम्मूढचेताः", "gram": "nom. sg. m. comp. adj.", "es": "con la mente extraviada acerca del dharma", "ref": "dharma", "analisis": "dharma + sammūḍha (extraviado; sam-√muh, la raíz de moha) + cetas (mente)"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. pron.", "es": "lo que"}, {"iast": "śreyaḥ", "sa": "श्रेयः", "gram": "nom. sg. n.", "es": "lo mejor", "ref": "sreyas"}, {"iast": "syāt", "sa": "स्यात्", "gram": "3 sg. opt. act.", "es": "sea", "analisis": "√as (ser)"}, {"iast": "niścitam", "sa": "निश्चितम्", "gram": "ac. sg. n. ppp", "es": "con certeza", "analisis": "nis-√ci (determinar)"}, {"iast": "brūhi", "sa": "ब्रूहि", "gram": "2 sg. impv. act.", "es": "di", "analisis": "√brū (decir)"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "eso"}, {"iast": "me", "sa": "मे", "gram": "dat. sg. pron.", "es": "a mí"}, {"iast": "śiṣyaḥ", "sa": "शिष्यः", "gram": "nom. sg. m.", "es": "discípulo", "ref": "guru", "analisis": "de √śās (instruir): «el que ha de ser instruido»"}, {"iast": "te", "sa": "ते", "gram": "gen. sg. pron.", "es": "tuyo"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "śādhi", "sa": "शाधि", "gram": "2 sg. impv. act.", "es": "instrúyeme", "analisis": "√śās (instruir, disciplinar)"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "a ti"}, {"iast": "prapannam", "sa": "प्रपन्नम्", "gram": "ac. sg. m. ppp", "es": "refugiado", "ref": "prapatti", "analisis": "pra-√pad (acudir, refugiarse)"}], "nota": "<p>Es el verso que hace posible la Gītā. Hasta aquí Arjuna argumentaba con Kṛṣṇa como con un amigo y un igual; ahora reconoce que está confundido, pide una respuesta cierta y se declara discípulo (<em>śiṣya</em>) que se pone en sus manos (<em>prapanna</em>). Sólo entonces empieza la enseñanza.</p><p>El diagnóstico que hace de sí mismo es preciso. La <a class=\"t\" href=\"glosario.html#karpanya\" data-t=\"karpanya\"><em>kārpaṇya</em></a> es la pusilanimidad del que se encoge ante lo que debe hacer; <em>dharma-sammūḍha-cetāḥ</em>, «con la mente extraviada acerca del dharma», usa la raíz de <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\"><em>moha</em></a>, el extravío que la Gītā se propone disipar y que Arjuna declarará disipado al final (<a class=\"vref\" href=\"capitulo-18.html#v73\" data-v=\"18.73\">18.73</a>).</p><p><em>Śādhi</em> es un imperativo de √<em>śās</em>, «instruir, corregir, disciplinar»: la misma raíz que <em>śiṣya</em> y que <em>śāstra</em>, «enseñanza, tratado».</p>", "interp": [{"titulo": "Del ruego a la entrega", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> glosa <em>tvāṃ prapannam</em> como «a mí, tu discípulo, que me he refugiado en ti» (<em>śaraṇāgata</em>), y al comentar <a class=\"vref\" href=\"capitulo-02.html#v10\" data-v=\"2.10\">2.10</a>, con palabras de su predecesor Yāmuna, presenta toda la enseñanza como dirigida a Arjuna «refugiado» (<em>prapanna</em>): una enseñanza que va desde <a class=\"vref\" href=\"capitulo-02.html#v12\" data-v=\"2.12\">2.12</a> hasta <a class=\"vref\" href=\"capitulo-18.html#v66\" data-v=\"18.66\">18.66</a>, donde Kṛṣṇa invita a refugiarse sólo en él. Vedānta Deśika precisa que ese último verso enseña la entrega (<a class=\"t\" href=\"glosario.html#prapatti\" data-t=\"prapatti\">prapatti</a>). Para esta tradición, la enseñanza entera nace de una entrega y culmina en otra.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "La necesidad del maestro", "html": "<p>En la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, A. C. Bhaktivedanta Swami Prabhupāda ve aquí el momento en que Arjuna deja de tratar a Kṛṣṇa como amigo y lo acepta como maestro espiritual, y extrae una regla general: los problemas de la vida no se resuelven con el propio ingenio, sino acudiendo a un maestro auténtico con humildad.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}, {"titulo": "Un conflicto de deberes", "html": "<p><a class=\"t\" href=\"glosario.html#tilak\" data-t=\"tilak\">Bal Gangadhar Tilak</a> partió de este verso para leer la Gītā como un tratado de ética de la acción. La confusión de Arjuna no es la de quien no sabe qué es el bien, sino la de quien se encuentra ante deberes que chocan entre sí: con sus mayores, con su familia, con su clase. Según Tilak, la respuesta de Kṛṣṇa no es invitarlo a renunciar al mundo, sino enseñarle a actuar.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 8, "hablante": "arjuna", "sa": ["न हि प्रपश्यामि ममापनुद्याद्यच्छोकमुच्छोषणमिन्द्रियाणाम् ।", "अवाप्य भूमावसपत्नमृद्धं राज्यं सुराणामपि चाधिपत्यम् ॥८॥"], "iast": ["na hi prapaśyāmi mamāpanudyād yac chokam ucchoṣaṇam indriyāṇām", "avāpya bhūmāv asapatnam ṛddhaṃ rājyaṃ surāṇām api cādhipatyam"], "rojas": [], "t": "<span class=\"vt-parte\">Pues no veo qué podría disipar este <a class=\"t\" href=\"glosario.html#soka\" data-t=\"soka\">pesar</a> que me seca los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a>, aunque obtuviera en la tierra un reino próspero y sin rivales, y aun el señorío sobre los dioses.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "prapaśyāmi", "sa": "प्रपश्यामि", "gram": "1 sg. pres. act.", "es": "veo", "analisis": "pra-√paś (ver)"}, {"iast": "mama", "sa": "मम", "gram": "gen. sg. pron.", "es": "mi"}, {"iast": "apanudyāt", "sa": "अपनुद्यात्", "gram": "3 sg. opt. act.", "es": "pudiera disipar", "analisis": "apa-√nud (apartar, ahuyentar)"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. pron.", "es": "lo que"}, {"iast": "śokam", "sa": "शोकम्", "gram": "ac. sg. m.", "es": "pesar", "ref": "soka"}, {"iast": "ucchoṣaṇam", "sa": "उच्छोषणम्", "gram": "ac. sg. m. adj.", "es": "que seca", "analisis": "ut-√śuṣ (secar)"}, {"iast": "indriyāṇām", "sa": "इन्द्रियाणाम्", "gram": "gen. pl. n.", "es": "los sentidos", "ref": "indriya"}, {"iast": "avāpya", "sa": "अवाप्य", "gram": "abs.", "es": "aunque obtuviera", "analisis": "ava-√āp (obtener)"}, {"iast": "bhūmau", "sa": "भूमौ", "gram": "loc. sg. f.", "es": "en la tierra"}, {"iast": "asapatnam", "sa": "असपत्नम्", "gram": "ac. sg. n. adj.", "es": "sin rivales", "analisis": "a- (sin) + sapatna (rival)"}, {"iast": "ṛddham", "sa": "ऋद्धम्", "gram": "ac. sg. n. ppp", "es": "próspero", "analisis": "√ṛdh (prosperar)"}, {"iast": "rājyam", "sa": "राज्यम्", "gram": "ac. sg. n.", "es": "reino"}, {"iast": "surāṇām", "sa": "सुराणाम्", "gram": "gen. pl. m.", "es": "de los dioses"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "incluso"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "ādhipatyam", "sa": "आधिपत्यम्", "gram": "ac. sg. n.", "es": "señorío", "analisis": "de adhipati (soberano)"}], "nota": "<p>Arjuna llega al límite de sus razones: ni el reino por el que se combate ni siquiera la soberanía de los dioses, el trono de <a class=\"t\" href=\"glosario.html#indra\" data-t=\"indra\">Indra</a>, podrían curar su <a class=\"t\" href=\"glosario.html#soka\" data-t=\"soka\">pesar</a>. Sin saberlo, descarta todas las metas que ofrecen la guerra y el rito; la Gītā partirá precisamente de ahí, de la insuficiencia de cualquier ganancia exterior.</p><p>La imagen del pesar que «seca» los sentidos responde a los síntomas físicos de <a class=\"vref\" href=\"capitulo-01.html#v29\" data-v=\"1.29\">1.29</a>–<a class=\"vref\" href=\"capitulo-01.html#v30\" data-v=\"1.30\">1.30</a>: la boca seca, los miembros desfallecidos.</p>", "interp": [], "metro": "triṣṭubh (cuatro pies de once sílabas)"}, {"n": 9, "hablante": "sanjaya", "sa": ["सञ्जय उवाच ।", "एवमुक्त्वा हृषीकेशं गुडाकेशः परन्तप ।", "न योत्स्य इति गोविन्दमुक्त्वा तूष्णीं बभूव ह ॥९॥"], "iast": ["sañjaya uvāca", "evam uktvā hṛṣīkeśaṃ guḍākeśaḥ parantapa", "na yotsya iti govindam uktvā tūṣṇīṃ babhūva ha"], "rojas": [], "t": "<span class=\"vt-parte\">Tras hablar así a <a class=\"t\" href=\"glosario.html#hrsikesa\" data-t=\"hrsikesa\">Hṛṣīkeśa</a>, oh <a class=\"t\" href=\"glosario.html#parantapa\" data-t=\"parantapa\">Parantapa</a>, <a class=\"t\" href=\"glosario.html#gudakesa\" data-t=\"gudakesa\">Guḍākeśa</a> dijo a <a class=\"t\" href=\"glosario.html#govinda\" data-t=\"govinda\">Govinda</a>: «No lucharé», y quedó en silencio.</span>", "palabras": [{"iast": "sañjayaḥ", "sa": "सञ्जयः", "gram": "nom. sg. m.", "es": "Saṃjaya", "ref": "sanjaya"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "uktvā", "sa": "उक्त्वा", "gram": "abs.", "es": "tras hablar", "analisis": "√vac (hablar)"}, {"iast": "hṛṣīkeśam", "sa": "हृषीकेशम्", "gram": "ac. sg. m.", "es": "a Hṛṣīkeśa", "ref": "hrsikesa"}, {"iast": "guḍākeśaḥ", "sa": "गुडाकेशः", "gram": "nom. sg. m.", "es": "Guḍākeśa", "ref": "gudakesa"}, {"iast": "parantapa", "sa": "परन्तप", "gram": "voc. sg. m.", "es": "oh Parantapa", "ref": "parantapa", "analisis": "aquí se dirige a Dhṛtarāṣṭra"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "yotsye", "sa": "योत्स्ये", "gram": "1 sg. fut. med.", "es": "lucharé", "analisis": "√yudh (combatir); ante iti, yotsya por sandhi"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "(cierra la cita)"}, {"iast": "govindam", "sa": "गोविन्दम्", "gram": "ac. sg. m.", "es": "a Govinda", "ref": "govinda"}, {"iast": "uktvā", "sa": "उक्त्वा", "gram": "abs.", "es": "tras decir"}, {"iast": "tūṣṇīm", "sa": "तूष्णीम्", "gram": "ind.", "es": "en silencio"}, {"iast": "babhūva", "sa": "बभूव", "gram": "3 sg. pf. act.", "es": "quedó", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "ha", "sa": "ह", "gram": "ind.", "es": "(partícula narrativa)"}], "nota": "<p><em>Na yotsye</em>, «no lucharé»: la negativa definitiva, tras la cual Arjuna calla. El silencio es el punto más bajo de la crisis y, a la vez, el umbral de la enseñanza.</p><p>El vocativo <a class=\"t\" href=\"glosario.html#parantapa\" data-t=\"parantapa\"><em>parantapa</em></a>, «abrasador de enemigos», no se refiere aquí a Arjuna: Saṃjaya se dirige al rey <a class=\"t\" href=\"glosario.html#dhrtarastra\" data-t=\"dhrtarastra\">Dhṛtarāṣṭra</a>, que escucha el relato. El título guerrero suena irónico aplicado al rey ciego, y la noticia que recibe podría alegrarlo: el mejor arquero del bando enemigo se niega a combatir. Los versos siguientes le quitarán esa esperanza.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 10, "hablante": "sanjaya", "sa": ["तमुवाच हृषीकेशः प्रहसन्निव भारत ।", "सेनयोरुभयोर्मध्ये विषीदन्तमिदं वचः ॥१०॥"], "iast": ["tam uvāca hṛṣīkeśaḥ prahasann iva bhārata", "senayor ubhayor madhye viṣīdantam idaṃ vacaḥ"], "rojas": [], "t": "<span class=\"vt-parte\">Y a él, que desfallecía entre los dos ejércitos, <a class=\"t\" href=\"glosario.html#hrsikesa\" data-t=\"hrsikesa\">Hṛṣīkeśa</a>, como sonriendo, oh <a class=\"t\" href=\"glosario.html#bharata\" data-t=\"bharata\">Bhārata</a>, le dirigió estas palabras:</span>", "palabras": [{"iast": "tam", "sa": "तम्", "gram": "ac. sg. m. pron.", "es": "a él"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo"}, {"iast": "hṛṣīkeśaḥ", "sa": "हृषीकेशः", "gram": "nom. sg. m.", "es": "Hṛṣīkeśa", "ref": "hrsikesa"}, {"iast": "prahasan", "sa": "प्रहसन्", "gram": "nom. sg. m. part. pres.", "es": "sonriendo", "analisis": "pra-√has (reír, sonreír)"}, {"iast": "iva", "sa": "इव", "gram": "ind.", "es": "como"}, {"iast": "bhārata", "sa": "भारत", "gram": "voc. sg. m.", "es": "oh Bhārata", "ref": "bharata"}, {"iast": "senayoḥ", "sa": "सेनयोः", "gram": "gen. du. f.", "es": "de los dos ejércitos"}, {"iast": "ubhayoḥ", "sa": "उभयोः", "gram": "gen. du. f. pron.", "es": "de ambos"}, {"iast": "madhye", "sa": "मध्ये", "gram": "loc. sg. n.", "es": "en medio"}, {"iast": "viṣīdantam", "sa": "विषीदन्तम्", "gram": "ac. sg. m. part. pres.", "es": "que desfallecía", "ref": "visada"}, {"iast": "idam", "sa": "इदम्", "gram": "ac. sg. n. pron.", "es": "estas"}, {"iast": "vacaḥ", "sa": "वचः", "gram": "ac. sg. n.", "es": "palabras", "analisis": "de √vac (hablar)"}], "nota": "<p>La escena vuelve al lugar que Arjuna había elegido en <a class=\"vref\" href=\"capitulo-01.html#v21\" data-v=\"1.21\">1.21</a>: «entre los dos ejércitos». Allí, y no en un retiro apartado, se pronuncia toda la enseñanza que comienza en el verso siguiente.</p><p><em>Prahasann iva</em>, «como sonriendo»: el <em>iva</em> atenúa el gesto. La sonrisa de Kṛṣṇa contrasta con el llanto de Arjuna y anuncia el tono del discurso: no la compasión que se contagia, sino la calma de quien ve la situación entera. El vocativo <em>bhārata</em> se dirige de nuevo a Dhṛtarāṣṭra.</p>", "interp": [{"titulo": "El pesar y el extravío, semillas del saṃsāra", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> no comenta los versos anteriores uno por uno: su comentario empieza aquí, con una larga introducción en la que establece que todo lo narrado desde <a class=\"vref\" href=\"capitulo-01.html#v2\" data-v=\"1.2\">1.2</a> hasta <a class=\"vref\" href=\"capitulo-02.html#v9\" data-v=\"2.9\">2.9</a> debe entenderse como la exposición de cómo nacen el pesar (<a class=\"t\" href=\"glosario.html#soka\" data-t=\"soka\"><em>śoka</em></a>) y el extravío (<a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\"><em>moha</em></a>), que considera la semilla del <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">saṃsāra</a>. Su remedio no es otro que el conocimiento del <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">ātman</a>, y para Śaṅkara ese conocimiento va precedido por la renuncia a toda acción. En este punto discute largamente la tesis de quienes sostienen que la liberación se alcanza combinando conocimiento y obras rituales, que él rechaza.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La enseñanza como respuesta a una entrega", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, Kṛṣṇa empieza a hablar porque Arjuna, confundido sobre el <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a>, se ha refugiado en él (<a class=\"vref\" href=\"capitulo-02.html#v7\" data-v=\"2.7\">2.7</a>). Su extravío no cesará sin dos conocimientos: el de la verdadera naturaleza del <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">ātman</a>, distinto del cuerpo, y el de que su deber propio, combatir, realizado sin buscar el fruto, es el medio para alcanzar ese sí-mismo. Por eso la enseñanza que empieza en <a class=\"vref\" href=\"capitulo-02.html#v12\" data-v=\"2.12\">2.12</a> y llega hasta <a class=\"vref\" href=\"capitulo-18.html#v66\" data-v=\"18.66\">18.66</a> trata de la naturaleza del sí-mismo y del Señor y de los caminos de la acción, el conocimiento y la devoción (<em>bhakti</em>).</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "¿Por qué sonríe?", "html": "<p>Los comentaristas dan varias razones de la sonrisa. Para unos expresa la serenidad del maestro ante una angustia que sabe pasajera; para otros, una leve ironía ante la contradicción de Arjuna, que vino a combatir y ahora habla como un renunciante, y que ofrece razones de sabio mientras llora. El <em>iva</em>, «como», impide decidir: es apenas un esbozo de sonrisa.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 11, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "अशोच्यानन्वशोचस्त्वं प्रज्ञावादांश्च भाषसे ।", "गतासूनगतासूंश्च नानुशोचन्ति पण्डिताः ॥११॥"], "iast": ["śrī-bhagavān uvāca", "aśocyān anvaśocas tvaṃ prajñā-vādāṃś ca bhāṣase", "gatāsūn agatāsūṃś ca nānuśocanti paṇḍitāḥ"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Te afliges por quienes no hay por qué afligirse, y hablas con palabras de sabio. Los sabios no se afligen ni por los que han muerto ni por los que viven.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el Señor bienaventurado", "ref": "bhagavan", "analisis": "śrī (esplendor, fortuna) + bhagavat (el que posee bhaga, la fortuna: el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "aśocyān", "sa": "अशोच्यान्", "gram": "ac. pl. m. gerundivo", "es": "a quienes no hay por qué llorar", "analisis": "a- (negación) + śocya, gerundivo de √śuc (afligirse)"}, {"iast": "anvaśocaḥ", "sa": "अन्वशोचः", "gram": "2 sg. impf. act.", "es": "te has afligido", "analisis": "anu-√śuc (lamentarse por alguien)"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "prajñā-vādān", "sa": "प्रज्ञावादान्", "gram": "ac. pl. m. comp.", "es": "palabras de sabio", "analisis": "prajñā (sabiduría) + vāda (dicho, discurso; √vad)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "bhāṣase", "sa": "भाषसे", "gram": "2 sg. pres. med.", "es": "hablas, dices", "analisis": "√bhāṣ (hablar)"}, {"iast": "gata-asūn", "sa": "गतासून्", "gram": "ac. pl. m. comp.", "es": "a los que han muerto", "analisis": "gata (ido; √gam) + asu (aliento vital): «aquellos cuyo aliento se ha ido»"}, {"iast": "agata-asūn", "sa": "अगतासून्", "gram": "ac. pl. m. comp.", "es": "a los que viven", "analisis": "a-gata (no ido) + asu: «aquellos cuyo aliento no se ha ido»"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "anuśocanti", "sa": "अनुशोचन्ति", "gram": "3 pl. pres. act.", "es": "se afligen", "analisis": "anu-√śuc"}, {"iast": "paṇḍitāḥ", "sa": "पण्डिताः", "gram": "nom. pl. m.", "es": "los sabios", "analisis": "paṇḍita, «docto, instruido»"}], "nota": "<p>Con este verso empieza la enseñanza propiamente dicha. Es también la primera vez que Kṛṣṇa habla como hablante del verso: su única frase anterior (<a class=\"vref\" href=\"capitulo-01.html#v25\" data-v=\"1.25\">1.25</a>) venía citada por Saṃjaya. La línea <em>śrī-bhagavān uvāca</em>, «el Señor bienaventurado dijo», encabezará desde ahora casi todas sus intervenciones.</p><p><em>Prajñā-vādān bhāṣase</em> es irónico: Arjuna ha hablado como un sabio, con argumentos sobre el <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a> de las familias (<a class=\"vref\" href=\"capitulo-01.html#v40\" data-v=\"1.40\">1.40</a>–<a class=\"vref\" href=\"capitulo-01.html#v44\" data-v=\"1.44\">1.44</a>), pero su aflicción muestra que no lo es. <em>Gatāsu</em>, «el de aliento ido», es una manera tradicional de nombrar al muerto.</p>", "interp": [{"titulo": "Donde empieza el comentario", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> empieza aquí su comentario verso a verso. En la introducción a este pasaje sostiene que el pesar y el extravío (<em>śoka</em> y <em>moha</em>) que Arjuna acaba de mostrar son la semilla del <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">saṃsāra</a>, y que sólo los elimina el conocimiento del sí-mismo, precedido, según él, de la renuncia a toda acción. Por eso la enseñanza no empieza por el deber, sino por el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">ātman</a>.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Una enseñanza en dos tiempos", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee el pasaje como el comienzo de una enseñanza en dos partes: primero, la verdadera naturaleza del sí-mismo, distinto del cuerpo; después, el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a> de la acción como medio para realizarlo. El pesar de Arjuna nace de no distinguir el sí-mismo del cuerpo, y eso es lo primero que Kṛṣṇa corrige.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "El primer rasgo del sabio", "html": "<p><em>Paṇḍita</em>, «docto», es quien sabe. El primer rasgo que Kṛṣṇa le atribuye no es una doctrina, sino una actitud: no afligirse. Todo lo que sigue hasta <a class=\"vref\" href=\"capitulo-02.html#v30\" data-v=\"2.30\">2.30</a> es la justificación de esa actitud.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 12, "hablante": "krsna", "sa": ["न त्वेवाहं जातु नासं न त्वं नेमे जनाधिपाः ।", "न चैव न भविष्यामः सर्वे वयमतः परम् ॥१२॥"], "iast": ["na tv evāhaṃ jātu nāsaṃ na tvaṃ neme janādhipāḥ", "na caiva na bhaviṣyāmaḥ sarve vayam ataḥ param"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Nunca hubo un tiempo en que yo no existiera, ni tú, ni estos reyes; ni dejaremos de existir ninguno de nosotros de aquí en adelante.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero, en verdad"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "ciertamente, precisamente"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "jātu", "sa": "जातु", "gram": "ind.", "es": "jamás, en algún momento"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "āsam", "sa": "आसम्", "gram": "1 sg. impf. act.", "es": "existí, era", "analisis": "√as (ser)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ime", "sa": "इमे", "gram": "nom. pl. m. pron.", "es": "estos"}, {"iast": "jana-adhipāḥ", "sa": "जनाधिपाः", "gram": "nom. pl. m. comp.", "es": "soberanos de hombres, reyes", "analisis": "jana (gente) + adhipa (señor)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "ciertamente, precisamente"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "bhaviṣyāmaḥ", "sa": "भविष्यामः", "gram": "1 pl. fut. act.", "es": "existiremos, seremos", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "sarve", "sa": "सर्वे", "gram": "nom. pl. m. adj.", "es": "todos"}, {"iast": "vayam", "sa": "वयम्", "gram": "nom. pl. pron.", "es": "nosotros"}, {"iast": "ataḥ", "sa": "अतः", "gram": "ind.", "es": "de aquí"}, {"iast": "param", "sa": "परम्", "gram": "ind.", "es": "en adelante", "analisis": "ataḥ param: «de ahora en adelante»"}], "nota": "<p>La frase se construye con negaciones dobles: «no es que yo no existiera…», «no es que no vayamos a existir…». El verso abarca a la vez el pasado y el futuro, y a tres sujetos: Kṛṣṇa, Arjuna y los reyes que van a morir en la batalla. Esa enumeración, aparentemente inocente, es uno de los puntos más discutidos por los comentaristas.</p>", "interp": [{"titulo": "Plural sólo por los cuerpos", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> advierte que el plural «nosotros» se dice siguiendo la diferencia de los cuerpos, no porque haya varios sí-mismos: el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">ātman</a> es uno y el mismo en todos. Lo que el verso afirma es su eternidad en los tres tiempos, no la pluralidad de los seres.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La pluralidad es real", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> hace de este verso uno de sus argumentos principales contra el <a class=\"t\" href=\"glosario.html#advaita\" data-t=\"advaita\">Advaita</a>. Quien habla es el Señor, libre de toda ignorancia; si la distinción entre él, Arjuna y los reyes fuera fruto de la ignorancia, no podría afirmarla al enseñar la verdad. La diferencia entre el Señor y los sí-mismos individuales, y la de éstos entre sí, es por tanto real (<em>pāramārthika</em>) y natural: no la producen condicionamientos externos, como quería Bhāskara, ni la ignorancia, como sostiene el Advaita.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "La diferencia eterna", "html": "<p>La escuela de <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, para la que es eterna la diferencia entre Dios y las almas y entre las almas mismas, llega a una conclusión semejante a la de Rāmānuja. Madhva lee el verso como un argumento por analogía: así como el Señor es eterno, según enseñan todas las Upaniṣads, también lo son Arjuna y los reyes. Su comentarista Jayatīrtha precisa que aquí el Señor enseña la diferencia de las almas entre sí y respecto de Dios, y anuncia la refutación de Śaṅkara, para quien el plural se dice sólo por los cuerpos.</p>", "trad": "dvaita", "tradNombre": "Dvaita"}, {"titulo": "La persona no se disuelve", "html": "<p>En la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, Prabhupāda insiste en que el verso refuta la idea de que la individualidad se disuelva en la liberación: Kṛṣṇa y las almas conservan eternamente su identidad personal, y por eso la relación de amor entre ellas tampoco termina.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-que-habita-el-cuerpo"}, {"n": 13, "hablante": "krsna", "sa": ["देहिनोऽस्मिन्यथा देहे कौमारं यौवनं जरा ।", "तथा देहान्तरप्राप्तिर्धीरस्तत्र न मुह्यति ॥१३॥"], "iast": ["dehino 'smin yathā dehe kaumāraṃ yauvanaṃ jarā", "tathā dehāntara-prāptir dhīras tatra na muhyati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Así como el que habita el cuerpo pasa en este cuerpo por la niñez, la juventud y la vejez, así también pasa a otro cuerpo; el sabio sereno no se extravía por ello.</span>", "palabras": [{"iast": "dehinaḥ", "sa": "देहिनः", "gram": "gen. sg. m.", "es": "del que habita el cuerpo", "ref": "dehin", "analisis": "dehin, «que tiene cuerpo», de deha (cuerpo)"}, {"iast": "asmin", "sa": "अस्मिन्", "gram": "loc. sg. m. pron.", "es": "en este"}, {"iast": "yathā", "sa": "यथा", "gram": "ind.", "es": "así como"}, {"iast": "dehe", "sa": "देहे", "gram": "loc. sg. m.", "es": "cuerpo"}, {"iast": "kaumāram", "sa": "कौमारम्", "gram": "nom. sg. n.", "es": "la niñez", "analisis": "derivado de kumāra (niño)"}, {"iast": "yauvanam", "sa": "यौवनम्", "gram": "nom. sg. n.", "es": "la juventud", "analisis": "derivado de yuvan (joven)"}, {"iast": "jarā", "sa": "जरा", "gram": "nom. sg. f.", "es": "la vejez", "analisis": "√jṝ (envejecer, desgastarse)"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así también"}, {"iast": "deha-antara-prāptiḥ", "sa": "देहान्तरप्राप्तिः", "gram": "nom. sg. f. comp.", "es": "el paso a otro cuerpo", "analisis": "deha (cuerpo) + antara (otro) + prāpti (llegada, obtención; pra-√āp)"}, {"iast": "dhīraḥ", "sa": "धीरः", "gram": "nom. sg. m. adj.", "es": "el sereno, el sabio", "analisis": "dhīra, «firme, sensato»"}, {"iast": "tatra", "sa": "तत्र", "gram": "ind.", "es": "en eso, por ello"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "muhyati", "sa": "मुह्यति", "gram": "3 sg. pres. act.", "es": "se extravía", "analisis": "√muh (confundirse), de donde moha (extravío)"}], "nota": "<p>Primera aparición de <em>dehin</em>, «el que tiene cuerpo», el término con que la Gītā nombra al sí-mismo en cuanto habita un cuerpo (<a class=\"t\" href=\"glosario.html#dehin\" data-t=\"dehin\">dehin</a>). El verso no dice «el alma está en el cuerpo» sino, literalmente, «para el que tiene cuerpo, en este cuerpo, hay niñez, juventud y vejez»: el cambio pertenece al cuerpo, y el que lo vive permanece.</p><p><em>Dhīra</em>, «firme, sensato», es el adjetivo que la Gītā asocia una y otra vez al sabio; su contrario es el que se extravía (<em>muhyati</em>), de la misma raíz que <em>moha</em>, la confusión de Arjuna.</p>", "interp": [{"titulo": "Un argumento de la experiencia", "html": "<p>Los comentaristas subrayan el método: Kṛṣṇa parte de algo que todos han vivido. Nadie se considera otra persona por haber dejado de ser niño, aunque el cuerpo haya cambiado por completo; lo que permanece a través de las edades es el que las vive. La muerte sería un cambio de la misma clase, sólo que más amplio, y quien lo comprende no tiene por qué extraviarse.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-que-habita-el-cuerpo"}, {"n": 14, "hablante": "krsna", "sa": ["मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः ।", "आगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत ॥१४॥"], "iast": ["mātrā-sparśās tu kaunteya śītoṣṇa-sukha-duḥkha-dāḥ", "āgamāpāyino 'nityās tāṃs titikṣasva bhārata"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero los contactos de los sentidos con sus objetos, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, que traen frío y calor, placer y dolor, vienen y se van: son pasajeros. Sopórtalos, oh <a class=\"t\" href=\"glosario.html#bharata\" data-t=\"bharata\">Bhārata</a>.</span>", "palabras": [{"iast": "mātrā-sparśāḥ", "sa": "मात्रास्पर्शाः", "gram": "nom. pl. m. comp.", "es": "los contactos de los sentidos con sus objetos", "analisis": "mātrā (medida: los sentidos, que «miden» los objetos, o los objetos mismos) + sparśa (contacto; √spṛś)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero, en verdad"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh Kaunteya", "ref": "kaunteya", "analisis": "«hijo de Kuntī»"}, {"iast": "śīta-uṣṇa-sukha-duḥkha-dāḥ", "sa": "शीतोष्णसुखदुःखदाः", "gram": "nom. pl. m. comp.", "es": "que traen frío y calor, placer y dolor", "analisis": "śīta (frío) + uṣṇa (calor) + sukha (placer) + duḥkha (dolor) + -da (que da; √dā)"}, {"iast": "āgama-apāyinaḥ", "sa": "आगमापायिनः", "gram": "nom. pl. m. comp.", "es": "que vienen y se van", "analisis": "āgama (llegada; ā-√gam) + apāyin (que se marcha; apa-√i)"}, {"iast": "anityāḥ", "sa": "अनित्याः", "gram": "nom. pl. m. adj.", "es": "pasajeros", "analisis": "a- (negación) + nitya (permanente)"}, {"iast": "tān", "sa": "तान्", "gram": "ac. pl. m. pron.", "es": "a ellos"}, {"iast": "titikṣasva", "sa": "तितिक्षस्व", "gram": "2 sg. impv. med. desid.", "es": "sopórtalos", "ref": "titiksa", "analisis": "desiderativo de √tij (soportar): «procura soportar»"}, {"iast": "bhārata", "sa": "भारत", "gram": "voc. sg. m.", "es": "oh Bhārata", "ref": "bharata", "analisis": "«descendiente de Bharata»"}], "nota": "<p><em>Mātrā-sparśa</em> es una expresión técnica de sentido discutido. <em>Mātrā</em> significa «medida»: para unos son los sentidos, con los que se «miden» los objetos; para otros, los objetos mismos, o los elementos sutiles de que están hechos. En cualquier caso, se trata del contacto entre los sentidos y lo que perciben, del que nacen las sensaciones de frío y calor, placer y dolor.</p><p><em>Titikṣasva</em> es un desiderativo («procura soportar») de la raíz que da <em>titikṣā</em>, la <a class=\"t\" href=\"glosario.html#titiksa\" data-t=\"titiksa\">tolerancia</a>, virtud que la tradición pondrá entre las primeras exigencias del camino espiritual. Kṛṣṇa no pide que Arjuna deje de sentir, sino que no se deje arrastrar por lo que siente.</p>", "interp": [{"titulo": "Una virtud del aspirante", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende <em>mātrā</em> como los sentidos —aquello con que se «miden» los objetos— y <em>sparśa</em> como su contacto con los objetos. La tradición <a class=\"t\" href=\"glosario.html#advaita\" data-t=\"advaita\">advaita</a> cuenta la tolerancia (<em>titikṣā</em>) entre las seis virtudes que se exigen a quien aspira a la liberación, junto a la calma, el dominio de los sentidos, la abstención, la fe y la concentración.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "¿Una ética estoica?", "html": "<p>Muchos lectores modernos han comparado esta disciplina con la de los estoicos: distinguir lo que depende de uno de lo que viene y va, y no dejarse arrastrar por ello. La diferencia está en el fundamento: en la Gītā la ecuanimidad no se apoya en una razón universal, sino en el conocimiento de un sí-mismo al que los contrarios no alcanzan (<a class=\"vref\" href=\"capitulo-02.html#v16\" data-v=\"2.16\">2.16</a>–<a class=\"vref\" href=\"capitulo-02.html#v25\" data-v=\"2.25\">2.25</a>).</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "soportar-los-contrarios"}, {"n": 15, "hablante": "krsna", "sa": ["यं हि न व्यथयन्त्येते पुरुषं पुरुषर्षभ ।", "समदुःखसुखं धीरं सोऽमृतत्वाय कल्पते ॥१५॥"], "iast": ["yaṃ hi na vyathayanty ete puruṣaṃ puruṣarṣabha", "sama-duḥkha-sukhaṃ dhīraṃ so 'mṛtatvāya kalpate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pues el hombre al que estos contactos no perturban, oh <a class=\"t\" href=\"glosario.html#purusarsabha\" data-t=\"purusarsabha\">Puruṣarṣabha</a>, igual en el dolor y en el placer, sereno, ése está preparado para la inmortalidad.</span>", "palabras": [{"iast": "yam", "sa": "यम्", "gram": "ac. sg. m. pron.", "es": "al que"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "vyathayanti", "sa": "व्यथयन्ति", "gram": "3 pl. pres. act. caus.", "es": "perturban, afligen", "analisis": "causativo de √vyath (temblar, sufrir)"}, {"iast": "ete", "sa": "एते", "gram": "nom. pl. m. pron.", "es": "estos (contactos)"}, {"iast": "puruṣam", "sa": "पुरुषम्", "gram": "ac. sg. m.", "es": "hombre", "analisis": "aquí, simplemente «hombre, persona»"}, {"iast": "puruṣa-ṛṣabha", "sa": "पुरुषर्षभ", "gram": "voc. sg. m. comp.", "es": "oh toro entre los hombres", "ref": "purusarsabha", "analisis": "puruṣa (hombre) + ṛṣabha (toro)"}, {"iast": "sama-duḥkha-sukham", "sa": "समदुःखसुखम्", "gram": "ac. sg. m. comp.", "es": "igual en el dolor y en el placer", "analisis": "sama (igual) + duḥkha (dolor) + sukha (placer)"}, {"iast": "dhīram", "sa": "धीरम्", "gram": "ac. sg. m. adj.", "es": "sereno, sabio"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "amṛtatvāya", "sa": "अमृतत्वाय", "gram": "dat. sg. n.", "es": "para la inmortalidad", "analisis": "a-mṛta (no muerto) + -tva (sufijo abstracto)"}, {"iast": "kalpate", "sa": "कल्पते", "gram": "3 sg. pres. med.", "es": "es apto, está preparado", "analisis": "√kḷp (ser apto, convenir)"}], "nota": "<p><em>Sama</em>, «igual», anuncia uno de los conceptos centrales del capítulo: la ecuanimidad (<em>samatva</em>), que en <a class=\"vref\" href=\"capitulo-02.html#v48\" data-v=\"2.48\">2.48</a> se convertirá en la definición misma del <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>. El vocativo <em>puruṣarṣabha</em>, «toro entre los hombres», no es casual: Kṛṣṇa apela a la hombría de Arjuna justo cuando le pide firmeza.</p>", "interp": [{"titulo": "La inmortalidad es la liberación", "html": "<p>Los comentaristas clásicos entienden la «inmortalidad» (<em>amṛtatva</em>) como la liberación (<a class=\"t\" href=\"glosario.html#moksa\" data-t=\"moksa\">mokṣa</a>) y no como una larga vida en el cielo: quien ya no es zarandeado por el placer y el dolor está maduro para salir del <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">ciclo de renacimientos</a>.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "soportar-los-contrarios"}, {"n": 16, "hablante": "krsna", "sa": ["नासतो विद्यते भावो नाभावो विद्यते सतः ।", "उभयोरपि दृष्टोऽन्तस्त्वनयोस्तत्त्वदर्शिभिः ॥१६॥"], "iast": ["nāsato vidyate bhāvo nābhāvo vidyate sataḥ", "ubhayor api dṛṣṭo 'ntas tv anayos tattva-darśibhiḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Lo que no es no llega a ser, y lo que es no deja de ser: los que ven la realidad han visto la verdad última de uno y otro.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "asataḥ", "sa": "असतः", "gram": "gen. sg. n. part.", "es": "de lo que no es", "ref": "sat-asat", "analisis": "a- (negación) + sat, participio presente de √as (ser)"}, {"iast": "vidyate", "sa": "विद्यते", "gram": "3 sg. pres. pas.", "es": "hay, se da", "analisis": "√vid (hallar); en pasiva, «encontrarse, existir»"}, {"iast": "bhāvaḥ", "sa": "भावः", "gram": "nom. sg. m.", "es": "llegar a ser, existencia", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "abhāvaḥ", "sa": "अभावः", "gram": "nom. sg. m.", "es": "dejar de ser, inexistencia", "analisis": "a- (negación) + bhāva"}, {"iast": "vidyate", "sa": "विद्यते", "gram": "3 sg. pres. pas.", "es": "hay, se da"}, {"iast": "sataḥ", "sa": "सतः", "gram": "gen. sg. n. part.", "es": "de lo que es", "ref": "sat-asat", "analisis": "participio presente de √as (ser)"}, {"iast": "ubhayoḥ", "sa": "उभयोः", "gram": "gen. du.", "es": "de ambos"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "dṛṣṭaḥ", "sa": "दृष्टः", "gram": "nom. sg. m. ppp", "es": "ha sido visto", "analisis": "√dṛś (ver)"}, {"iast": "antaḥ", "sa": "अन्तः", "gram": "nom. sg. m.", "es": "el fondo, la verdad última", "analisis": "anta, «fin, límite»; aquí, «conclusión, naturaleza última»"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero, en verdad"}, {"iast": "anayoḥ", "sa": "अनयोः", "gram": "gen. du. pron.", "es": "de estos dos"}, {"iast": "tattva-darśibhiḥ", "sa": "तत्त्वदर्शिभिः", "gram": "instr. pl. m. comp.", "es": "por los que ven la realidad", "analisis": "tattva («lo que es así»: la realidad; tat + -tva) + darśin (que ve; √dṛś)"}], "nota": "<p>Uno de los versos más comentados de la Gītā, y de los más difíciles. Las palabras son sencillas —<em>sat</em>, «lo que es», y <em>asat</em>, «lo que no es» (<a class=\"t\" href=\"glosario.html#sat-asat\" data-t=\"sat-asat\">sat y asat</a>)—, pero no está claro qué designan. Para unos, lo real frente a lo irreal; para otros, lo imperecedero frente a lo perecedero. La traducción mantiene la ambigüedad del original.</p><p><em>Anta</em>, literalmente «fin, límite», se toma aquí en el sentido de «conclusión»: los que ven la realidad han llegado hasta el fondo de la cuestión.</p>", "interp": [{"titulo": "Lo real y lo aparente", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, lo que «no es» son el frío, el calor y todo lo que tiene causa: lo que cambia y se percibe como objeto no tiene realidad propia, como el espejismo. Lo que «es» es el <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, la pura existencia, que no puede dejar de ser. El verso se convierte así en una de las bases de la distinción advaita entre la realidad absoluta y la apariencia.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Lo perecedero y lo imperecedero", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee <em>asat</em> y <em>sat</em> sin la idea de ilusión: <em>asat</em> es el cuerpo, que por naturaleza perece, y <em>sat</em> el sí-mismo, que por naturaleza no perece. Que el cuerpo «no sea» significa que es destructible, no que sea irreal.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Una idea de las Upaniṣads", "html": "<p>El verso recoge una idea de las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a>. En la <em>Chāndogya Upaniṣad</em> (6.2.1–2), el sabio Uddālaka enseña a su hijo que al principio sólo existía el ser, y pregunta cómo podría el ser nacer del no-ser. Los estudiosos modernos han comparado también el verso con el poema de Parménides: lo que es, es, y lo que no es, no es.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Lo irreal no tiene existencia, y a lo real no le falta nunca: quienes ven la verdad han conocido el fondo de ambos.", "nota": "<p>Si <em>asat</em> y <em>sat</em> se toman como «lo irreal» y «lo real», el verso enuncia una tesis sobre el ser: lo cambiante (frío y calor, placer y dolor, el cuerpo) no es plenamente real; el sí-mismo, sí. Es la lectura que desarrolla el <a class=\"t\" href=\"glosario.html#advaita\" data-t=\"advaita\">Advaita</a>.</p>"}, {"html": "Lo perecedero no permanece, y lo imperecedero no perece: quienes ven la verdad han conocido el fondo de ambos.", "nota": "<p>Otras lecturas no oponen lo real a lo irreal, sino lo que perece a lo que permanece: <em>asat</em> sería el cuerpo, de naturaleza perecedera, y <em>sat</em> el sí-mismo. Así lo entiende <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, para quien el mundo y los cuerpos son plenamente reales, aunque cambiantes. La traducción principal mantiene la ambigüedad del original («lo que no es», «lo que es»).</p>"}], "ens": "lo-que-no-muere"}, {"n": 17, "hablante": "krsna", "sa": ["अविनाशि तु तद्विद्धि येन सर्वमिदं ततम् ।", "विनाशमव्ययस्यास्य न कश्चित्कर्तुमर्हति ॥१७॥"], "iast": ["avināśi tu tad viddhi yena sarvam idaṃ tatam", "vināśam avyayasyāsya na kaścit kartum arhati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Sabe que es indestructible aquello por lo que todo esto está penetrado: nadie puede causar la destrucción de lo imperecedero.</span>", "palabras": [{"iast": "avināśi", "sa": "अविनाशि", "gram": "ac. sg. n. adj.", "es": "indestructible", "analisis": "a- (negación) + vināśin (perecedero; vi-√naś)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero, en verdad"}, {"iast": "tat", "sa": "तत्", "gram": "ac. sg. n. pron.", "es": "eso"}, {"iast": "viddhi", "sa": "विद्धि", "gram": "2 sg. impv. act.", "es": "sabe", "analisis": "√vid (saber)"}, {"iast": "yena", "sa": "येन", "gram": "instr. sg. n. pron.", "es": "por lo que"}, {"iast": "sarvam", "sa": "सर्वम्", "gram": "nom. sg. n. adj.", "es": "todo"}, {"iast": "idam", "sa": "इदम्", "gram": "nom. sg. n. pron.", "es": "esto"}, {"iast": "tatam", "sa": "ततम्", "gram": "nom. sg. n. ppp", "es": "penetrado, extendido", "analisis": "√tan (extender)"}, {"iast": "vināśam", "sa": "विनाशम्", "gram": "ac. sg. m.", "es": "la destrucción", "analisis": "vi-√naś (perecer)"}, {"iast": "avyayasya", "sa": "अव्ययस्य", "gram": "gen. sg. m. adj.", "es": "de lo imperecedero", "analisis": "a- (negación) + vyaya (pérdida, gasto; vi-√i)"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. m. pron.", "es": "de éste"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "kaścit", "sa": "कश्चित्", "gram": "nom. sg. m. pron.", "es": "alguien (con na: nadie)"}, {"iast": "kartum", "sa": "कर्तुम्", "gram": "inf.", "es": "causar, hacer", "analisis": "√kṛ (hacer)"}, {"iast": "arhati", "sa": "अर्हति", "gram": "3 sg. pres. act.", "es": "puede", "analisis": "√arh (merecer, poder)"}], "nota": "<p>El sujeto pasa al neutro: ya no «el que habita el cuerpo», sino «aquello» (<em>tat</em>), como cuando las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a> hablan del <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>. «Todo esto» (<em>sarvam idam</em>) es la fórmula habitual para designar el mundo visible. Qué sea exactamente lo que está «penetrado» es objeto de discusión entre las escuelas.</p>", "interp": [{"titulo": "La conciencia que todo lo abarca", "html": "<p>Para la lectura <a class=\"t\" href=\"glosario.html#advaita\" data-t=\"advaita\">advaita</a>, «aquello por lo que todo esto está penetrado» es el <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, idéntico al sí-mismo: la conciencia en la que aparece el universo entero, y que por eso no puede ser destruida por nada de lo que aparece en ella.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El sí-mismo y la materia", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, lo que penetra «todo esto» es el sí-mismo consciente, que por su extrema sutileza impregna toda la materia inconsciente, distinta de él. Precisamente porque es más sutil que todo lo que penetra, nada de ello puede destruirlo: las armas, el agua, el fuego o el viento sólo destruyen aquello en lo que pueden penetrar.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-que-no-muere"}, {"n": 18, "hablante": "krsna", "sa": ["अन्तवन्त इमे देहा नित्यस्योक्ताः शरीरिणः ।", "अनाशिनोऽप्रमेयस्य तस्माद्युध्यस्व भारत ॥१८॥"], "iast": ["antavanta ime dehā nityasyoktāḥ śarīriṇaḥ", "anāśino 'prameyasya tasmād yudhyasva bhārata"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Se dice que estos cuerpos del morador del cuerpo tienen fin; pero él es eterno, imperecedero e inconmensurable. Por tanto, combate, oh <a class=\"t\" href=\"glosario.html#bharata\" data-t=\"bharata\">Bhārata</a>.</span>", "palabras": [{"iast": "antavantaḥ", "sa": "अन्तवन्तः", "gram": "nom. pl. m. adj.", "es": "que tienen fin, perecederos", "analisis": "anta (fin) + -vat (que posee)"}, {"iast": "ime", "sa": "इमे", "gram": "nom. pl. m. pron.", "es": "estos"}, {"iast": "dehāḥ", "sa": "देहाः", "gram": "nom. pl. m.", "es": "cuerpos"}, {"iast": "nityasya", "sa": "नित्यस्य", "gram": "gen. sg. m. adj.", "es": "del eterno"}, {"iast": "uktāḥ", "sa": "उक्ताः", "gram": "nom. pl. m. ppp", "es": "se dice que son", "analisis": "√vac (decir)"}, {"iast": "śarīriṇaḥ", "sa": "शरीरिणः", "gram": "gen. sg. m.", "es": "del morador del cuerpo", "ref": "dehin", "analisis": "śarīrin, «que tiene cuerpo» (śarīra)"}, {"iast": "anāśinaḥ", "sa": "अनाशिनः", "gram": "gen. sg. m. adj.", "es": "del que no perece", "analisis": "a- (negación) + nāśin (perecedero; √naś)"}, {"iast": "aprameyasya", "sa": "अप्रमेयस्य", "gram": "gen. sg. m. adj.", "es": "del inconmensurable", "analisis": "a- (negación) + prameya (medible, cognoscible; pra-√mā)"}, {"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. n. pron.", "es": "por tanto"}, {"iast": "yudhyasva", "sa": "युध्यस्व", "gram": "2 sg. impv. med.", "es": "combate", "analisis": "√yudh (combatir)"}, {"iast": "bhārata", "sa": "भारत", "gram": "voc. sg. m.", "es": "oh Bhārata", "ref": "bharata", "analisis": "«descendiente de Bharata»"}], "nota": "<p><em>Śarīrin</em>, «el que tiene un cuerpo (<em>śarīra</em>)», es sinónimo de <a class=\"t\" href=\"glosario.html#dehin\" data-t=\"dehin\">dehin</a>. <em>Aprameya</em> puede entenderse como «inconmensurable» o como «que no puede ser objeto de conocimiento»: <em>prameya</em> es, en la filosofía india, lo que se conoce por los medios válidos de conocimiento (<em>pramāṇa</em>), y el sí-mismo, que es el que conoce, no puede convertirse en un objeto más.</p><p>Es la primera vez que Kṛṣṇa exhorta abiertamente a combatir.</p>", "interp": [{"titulo": "«Combate» no es un mandato", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> precisa que «por tanto, combate» no ordena la guerra: Arjuna ya estaba dispuesto a combatir, y sólo el pesar lo detuvo. Kṛṣṇa no prescribe una acción nueva, sino que retira el obstáculo; lo que el verso concluye es que no hay razón para afligirse.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Un argumento que no basta solo", "html": "<p>La frase ha pesado en el siglo XX. <a class=\"t\" href=\"glosario.html#tilak\" data-t=\"tilak\">Tilak</a> vio en pasajes como éste la prueba de que la Gītā enseña a actuar en el mundo; <a class=\"t\" href=\"glosario.html#gandhi\" data-t=\"gandhi\">Gandhi</a>, que la batalla es una alegoría y que el texto no puede justificar la violencia física. Muchos lectores notan que el argumento del sí-mismo inmortal no basta por sí solo, y la propia Gītā añade enseguida otros: el deber propio (<a class=\"vref\" href=\"capitulo-02.html#v31\" data-v=\"2.31\">2.31</a>) y la acción sin apego (<a class=\"vref\" href=\"capitulo-02.html#v47\" data-v=\"2.47\">2.47</a>).</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-que-no-muere"}, {"n": 19, "hablante": "krsna", "sa": ["य एनं वेत्ति हन्तारं यश्चैनं मन्यते हतम् ।", "उभौ तौ न विजानीतो नायं हन्ति न हन्यते ॥१९॥"], "iast": ["ya enaṃ vetti hantāraṃ yaś cainaṃ manyate hatam", "ubhau tau na vijānīto nāyaṃ hanti na hanyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien lo tiene por matador y quien lo cree muerto, ninguno de los dos conoce la verdad: éste ni mata ni es muerto.</span>", "palabras": [{"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron.", "es": "el que"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a éste, lo"}, {"iast": "vetti", "sa": "वेत्ति", "gram": "3 sg. pres. act.", "es": "tiene por, considera", "analisis": "√vid (saber)"}, {"iast": "hantāram", "sa": "हन्तारम्", "gram": "ac. sg. m.", "es": "matador", "analisis": "hantṛ, nombre de agente de √han (matar)"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron.", "es": "el que"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a éste, lo"}, {"iast": "manyate", "sa": "मन्यते", "gram": "3 sg. pres. med.", "es": "cree", "analisis": "√man (pensar)"}, {"iast": "hatam", "sa": "हतम्", "gram": "ac. sg. m. ppp", "es": "muerto (matado)", "analisis": "√han (matar)"}, {"iast": "ubhau", "sa": "उभौ", "gram": "nom. du. m.", "es": "ambos"}, {"iast": "tau", "sa": "तौ", "gram": "nom. du. m. pron.", "es": "esos dos"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "vijānītaḥ", "sa": "विजानीतः", "gram": "3 du. pres. act.", "es": "conocen (la verdad)", "analisis": "vi-√jñā (discernir, conocer)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "éste"}, {"iast": "hanti", "sa": "हन्ति", "gram": "3 sg. pres. act.", "es": "mata", "analisis": "√han"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "hanyate", "sa": "हन्यते", "gram": "3 sg. pres. pas.", "es": "es matado", "analisis": "√han"}], "nota": "<p>«Lo» y «éste» se refieren al morador del cuerpo de los versos anteriores. El verso responde directamente al temor de Arjuna de matar a los suyos (<a class=\"vref\" href=\"capitulo-01.html#v35\" data-v=\"1.35\">1.35</a>): ni Arjuna, en lo que verdaderamente es, mata, ni sus parientes, en lo que verdaderamente son, mueren.</p>", "interp": [{"titulo": "Casi literal de la Kaṭha Upaniṣad", "html": "<p>El verso coincide casi palabra por palabra con la <a class=\"t\" href=\"glosario.html#katha-upanisad\" data-t=\"katha-upanisad\">Kaṭha Upaniṣad</a> (1.2.19), donde la Muerte instruye al joven Naciketas sobre lo que sobrevive al morir. La Gītā cita aquí su fuente sin nombrarla, y lo mismo hará en el verso siguiente.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-que-no-muere"}, {"n": 20, "hablante": "krsna", "sa": ["न जायते म्रियते वा कदाचिन्नायं भूत्वा भविता वा न भूयः ।", "अजो नित्यः शाश्वतोऽयं पुराणो न हन्यते हन्यमाने शरीरे ॥२०॥"], "iast": ["na jāyate mriyate vā kadācin nāyaṃ bhūtvā bhavitā vā na bhūyaḥ", "ajo nityaḥ śāśvato 'yaṃ purāṇo na hanyate hanyamāne śarīre"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Nunca nace ni muere; no es algo que haya llegado a ser y vaya a dejar de ser. No nacido, eterno, perpetuo, primordial, no muere cuando se da muerte al cuerpo.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "jāyate", "sa": "जायते", "gram": "3 sg. pres. med.", "es": "nace", "analisis": "√jan (nacer)"}, {"iast": "mriyate", "sa": "म्रियते", "gram": "3 sg. pres. med.", "es": "muere", "analisis": "√mṛ (morir)"}, {"iast": "vā", "sa": "वा", "gram": "ind.", "es": "o, ni"}, {"iast": "kadācit", "sa": "कदाचित्", "gram": "ind.", "es": "en algún momento (con na: jamás)", "analisis": "kadā (¿cuándo?) + cit (partícula indefinida)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "éste"}, {"iast": "bhūtvā", "sa": "भूत्वा", "gram": "abs.", "es": "habiendo llegado a ser", "analisis": "√bhū (llegar a ser)"}, {"iast": "bhavitā", "sa": "भविता", "gram": "3 sg. fut. act.", "es": "llegará a ser", "analisis": "futuro perifrástico de √bhū"}, {"iast": "vā", "sa": "वा", "gram": "ind.", "es": "o, ni"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "bhūyaḥ", "sa": "भूयः", "gram": "ind.", "es": "de nuevo, otra vez"}, {"iast": "ajaḥ", "sa": "अजः", "gram": "nom. sg. m. adj.", "es": "no nacido", "analisis": "a- (negación) + ja (nacido; √jan)"}, {"iast": "nityaḥ", "sa": "नित्यः", "gram": "nom. sg. m. adj.", "es": "eterno"}, {"iast": "śāśvataḥ", "sa": "शाश्वतः", "gram": "nom. sg. m. adj.", "es": "perpetuo", "analisis": "derivado de śaśvat (siempre)"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "éste"}, {"iast": "purāṇaḥ", "sa": "पुराणः", "gram": "nom. sg. m. adj.", "es": "primordial, antiguo", "analisis": "de purā (antes, antiguamente)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "hanyate", "sa": "हन्यते", "gram": "3 sg. pres. pas.", "es": "es matado"}, {"iast": "hanyamāne", "sa": "हन्यमाने", "gram": "loc. sg. n. part. pres. pas.", "es": "cuando es matado", "analisis": "√han; locativo absoluto con śarīre"}, {"iast": "śarīre", "sa": "शरीरे", "gram": "loc. sg. n.", "es": "el cuerpo"}], "nota": "<p>Cambia el metro: el verso está en <em>triṣṭubh</em>, de once sílabas por pie, más amplio y solemne que el <em>śloka</em> habitual. La Gītā lo reserva para momentos de especial peso.</p><p>La primera mitad admite varias construcciones. La que seguimos entiende: «no es que, habiendo llegado a ser, vaya a dejar de ser otra vez». Otros leen: «no es que, habiendo sido, no vaya a ser otra vez», o separan la frase en dos negaciones independientes. El sentido general es el mismo: el sí-mismo no tiene comienzo ni fin.</p>", "interp": [{"titulo": "La Gītā retoca su fuente", "html": "<p>El verso procede de la <a class=\"t\" href=\"glosario.html#katha-upanisad\" data-t=\"katha-upanisad\">Kaṭha Upaniṣad</a> (1.2.18), con dos cambios en la primera mitad. Donde la Upaniṣad dice que «el sabio» (<em>vipaścit</em>) no nace ni muere, la Gītā dice «jamás» (<em>kadācit</em>): lo que era un atributo del que conoce pasa a ser una propiedad de todo sí-mismo. La segunda mitad es idéntica.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Ninguna de las seis transformaciones", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> ve en este verso la negación de las seis transformaciones del ser (<em>ṣaḍ bhāva-vikārāḥ</em>) que afectan a todo lo que existe: nacer, existir, crecer, transformarse, decaer y perecer. Él no cita la fuente, pero la lista es la que el <em>Nirukta</em> de Yāska atribuye a Vārṣyāyaṇi. Śaṅkara la reparte entre las palabras del verso: «no nace» y «no muere» niegan el nacimiento y la muerte; <em>śāśvata</em>, la decadencia; <em>purāṇa</em>, el crecimiento; «no es muerto», la transformación. El sí-mismo no está sujeto a ninguna de ellas.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "ens": "lo-que-no-muere"}, {"n": 21, "hablante": "krsna", "sa": ["वेदाविनाशिनं नित्यं य एनमजमव्ययम् ।", "कथं स पुरुषः पार्थ कं घातयति हन्ति कम् ॥२१॥"], "iast": ["vedāvināśinaṃ nityaṃ ya enam ajam avyayam", "kathaṃ sa puruṣaḥ pārtha kaṃ ghātayati hanti kam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien lo sabe indestructible, eterno, no nacido e imperecedero, ¿cómo, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, podría ese hombre hacer matar a alguien, o matar a alguien?</span>", "palabras": [{"iast": "veda", "sa": "वेद", "gram": "3 sg. pf. act.", "es": "sabe", "analisis": "√vid (saber); perfecto con valor de presente"}, {"iast": "avināśinam", "sa": "अविनाशिनम्", "gram": "ac. sg. m. adj.", "es": "indestructible"}, {"iast": "nityam", "sa": "नित्यम्", "gram": "ac. sg. m. adj.", "es": "eterno"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron.", "es": "el que"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a éste, lo"}, {"iast": "ajam", "sa": "अजम्", "gram": "ac. sg. m. adj.", "es": "no nacido"}, {"iast": "avyayam", "sa": "अव्ययम्", "gram": "ac. sg. m. adj.", "es": "imperecedero"}, {"iast": "katham", "sa": "कथम्", "gram": "ind.", "es": "¿cómo?"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ese"}, {"iast": "puruṣaḥ", "sa": "पुरुषः", "gram": "nom. sg. m.", "es": "hombre"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha", "analisis": "«hijo de Pṛthā»"}, {"iast": "kam", "sa": "कम्", "gram": "ac. sg. m. pron.", "es": "a quién"}, {"iast": "ghātayati", "sa": "घातयति", "gram": "3 sg. pres. act. caus.", "es": "hace matar", "analisis": "causativo de √han (matar)"}, {"iast": "hanti", "sa": "हन्ति", "gram": "3 sg. pres. act.", "es": "mata"}, {"iast": "kam", "sa": "कम्", "gram": "ac. sg. m. pron.", "es": "a quién"}], "nota": "<p><em>Veda</em>, «sabe», es un perfecto con valor de presente de la raíz √vid, «saber»: la misma de la que viene el nombre de los <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Vedas</a>, «el saber».</p><p>La pregunta retórica contempla las dos formas de causar una muerte: matar con la propia mano o hacer que otro mate. Arjuna, como jefe de guerra, haría ambas cosas.</p>", "interp": [{"titulo": "El sabio no actúa", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> extrae de aquí una de sus tesis centrales. Quien conoce el sí-mismo como inmutable no puede verse como agente de nada —ni de matar ni de ninguna otra acción—, y por eso al sabio sólo le corresponde la renuncia a toda acción; las acciones prescritas son para quien todavía se identifica con el cuerpo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Saber y seguir actuando", "html": "<p><a class=\"t\" href=\"glosario.html#tilak\" data-t=\"tilak\">Tilak</a>, en su <em>Gītā-rahasya</em>, discutió esa lectura: la Gītā no pide al que sabe que deje de actuar, sino que siga actuando sin apego, por el bien del mundo. Prueba de ello, según él, es que toda la enseñanza termina con Arjuna dispuesto a hacer lo que Kṛṣṇa le dice (<a class=\"vref\" href=\"capitulo-18.html#v73\" data-v=\"18.73\">18.73</a>).</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-que-no-muere"}, {"n": 22, "hablante": "krsna", "sa": ["वासांसि जीर्णानि यथा विहाय नवानि गृह्णाति नरोऽपराणि ।", "तथा शरीराणि विहाय जीर्णान्यन्यानि संयाति नवानि देही ॥२२॥"], "iast": ["vāsāṃsi jīrṇāni yathā vihāya navāni gṛhṇāti naro 'parāṇi", "tathā śarīrāṇi vihāya jīrṇāny anyāni saṃyāti navāni dehī"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Así como un hombre deja los vestidos gastados y toma otros nuevos, así el que habita el cuerpo deja los cuerpos gastados y entra en otros nuevos.</span>", "palabras": [{"iast": "vāsāṃsi", "sa": "वासांसि", "gram": "ac. pl. n.", "es": "vestidos", "analisis": "vāsas (vestido; √vas, vestir)"}, {"iast": "jīrṇāni", "sa": "जीर्णानि", "gram": "ac. pl. n. ppp", "es": "gastados", "analisis": "√jṝ (desgastarse, envejecer)"}, {"iast": "yathā", "sa": "यथा", "gram": "ind.", "es": "así como"}, {"iast": "vihāya", "sa": "विहाय", "gram": "abs.", "es": "dejando", "analisis": "vi-√hā (abandonar)"}, {"iast": "navāni", "sa": "नवानि", "gram": "ac. pl. n. adj.", "es": "nuevos"}, {"iast": "gṛhṇāti", "sa": "गृह्णाति", "gram": "3 sg. pres. act.", "es": "toma", "analisis": "√grah (tomar)"}, {"iast": "naraḥ", "sa": "नरः", "gram": "nom. sg. m.", "es": "un hombre"}, {"iast": "aparāṇi", "sa": "अपराणि", "gram": "ac. pl. n. adj.", "es": "otros"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así"}, {"iast": "śarīrāṇi", "sa": "शरीराणि", "gram": "ac. pl. n.", "es": "cuerpos"}, {"iast": "vihāya", "sa": "विहाय", "gram": "abs.", "es": "dejando"}, {"iast": "jīrṇāni", "sa": "जीर्णानि", "gram": "ac. pl. n. ppp", "es": "gastados"}, {"iast": "anyāni", "sa": "अन्यानि", "gram": "ac. pl. n. adj.", "es": "otros"}, {"iast": "saṃyāti", "sa": "संयाति", "gram": "3 sg. pres. act.", "es": "pasa a, entra en", "analisis": "sam-√yā (ir hacia, unirse a)"}, {"iast": "navāni", "sa": "नवानि", "gram": "ac. pl. n. adj.", "es": "nuevos"}, {"iast": "dehī", "sa": "देही", "gram": "nom. sg. m.", "es": "el que habita el cuerpo", "ref": "dehin"}], "nota": "<p>Otro verso en <em>triṣṭubh</em>, y la imagen más conocida de la Gītā para hablar del renacimiento. Los dos miembros de la comparación se corresponden palabra por palabra: vestidos y cuerpos, «gastados» y «nuevos», el hombre y el que habita el cuerpo.</p>", "interp": [{"titulo": "Otras imágenes de las Upaniṣads", "html": "<p>Las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a> usan otras imágenes para el paso de un cuerpo a otro. En la <em>Bṛhadāraṇyaka Upaniṣad</em> (4.4.3–4), el sí-mismo es como la oruga que, al llegar al extremo de una brizna, se apoya en otra antes de soltar la primera, o como el orfebre que funde el oro de una figura para hacer otra más hermosa.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "ens": "lo-que-no-muere"}, {"n": 23, "hablante": "krsna", "sa": ["नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः ।", "न चैनं क्लेदयन्त्यापो न शोषयति मारुतः ॥२३॥"], "iast": ["nainaṃ chindanti śastrāṇi nainaṃ dahati pāvakaḥ", "na cainaṃ kledayanty āpo na śoṣayati mārutaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Las armas no lo cortan, el fuego no lo quema, las aguas no lo mojan, el viento no lo seca.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a éste, lo"}, {"iast": "chindanti", "sa": "छिन्दन्ति", "gram": "3 pl. pres. act.", "es": "cortan", "analisis": "√chid (cortar)"}, {"iast": "śastrāṇi", "sa": "शस्त्राणि", "gram": "nom. pl. n.", "es": "las armas", "analisis": "śastra, «instrumento cortante»"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a éste, lo"}, {"iast": "dahati", "sa": "दहति", "gram": "3 sg. pres. act.", "es": "quema", "analisis": "√dah (quemar)"}, {"iast": "pāvakaḥ", "sa": "पावकः", "gram": "nom. sg. m.", "es": "el fuego", "ref": "agni", "analisis": "«el purificador» (√pū, purificar), nombre del fuego y de Agni"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a éste, lo"}, {"iast": "kledayanti", "sa": "क्लेदयन्ति", "gram": "3 pl. pres. act. caus.", "es": "mojan", "analisis": "causativo de √klid (humedecerse)"}, {"iast": "āpaḥ", "sa": "आपः", "gram": "nom. pl. f.", "es": "las aguas"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "śoṣayati", "sa": "शोषयति", "gram": "3 sg. pres. act. caus.", "es": "seca", "analisis": "causativo de √śuṣ (secarse)"}, {"iast": "mārutaḥ", "sa": "मारुतः", "gram": "nom. sg. m.", "es": "el viento", "ref": "vayu", "analisis": "relacionado con los Maruts, dioses de la tormenta"}], "nota": "<p>Cuatro maneras de destruir algo —cortar, quemar, empapar, secar— y cuatro agentes: el hierro de las armas, el fuego, el agua y el viento. El verso siguiente repite la serie en forma de adjetivos de posibilidad.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-que-no-muere"}, {"n": 24, "hablante": "krsna", "sa": ["अच्छेद्योऽयमदाह्योऽयमक्लेद्योऽशोष्य एव च ।", "नित्यः सर्वगतः स्थाणुरचलोऽयं सनातनः ॥२४॥"], "iast": ["acchedyo 'yam adāhyo 'yam akledyo 'śoṣya eva ca", "nityaḥ sarva-gataḥ sthāṇur acalo 'yaṃ sanātanaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">No puede ser cortado, ni quemado, ni mojado, ni secado: es eterno, presente en todo, firme, inmóvil, sempiterno.</span>", "palabras": [{"iast": "acchedyaḥ", "sa": "अच्छेद्यः", "gram": "nom. sg. m. gerundivo", "es": "que no puede ser cortado", "analisis": "a- (negación) + chedya (√chid)"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "éste"}, {"iast": "adāhyaḥ", "sa": "अदाह्यः", "gram": "nom. sg. m. gerundivo", "es": "que no puede ser quemado", "analisis": "a- + dāhya (√dah)"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "éste"}, {"iast": "akledyaḥ", "sa": "अक्लेद्यः", "gram": "nom. sg. m. gerundivo", "es": "que no puede ser mojado", "analisis": "a- + kledya (√klid)"}, {"iast": "aśoṣyaḥ", "sa": "अशोष्यः", "gram": "nom. sg. m. gerundivo", "es": "que no puede ser secado", "analisis": "a- + śoṣya (√śuṣ)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "ciertamente, precisamente"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "nityaḥ", "sa": "नित्यः", "gram": "nom. sg. m. adj.", "es": "eterno"}, {"iast": "sarva-gataḥ", "sa": "सर्वगतः", "gram": "nom. sg. m. comp.", "es": "presente en todo", "analisis": "sarva (todo) + gata (ido; √gam): «que ha ido a todas partes»"}, {"iast": "sthāṇuḥ", "sa": "स्थाणुः", "gram": "nom. sg. m. adj.", "es": "firme", "analisis": "√sthā (estar de pie); como sustantivo, «poste, tronco»"}, {"iast": "acalaḥ", "sa": "अचलः", "gram": "nom. sg. m. adj.", "es": "inmóvil", "analisis": "a- + cala (que se mueve; √cal)"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "éste"}, {"iast": "sanātanaḥ", "sa": "सनातनः", "gram": "nom. sg. m. adj.", "es": "sempiterno", "analisis": "de sanā (siempre, desde antiguo)"}], "nota": "<p>Los cuatro gerundivos negativos (<em>acchedya</em>, <em>adāhya</em>, <em>akledya</em>, <em>aśoṣya</em>) van más allá del verso anterior: no sólo no lo cortan, sino que no puede ser cortado. <em>Sthāṇu</em>, «firme», designa propiamente un poste o un tronco clavado en el suelo; <em>sanātana</em>, «sempiterno», es la palabra de la que vendrá la expresión moderna <em>sanātana dharma</em>, «el dharma eterno», con que muchos hindúes nombran su religión.</p>", "interp": [{"titulo": "Omnipresente como el espacio", "html": "<p>Para el <a class=\"t\" href=\"glosario.html#advaita\" data-t=\"advaita\">Advaita</a>, <em>sarva-gata</em>, «presente en todo», se toma en sentido estricto: el sí-mismo es uno, infinito y omnipresente, como el espacio, que tampoco es cortado ni quemado por lo que sucede en él.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El sí-mismo atómico", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> glosa <em>sarva-gata</em> como «cuya naturaleza es penetrar todos los elementos (<em>tattva</em>)», porque es más sutil que todos ellos; por eso ninguno puede penetrarlo a él, y cortar, quemar, mojar o secar exige penetrar lo que se corta, se quema, se moja o se seca. En su doctrina, como después en la de <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, cada sí-mismo individual es de tamaño atómico (<em>aṇu</em>): <em>sarva-gata</em> no significa, pues, que ocupe todo el espacio.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Almas en toda la creación", "html": "<p>Prabhupāda, en la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, glosa <em>sarva-gata</em> como «omnipresente» y lo entiende como «que vive en todas partes»: hay seres vivos por toda la creación —en la tierra, en el agua, en el aire, bajo tierra y aun en el fuego—, y por eso, concluye, también en el sol.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-que-no-muere"}, {"n": 25, "hablante": "krsna", "sa": ["अव्यक्तोऽयमचिन्त्योऽयमविकार्योऽयमुच्यते ।", "तस्मादेवं विदित्वैनं नानुशोचितुमर्हसि ॥२५॥"], "iast": ["avyakto 'yam acintyo 'yam avikāryo 'yam ucyate", "tasmād evaṃ viditvainaṃ nānuśocitum arhasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Se dice que es no manifiesto, impensable, inmutable. Por tanto, sabiéndolo así, no debes afligirte.</span>", "palabras": [{"iast": "avyaktaḥ", "sa": "अव्यक्तः", "gram": "nom. sg. m. adj.", "es": "no manifiesto", "ref": "avyakta", "analisis": "a- (negación) + vyakta (manifiesto; vi-√añj)"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "éste"}, {"iast": "acintyaḥ", "sa": "अचिन्त्यः", "gram": "nom. sg. m. gerundivo", "es": "impensable", "analisis": "a- + cintya (√cint, pensar)"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "éste"}, {"iast": "avikāryaḥ", "sa": "अविकार्यः", "gram": "nom. sg. m. gerundivo", "es": "inmutable", "analisis": "a- + vikārya (que puede transformarse; vi-√kṛ)"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "éste"}, {"iast": "ucyate", "sa": "उच्यते", "gram": "3 sg. pres. pas.", "es": "se dice", "analisis": "√vac (decir)"}, {"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. n. pron.", "es": "por tanto"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "viditvā", "sa": "विदित्वा", "gram": "abs.", "es": "sabiéndolo", "analisis": "√vid (saber)"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a éste, lo"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "anuśocitum", "sa": "अनुशोचितुम्", "gram": "inf.", "es": "afligirte", "analisis": "anu-√śuc"}, {"iast": "arhasi", "sa": "अर्हसि", "gram": "2 sg. pres. act.", "es": "debes", "analisis": "√arh (merecer, deber)"}], "nota": "<p>Fin del primer argumento de Kṛṣṇa, que vuelve al punto de partida: la aflicción de Arjuna (<a class=\"vref\" href=\"capitulo-02.html#v11\" data-v=\"2.11\">2.11</a>). <em>Avyakta</em>, «no manifiesto», significa aquí que el sí-mismo no se percibe con los sentidos. En otros pasajes la misma palabra designa el principio material del cosmos en su estado latente (<a class=\"vref\" href=\"capitulo-02.html#v28\" data-v=\"2.28\">2.28</a>, <a class=\"vref\" href=\"capitulo-08.html#v18\" data-v=\"8.18\">8.18</a>) o el absoluto sin forma (<a class=\"vref\" href=\"capitulo-12.html#v1\" data-v=\"12.1\">12.1</a>–<a class=\"vref\" href=\"capitulo-12.html#v5\" data-v=\"12.5\">12.5</a>); conviene no confundir los sentidos (<a class=\"t\" href=\"glosario.html#avyakta\" data-t=\"avyakta\">avyakta</a>).</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "lo-que-no-muere"}, {"n": 26, "hablante": "krsna", "sa": ["अथ चैनं नित्यजातं नित्यं वा मन्यसे मृतम् ।", "तथापि त्वं महाबाहो नैवं शोचितुमर्हसि ॥२६॥"], "iast": ["atha cainaṃ nitya-jātaṃ nityaṃ vā manyase mṛtam", "tathāpi tvaṃ mahā-bāho naivaṃ śocitum arhasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y aun si piensas que este nace sin cesar y sin cesar muere, tampoco así, oh <a class=\"t\" href=\"glosario.html#mahabaho\" data-t=\"mahabaho\">Mahābāhu</a>, debes afligirte.</span>", "palabras": [{"iast": "atha", "sa": "अथ", "gram": "ind.", "es": "y si, ahora bien"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y, además"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a este (el que habita el cuerpo)", "ref": "dehin"}, {"iast": "nitya-jātam", "sa": "नित्यजातम्", "gram": "ac. sg. m. comp.", "es": "que nace sin cesar", "analisis": "nitya (constante, perpetuo) + jāta (nacido, ppp de √jan, nacer)"}, {"iast": "nityam", "sa": "नित्यम्", "gram": "adv.", "es": "sin cesar"}, {"iast": "vā", "sa": "वा", "gram": "ind.", "es": "o"}, {"iast": "manyase", "sa": "मन्यसे", "gram": "2 sg. pres. med.", "es": "piensas, crees", "analisis": "√man (pensar)"}, {"iast": "mṛtam", "sa": "मृतम्", "gram": "ac. sg. m. ppp", "es": "muerto, que muere", "analisis": "√mṛ (morir)"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun, incluso"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "mahā-bāho", "sa": "महाबाहो", "gram": "voc. sg. m. comp.", "es": "oh Mahābāhu, el de brazos poderosos", "ref": "mahabaho", "analisis": "mahā (grande, poderoso) + bāhu (brazo)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así, de este modo"}, {"iast": "śocitum", "sa": "शोचितुम्", "gram": "inf.", "es": "afligirse", "analisis": "√śuc (arder, afligirse); de la misma raíz que śoka, «pesar»"}, {"iast": "arhasi", "sa": "अर्हसि", "gram": "2 sg. pres. act.", "es": "debes, es propio de ti", "analisis": "√arh (merecer, ser digno de)"}], "nota": "<p>«Este» es el que habita el cuerpo (<a class=\"t\" href=\"glosario.html#dehin\" data-t=\"dehin\">dehin</a>), del que Kṛṣṇa viene hablando desde <a class=\"vref\" href=\"capitulo-02.html#v13\" data-v=\"2.13\">2.13</a>. Hasta aquí ha afirmado que no nace ni muere (<a class=\"vref\" href=\"capitulo-02.html#v20\" data-v=\"2.20\">2.20</a>); ahora concede, por hipótesis, la tesis contraria: aun si el sí-mismo naciera y muriera con cada cuerpo, la aflicción seguiría sin fundamento, por la razón que da el verso siguiente.</p><p>El estribillo <em>na… śocitum arhasi</em>, «no debes afligirte», se repite en <a class=\"vref\" href=\"capitulo-02.html#v25\" data-v=\"2.25\">2.25</a>, aquí, en <a class=\"vref\" href=\"capitulo-02.html#v27\" data-v=\"2.27\">2.27</a> y en <a class=\"vref\" href=\"capitulo-02.html#v30\" data-v=\"2.30\">2.30</a>, y cierra cada paso del argumento.</p>", "interp": [{"titulo": "Una concesión dialéctica", "html": "<p>La mayoría de los comentaristas vedánticos leen el verso como un argumento <em>a fortiori</em>: Kṛṣṇa no abandona su doctrina, sino que muestra que ni siquiera el adversario tiene motivo para el duelo. Si el yo es eterno, nada muere de verdad; si no lo es y nace y muere con el cuerpo, lo nacido ha de morir de todos modos. En ningún caso está justificada la aflicción de Arjuna. Madhusūdana Sarasvatī enumera las escuelas que podrían sostener la tesis concedida: los budistas (<em>saugata</em>), para quienes el yo es conciencia que perece a cada instante; los materialistas (<em>lokāyatika</em>), que lo identifican con el cuerpo; quienes creen que nace y muere con el cuerpo, e incluso los lógicos (<em>tārkika</em>), que llaman nacimiento y muerte a la unión de un yo eterno con un cuerpo y a su separación. Rāmānuja, sin nombrar escuela, entiende la hipótesis como la de quien identifica el yo con el cuerpo; Śaṅkara la presenta como una concesión a la opinión común. Madhva, en cambio, no ve aquí concesión alguna: el yo sigue siendo eterno, y nacer y morir significan sólo unirse a un cuerpo y separarse de él; Jayatīrtha rechaza expresamente la lectura de Śaṅkara.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 27, "hablante": "krsna", "sa": ["जातस्य हि ध्रुवो मृत्युर्ध्रुवं जन्म मृतस्य च ।", "तस्मादपरिहार्येऽर्थे न त्वं शोचितुमर्हसि ॥२७॥"], "iast": ["jātasya hi dhruvo mṛtyur dhruvaṃ janma mṛtasya ca", "tasmād aparihārye 'rthe na tvaṃ śocitum arhasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Porque para el que ha nacido la muerte es segura, y seguro es el nacimiento para el que ha muerto. Por eso no debes afligirte por lo que no se puede evitar.</span>", "palabras": [{"iast": "jātasya", "sa": "जातस्य", "gram": "gen. sg. m. ppp", "es": "del que ha nacido", "analisis": "√jan (nacer)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues, porque"}, {"iast": "dhruvaḥ", "sa": "ध्रुवः", "gram": "nom. sg. m. adj.", "es": "cierta, segura", "analisis": "√dhru (estar firme)"}, {"iast": "mṛtyuḥ", "sa": "मृत्युः", "gram": "nom. sg. m.", "es": "la muerte", "analisis": "√mṛ (morir)"}, {"iast": "dhruvam", "sa": "ध्रुवम्", "gram": "nom. sg. n. adj.", "es": "cierto, seguro"}, {"iast": "janma", "sa": "जन्म", "gram": "nom. sg. n.", "es": "el nacimiento", "analisis": "janman, de √jan (nacer)"}, {"iast": "mṛtasya", "sa": "मृतस्य", "gram": "gen. sg. m. ppp", "es": "del que ha muerto"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. pron.", "es": "por eso"}, {"iast": "aparihārye", "sa": "अपरिहार्ये", "gram": "loc. sg. m. gerundivo", "es": "inevitable", "analisis": "a (no) + pari-√hṛ (evitar, esquivar)"}, {"iast": "arthe", "sa": "अर्थे", "gram": "loc. sg. m.", "es": "en un asunto, por una cosa"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "śocitum", "sa": "शोचितुम्", "gram": "inf.", "es": "afligirte"}, {"iast": "arhasi", "sa": "अर्हसि", "gram": "2 sg. pres. act.", "es": "debes"}], "nota": "<p>Dentro de la hipótesis de <a class=\"vref\" href=\"capitulo-02.html#v26\" data-v=\"2.26\">2.26</a>, el argumento es de puro sentido común: lo que nace muere. Pero la segunda mitad del verso va más allá y da por supuesto el renacimiento: también «lo muerto» vuelve a nacer, de modo que la muerte no es un final sino un paso dentro del <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">ciclo de renacimientos</a>. El adjetivo <em>dhruva</em>, «firme, seguro», es el mismo que da nombre a la estrella polar.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ciclo-de-los-seres"}, {"n": 28, "hablante": "krsna", "sa": ["अव्यक्तादीनि भूतानि व्यक्तमध्यानि भारत ।", "अव्यक्तनिधनान्येव तत्र का परिदेवना ॥२८॥"], "iast": ["avyaktādīni bhūtāni vyakta-madhyāni bhārata", "avyakta-nidhanāny eva tatra kā paridevanā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los seres tienen un comienzo <a class=\"t\" href=\"glosario.html#avyakta\" data-t=\"avyakta\">no manifiesto</a>, un medio manifiesto, oh <a class=\"t\" href=\"glosario.html#bharata\" data-t=\"bharata\">Bhārata</a>, y un fin también no manifiesto. ¿Qué hay en ello que lamentar?</span>", "palabras": [{"iast": "avyakta-ādīni", "sa": "अव्यक्तादीनि", "gram": "nom. pl. n. comp.", "es": "cuyo comienzo no es manifiesto", "ref": "avyakta", "analisis": "a-vyakta (no manifiesto, ppp de vi-√añj, manifestar) + ādi (comienzo)"}, {"iast": "bhūtāni", "sa": "भूतानि", "gram": "nom. pl. n.", "es": "los seres", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "vyakta-madhyāni", "sa": "व्यक्तमध्यानि", "gram": "nom. pl. n. comp.", "es": "cuyo medio es manifiesto", "analisis": "vyakta (manifiesto) + madhya (medio)"}, {"iast": "bhārata", "sa": "भारत", "gram": "voc. sg. m.", "es": "oh Bhārata", "ref": "bharata"}, {"iast": "avyakta-nidhanāni", "sa": "अव्यक्तनिधनानि", "gram": "nom. pl. n. comp.", "es": "cuyo fin no es manifiesto", "ref": "avyakta", "analisis": "a-vyakta (no manifiesto) + nidhana (fin, muerte)"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "tatra", "sa": "तत्र", "gram": "ind.", "es": "en eso, ante eso"}, {"iast": "kā", "sa": "का", "gram": "nom. sg. f. pron.", "es": "¿qué?"}, {"iast": "paridevanā", "sa": "परिदेवना", "gram": "nom. sg. f.", "es": "lamento", "analisis": "pari-√dev (lamentarse)"}], "nota": "<p>Antes de nacer, los seres no se ven; después de morir, tampoco: sólo el tramo intermedio es «manifiesto» (<em>vyakta</em>), perceptible. Llorar su desaparición es lamentar que vuelvan al estado del que vinieron. <em>Avyakta</em>, «no manifiesto», será más adelante un término técnico: la naturaleza primordial de la que surgen todos los seres al comenzar el día cósmico y en la que se disuelven al caer la noche (<a class=\"vref\" href=\"capitulo-08.html#v18\" data-v=\"8.18\">8.18</a>).</p>", "interp": [{"titulo": "Un vocabulario del Sāṅkhya", "html": "<p>La pareja <em>vyakta</em>/<em>avyakta</em>, «manifiesto»/«no manifiesto», procede de la filosofía <a class=\"t\" href=\"glosario.html#sankhya\" data-t=\"sankhya\">Sāṅkhya</a>, para la que el mundo visible es la evolución de una naturaleza primordial invisible. Aquí funciona todavía en sentido corriente, como lo que se ve y lo que no; la Gītā la desarrollará en <a class=\"vref\" href=\"capitulo-08.html#v18\" data-v=\"8.18\">8.18</a>–<a class=\"vref\" href=\"capitulo-08.html#v20\" data-v=\"8.20\">8.20</a>, donde distingue además, por encima de ese no manifiesto, «otro no manifiesto, eterno», que no perece cuando perecen todos los seres.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "ciclo-de-los-seres"}, {"n": 29, "hablante": "krsna", "sa": ["आश्चर्यवत्पश्यति कश्चिदेनमाश्चर्यवद्वदति तथैव चान्यः ।", "आश्चर्यवच्चैनमन्यः शृणोति श्रुत्वाप्येनं वेद न चैव कश्चित् ॥२९॥"], "iast": ["āścarya-vat paśyati kaścid enam āścarya-vad vadati tathaiva cānyaḥ", "āścarya-vac cainam anyaḥ śṛṇoti śrutvāpy enaṃ veda na caiva kaścit"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Alguno lo ve como una maravilla; otro, de igual modo, habla de él como de una maravilla; otro oye hablar de él como de una maravilla; pero, aun habiéndolo oído, nadie lo conoce.</span>", "palabras": [{"iast": "āścarya-vat", "sa": "आश्चर्यवत्", "gram": "ind.", "es": "como una maravilla", "analisis": "āścarya (maravilla, prodigio) + -vat (como)"}, {"iast": "paśyati", "sa": "पश्यति", "gram": "3 sg. pres. act.", "es": "ve", "analisis": "√paś (ver)"}, {"iast": "kaścit", "sa": "कश्चित्", "gram": "nom. sg. m. pron.", "es": "alguno"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a este", "ref": "dehin"}, {"iast": "āścarya-vat", "sa": "आश्चर्यवत्", "gram": "ind.", "es": "como una maravilla"}, {"iast": "vadati", "sa": "वदति", "gram": "3 sg. pres. act.", "es": "habla", "analisis": "√vad (hablar)"}, {"iast": "tathā", "sa": "तथा", "gram": "ind.", "es": "así"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "también"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "anyaḥ", "sa": "अन्यः", "gram": "nom. sg. m. pron.", "es": "otro"}, {"iast": "āścarya-vat", "sa": "आश्चर्यवत्", "gram": "ind.", "es": "como una maravilla"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a este"}, {"iast": "anyaḥ", "sa": "अन्यः", "gram": "nom. sg. m. pron.", "es": "otro"}, {"iast": "śṛṇoti", "sa": "शृणोति", "gram": "3 sg. pres. act.", "es": "oye", "analisis": "√śru (oír)"}, {"iast": "śrutvā", "sa": "श्रुत्वा", "gram": "abs.", "es": "habiendo oído"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun"}, {"iast": "enam", "sa": "एनम्", "gram": "ac. sg. m. pron.", "es": "a este"}, {"iast": "veda", "sa": "वेद", "gram": "3 sg. pf. act.", "es": "conoce", "analisis": "√vid (saber); perfecto con valor de presente, la misma raíz que Veda"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "precisamente"}, {"iast": "kaścit", "sa": "कश्चित्", "gram": "nom. sg. m. pron.", "es": "nadie (con negación)"}], "nota": "<p>«Lo»: el sí-mismo que habita el cuerpo. La gradación —ver, hablar, oír— termina en una negación: ni la visión, ni la palabra, ni la escucha bastan para conocerlo.</p><p>Métrica. Es una estrofa <em>triṣṭubh</em>, de cuatro pies de once sílabas, más solemne que el <em>śloka</em> habitual. El segundo pie (<em>āścarya-vad vadati tathaiva cānyaḥ</em>) tiene doce sílabas: irregularidad frecuente en los triṣṭubh de la épica.</p>", "interp": [{"titulo": "Eco de la Kaṭha Upaniṣad", "html": "<p>El verso reelabora una estrofa de la <a class=\"t\" href=\"glosario.html#katha-upanisad\" data-t=\"katha-upanisad\">Kaṭha Upaniṣad</a> (1.2.7): del yo, «muchos ni siquiera llegan a oír hablar; muchos, aun oyendo, no lo conocen; maravilla es quien lo enseña, hábil quien lo alcanza; maravilla quien lo conoce, instruido por un maestro hábil». Como en otros pasajes del capítulo (<a class=\"vref\" href=\"capitulo-02.html#v19\" data-v=\"2.19\">2.19</a>–<a class=\"vref\" href=\"capitulo-02.html#v20\" data-v=\"2.20\">2.20</a>), la Gītā toma de esa Upaniṣad, el diálogo entre el joven Naciketas y el dios de la muerte, el lenguaje con que habla del sí-mismo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Lo que no puede ser objeto", "html": "<p>Para el <a class=\"t\" href=\"glosario.html#advaita\" data-t=\"advaita\">Advaita</a>, la dificultad no es de grado sino de principio: el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">ātman</a> es el sujeto de todo conocer y por eso no puede convertirse en un objeto más que se ve, se nombra o se oye. «Nadie lo conoce» como se conoce una cosa; sólo se lo reconoce cuando cesa la confusión entre el yo y lo que no es el yo, y entonces no queda un conocedor separado de lo conocido.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "triṣṭubh con pies de jagatī (once y doce sílabas)"}, {"n": 30, "hablante": "krsna", "sa": ["देही नित्यमवध्योऽयं देहे सर्वस्य भारत ।", "तस्मात्सर्वाणि भूतानि न त्वं शोचितुमर्हसि ॥३०॥"], "iast": ["dehī nityam avadhyo 'yaṃ dehe sarvasya bhārata", "tasmāt sarvāṇi bhūtāni na tvaṃ śocitum arhasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\"><a class=\"t\" href=\"glosario.html#dehin\" data-t=\"dehin\">El que habita el cuerpo</a> de cada uno, oh <a class=\"t\" href=\"glosario.html#bharata\" data-t=\"bharata\">Bhārata</a>, es eternamente imposible de matar. Por eso no debes afligirte por ninguno de los seres.</span>", "palabras": [{"iast": "dehī", "sa": "देही", "gram": "nom. sg. m.", "es": "el que habita el cuerpo", "ref": "dehin", "analisis": "deha (cuerpo) + -in (sufijo de posesión): «el que tiene cuerpo»"}, {"iast": "nityam", "sa": "नित्यम्", "gram": "adv.", "es": "siempre, eternamente"}, {"iast": "avadhyaḥ", "sa": "अवध्यः", "gram": "nom. sg. m. gerundivo", "es": "que no puede ser muerto", "analisis": "a (no) + vadhya (que ha de ser muerto, de √vadh, matar)"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "este"}, {"iast": "dehe", "sa": "देहे", "gram": "loc. sg. m.", "es": "en el cuerpo"}, {"iast": "sarvasya", "sa": "सर्वस्य", "gram": "gen. sg. m. pron.", "es": "de todos, de cada uno"}, {"iast": "bhārata", "sa": "भारत", "gram": "voc. sg. m.", "es": "oh Bhārata", "ref": "bharata"}, {"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. pron.", "es": "por eso"}, {"iast": "sarvāṇi", "sa": "सर्वाणि", "gram": "ac. pl. n. pron.", "es": "todos"}, {"iast": "bhūtāni", "sa": "भूतानि", "gram": "ac. pl. n.", "es": "los seres"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "śocitum", "sa": "शोचितुम्", "gram": "inf.", "es": "afligirte"}, {"iast": "arhasi", "sa": "अर्हसि", "gram": "2 sg. pres. act.", "es": "debes"}], "nota": "<p>Conclusión del primer argumento, el que va de <a class=\"vref\" href=\"capitulo-02.html#v11\" data-v=\"2.11\">2.11</a> hasta aquí: lo que hay en cada cuerpo no puede ser muerto, y por tanto no hay a quién llorar. El verso juega con <em>dehin</em> y <em>deha</em>: el que habita el cuerpo está «en el cuerpo» (<em>dehe</em>) sin ser el cuerpo. En el verso siguiente, Kṛṣṇa cambiará de terreno.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 31, "hablante": "krsna", "sa": ["स्वधर्ममपि चावेक्ष्य न विकम्पितुमर्हसि ।", "धर्म्याद्धि युद्धाच्छ्रेयोऽन्यत्क्षत्रियस्य न विद्यते ॥३१॥"], "iast": ["sva-dharmam api cāvekṣya na vikampitum arhasi", "dharmyād dhi yuddhāc chreyo 'nyat kṣatriyasya na vidyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y atendiendo también a tu <a class=\"t\" href=\"glosario.html#svadharma\" data-t=\"svadharma\">dharma propio</a>, no debes vacilar: para un <a class=\"t\" href=\"glosario.html#ksatriya\" data-t=\"ksatriya\">kṣatriya</a> no hay bien mayor que un combate conforme al <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a>.</span>", "palabras": [{"iast": "sva-dharmam", "sa": "स्वधर्मम्", "gram": "ac. sg. m. comp.", "es": "el dharma propio", "ref": "svadharma", "analisis": "sva (propio) + dharma"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "avekṣya", "sa": "अवेक्ष्य", "gram": "abs.", "es": "considerando, atendiendo a", "analisis": "ava-√īkṣ (mirar hacia, considerar)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "vikampitum", "sa": "विकम्पितुम्", "gram": "inf.", "es": "vacilar, temblar", "analisis": "vi-√kamp (temblar, estremecerse)"}, {"iast": "arhasi", "sa": "अर्हसि", "gram": "2 sg. pres. act.", "es": "debes"}, {"iast": "dharmyāt", "sa": "धर्म्यात्", "gram": "abl. sg. n. adj.", "es": "conforme al dharma", "ref": "dharma", "analisis": "derivado de dharma: «que está de acuerdo con el dharma»"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "yuddhāt", "sa": "युद्धात्", "gram": "abl. sg. n.", "es": "que un combate", "analisis": "√yudh (combatir); el ablativo es el segundo término de la comparación"}, {"iast": "śreyaḥ", "sa": "श्रेयः", "gram": "nom. sg. n.", "es": "bien mayor, algo mejor", "analisis": "śreyas, comparativo de śrī (excelencia): «lo mejor, el bien»"}, {"iast": "anyat", "sa": "अन्यत्", "gram": "nom. sg. n. pron.", "es": "otro"}, {"iast": "kṣatriyasya", "sa": "क्षत्रियस्य", "gram": "gen. sg. m.", "es": "para un kṣatriya", "ref": "ksatriya"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "vidyate", "sa": "विद्यते", "gram": "3 sg. pres. pas.", "es": "existe, se encuentra", "analisis": "√vid (encontrar); en pasiva, «hallarse, existir»"}], "nota": "<p>Aquí empieza un segundo argumento, independiente del primero, y la partícula <em>api</em>, «también», lo anuncia: además de lo que sabes sobre el sí-mismo, considera tu propio deber. Ya no se habla de lo eterno, sino de la condición concreta de Arjuna como guerrero.</p><p>La guerra es «conforme al dharma» (<em>dharmya</em>) porque, según el <a class=\"t\" href=\"glosario.html#mahabharata\" data-t=\"mahabharata\">Mahābhārata</a>, se han agotado antes los intentos de paz: los <a class=\"t\" href=\"glosario.html#pandavas\" data-t=\"pandavas\">Pāṇḍavas</a> han cumplido su destierro; Yudhiṣṭhira, por medio de Saṃjaya, se ha conformado con cinco aldeas, y Kṛṣṇa mismo, como embajador, ha acabado pidiendo para ellos sólo esas cinco aldeas, sin conseguirlo. El verbo <em>vikampitum</em>, «temblar», recuerda el estado de Arjuna al final del capítulo 1.</p>", "interp": [{"titulo": "Dos planos del argumento", "html": "<p>La estructura es clara: de <a class=\"vref\" href=\"capitulo-02.html#v11\" data-v=\"2.11\">2.11</a> a <a class=\"vref\" href=\"capitulo-02.html#v30\" data-v=\"2.30\">2.30</a>, Kṛṣṇa razona desde la verdad última (el sí-mismo no muere); de <a class=\"vref\" href=\"capitulo-02.html#v31\" data-v=\"2.31\">2.31</a> a <a class=\"vref\" href=\"capitulo-02.html#v37\" data-v=\"2.37\">2.37</a>, desde la ética del guerrero (el deber, la honra, el cielo). En <a class=\"vref\" href=\"capitulo-02.html#v39\" data-v=\"2.39\">2.39</a> él mismo resume lo anterior como la enseñanza «según el Sāṅkhya» y anuncia otra, «según el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>». Los comentaristas clásicos ven en este escalonamiento una pedagogía: el maestro ofrece primero la verdad más alta y después, para quien aún no puede vivirla, razones a su medida.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Tilak: un manifiesto de la acción", "html": "<p>Para <a class=\"t\" href=\"glosario.html#tilak\" data-t=\"tilak\">Bal Gangadhar Tilak</a>, en su <em>Gītā-rahasya</em>, versos como este son decisivos contra las lecturas que hacen de la Gītā un elogio de la renuncia al mundo: el propósito de Kṛṣṇa es que Arjuna cumpla su deber y combata. La enseñanza central sería el <a class=\"t\" href=\"glosario.html#karma-yoga\" data-t=\"karma-yoga\"><em>karma-yoga</em></a>, el yoga de la acción: la acción enérgica y desinteresada en el mundo, y el conocimiento y la devoción estarían al servicio de esa acción, no al revés.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 32, "hablante": "krsna", "sa": ["यदृच्छया चोपपन्नं स्वर्गद्वारमपावृतम् ।", "सुखिनः क्षत्रियाः पार्थ लभन्ते युद्धमीदृशम् ॥३२॥"], "iast": ["yadṛcchayā copapannaṃ svarga-dvāram apāvṛtam", "sukhinaḥ kṣatriyāḥ pārtha labhante yuddham īdṛśam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Dichosos los <a class=\"t\" href=\"glosario.html#ksatriya\" data-t=\"ksatriya\">kṣatriyas</a>, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, a quienes se les presenta, sin haberla buscado, una guerra como esta: una puerta abierta de par en par al <a class=\"t\" href=\"glosario.html#svarga\" data-t=\"svarga\">cielo</a>.</span>", "palabras": [{"iast": "yadṛcchayā", "sa": "यदृच्छया", "gram": "instr. sg. f.", "es": "por sí sola, sin buscarla", "analisis": "yad (lo que) + ṛcchā (llegada): «según llegue», «por azar»"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "upapannam", "sa": "उपपन्नम्", "gram": "ac. sg. n. ppp", "es": "venida, presentada", "analisis": "upa-√pad (llegar, presentarse)"}, {"iast": "svarga-dvāram", "sa": "स्वर्गद्वारम्", "gram": "ac. sg. n. comp.", "es": "puerta del cielo", "ref": "svarga", "analisis": "svarga (cielo) + dvāra (puerta)"}, {"iast": "apāvṛtam", "sa": "अपावृतम्", "gram": "ac. sg. n. ppp", "es": "abierta de par en par", "analisis": "apa-ā-√vṛ (descubrir, abrir)"}, {"iast": "sukhinaḥ", "sa": "सुखिनः", "gram": "nom. pl. m. adj.", "es": "dichosos", "analisis": "sukha (dicha) + -in"}, {"iast": "kṣatriyāḥ", "sa": "क्षत्रियाः", "gram": "nom. pl. m.", "es": "los kṣatriyas", "ref": "ksatriya"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "labhante", "sa": "लभन्ते", "gram": "3 pl. pres. med.", "es": "obtienen", "analisis": "√labh (obtener)"}, {"iast": "yuddham", "sa": "युद्धम्", "gram": "ac. sg. n.", "es": "una guerra, un combate"}, {"iast": "īdṛśam", "sa": "ईदृशम्", "gram": "ac. sg. n. adj.", "es": "semejante, como esta"}], "nota": "<p>Según la ética guerrera de la épica, quien muere combatiendo sin volver la espalda gana el <a class=\"t\" href=\"glosario.html#svarga\" data-t=\"svarga\">cielo</a> de Indra. Que la ocasión llegue «por sí sola» (<em>yadṛcchayā</em>) importa: Arjuna no ha provocado esta guerra, y rehusarla no sería prudencia, sino desperdiciar lo que el destino pone en sus manos.</p>", "interp": [{"titulo": "La ética del guerrero", "html": "<p>Los historiadores señalan que los argumentos de <a class=\"vref\" href=\"capitulo-02.html#v31\" data-v=\"2.31\">2.31</a>–<a class=\"vref\" href=\"capitulo-02.html#v37\" data-v=\"2.37\">2.37</a> —el deber de clase, la honra, el cielo de los caídos en combate— son los de la moral heroica de la épica y de los tratados de derecho brahmánico: las <em>Leyes de Manu</em> (7.89) prometen el cielo a los reyes que combaten con todas sus fuerzas sin volver la espalda, y Yājñavalkya (1.324), a los que mueren en la batalla sin huir. En este tramo, Kṛṣṇa habla todavía el lenguaje de la sociedad de Arjuna. La novedad de la Gītā vendrá después, cuando pida actuar sin buscar ni siquiera esas recompensas (<a class=\"vref\" href=\"capitulo-02.html#v47\" data-v=\"2.47\">2.47</a>).</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 33, "hablante": "krsna", "sa": ["अथ चेत्त्वमिमं धर्म्यं सङ्ग्रामं न करिष्यसि ।", "ततः स्वधर्मं कीर्तिं च हित्वा पापमवाप्स्यसि ॥३३॥"], "iast": ["atha cet tvam imaṃ dharmyaṃ saṅgrāmaṃ na kariṣyasi", "tataḥ sva-dharmaṃ kīrtiṃ ca hitvā pāpam avāpsyasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero si no libras este combate conforme al <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a>, entonces, abandonando tu <a class=\"t\" href=\"glosario.html#svadharma\" data-t=\"svadharma\">dharma propio</a> y tu <a class=\"t\" href=\"glosario.html#kirti\" data-t=\"kirti\">honra</a>, incurrirás en <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a>.</span>", "palabras": [{"iast": "atha", "sa": "अथ", "gram": "ind.", "es": "pero"}, {"iast": "cet", "sa": "चेत्", "gram": "ind.", "es": "si"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "imam", "sa": "इमम्", "gram": "ac. sg. m. pron.", "es": "este"}, {"iast": "dharmyam", "sa": "धर्म्यम्", "gram": "ac. sg. m. adj.", "es": "conforme al dharma", "ref": "dharma"}, {"iast": "saṅgrāmam", "sa": "सङ्ग्रामम्", "gram": "ac. sg. m.", "es": "combate, batalla"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "kariṣyasi", "sa": "करिष्यसि", "gram": "2 sg. fut. act.", "es": "harás, librarás", "analisis": "√kṛ (hacer)"}, {"iast": "tataḥ", "sa": "ततः", "gram": "ind.", "es": "entonces"}, {"iast": "sva-dharmam", "sa": "स्वधर्मम्", "gram": "ac. sg. m. comp.", "es": "el dharma propio", "ref": "svadharma"}, {"iast": "kīrtim", "sa": "कीर्तिम्", "gram": "ac. sg. f.", "es": "la honra, la buena fama", "ref": "kirti", "analisis": "√kṝt (alabar, celebrar)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "hitvā", "sa": "हित्वा", "gram": "abs.", "es": "abandonando", "analisis": "√hā (dejar, abandonar)"}, {"iast": "pāpam", "sa": "पापम्", "gram": "ac. sg. n.", "es": "el pecado", "ref": "papa"}, {"iast": "avāpsyasi", "sa": "अवाप्स्यसि", "gram": "2 sg. fut. act.", "es": "obtendrás, incurrirás en", "analisis": "ava-√āp (alcanzar, obtener)"}], "nota": "<p>Kṛṣṇa invierte el argumento de Arjuna. En el capítulo 1, Arjuna temía que matar a sus parientes le acarreara <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a> (<a class=\"vref\" href=\"capitulo-01.html#v36\" data-v=\"1.36\">1.36</a>, <a class=\"vref\" href=\"capitulo-01.html#v45\" data-v=\"1.45\">1.45</a>); ahora oye que el pecado estaría en no combatir, porque abandonaría el dharma que le corresponde. Los versos <a class=\"vref\" href=\"capitulo-02.html#v33\" data-v=\"2.33\">2.33</a>–<a class=\"vref\" href=\"capitulo-02.html#v36\" data-v=\"2.36\">2.36</a> apelan a la honra y a la vergüenza: argumentos que el propio Kṛṣṇa superará muy pronto.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 34, "hablante": "krsna", "sa": ["अकीर्तिं चापि भूतानि कथयिष्यन्ति तेऽव्ययाम् ।", "सम्भावितस्य चाकीर्तिर्मरणादतिरिच्यते ॥३४॥"], "iast": ["akīrtiṃ cāpi bhūtāni kathayiṣyanti te 'vyayām", "sambhāvitasya cākīrtir maraṇād atiricyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Además, la gente hablará de tu deshonra, una deshonra que no se borrará; y para quien ha sido honrado, la deshonra es peor que la muerte.</span>", "palabras": [{"iast": "akīrtim", "sa": "अकीर्तिम्", "gram": "ac. sg. f.", "es": "la deshonra", "ref": "kirti", "analisis": "a (no) + kīrti (honra, fama)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "además"}, {"iast": "bhūtāni", "sa": "भूतानि", "gram": "nom. pl. n.", "es": "los seres, la gente"}, {"iast": "kathayiṣyanti", "sa": "कथयिष्यन्ति", "gram": "3 pl. fut. act.", "es": "contarán, irán diciendo", "analisis": "√kath (contar, relatar)"}, {"iast": "te", "sa": "ते", "gram": "gen. sg. pron.", "es": "tuya"}, {"iast": "avyayām", "sa": "अव्ययाम्", "gram": "ac. sg. f. adj.", "es": "imperecedera, que no se borra", "analisis": "a (no) + vyaya (pérdida, desgaste), de vi-√i"}, {"iast": "sambhāvitasya", "sa": "सम्भावितस्य", "gram": "gen. sg. m. ppp", "es": "para el que ha sido honrado", "analisis": "causativo de sam-√bhū: «estimado, tenido en mucho»"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "akīrtiḥ", "sa": "अकीर्तिः", "gram": "nom. sg. f.", "es": "la deshonra", "ref": "kirti"}, {"iast": "maraṇāt", "sa": "मरणात्", "gram": "abl. sg. n.", "es": "que la muerte", "analisis": "√mṛ (morir)"}, {"iast": "atiricyate", "sa": "अतिरिच्यते", "gram": "3 sg. pres. pas.", "es": "excede, es peor", "analisis": "ati-√ric (sobrepasar)"}], "nota": "<p><em>Avyaya</em>, «imperecedero», es el mismo adjetivo que poco antes se aplicaba al sí-mismo (<a class=\"vref\" href=\"capitulo-02.html#v21\" data-v=\"2.21\">2.21</a>): ahora califica la deshonra, que tampoco muere. El juego subraya el cambio de plano: del yo eterno se ha pasado a la fama, que es lo que sobrevive al guerrero en la memoria de los demás.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 35, "hablante": "krsna", "sa": ["भयाद्रणादुपरतं मंस्यन्ते त्वां महारथाः ।", "येषां च त्वं बहुमतो भूत्वा यास्यसि लाघवम् ॥३५॥"], "iast": ["bhayād raṇād uparataṃ maṃsyante tvāṃ mahā-rathāḥ", "yeṣāṃ ca tvaṃ bahu-mato bhūtvā yāsyasi lāghavam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los <a class=\"t\" href=\"glosario.html#maharatha\" data-t=\"maharatha\">mahārathas</a> pensarán que te retiraste del combate por miedo, y tú, que tanto estimaban, caerás en su menosprecio.</span>", "palabras": [{"iast": "bhayāt", "sa": "भयात्", "gram": "abl. sg. n.", "es": "por miedo", "analisis": "√bhī (temer)"}, {"iast": "raṇāt", "sa": "रणात्", "gram": "abl. sg. m.", "es": "del combate"}, {"iast": "uparatam", "sa": "उपरतम्", "gram": "ac. sg. m. ppp", "es": "retirado", "analisis": "upa-√ram (cesar, retirarse)"}, {"iast": "maṃsyante", "sa": "मंस्यन्ते", "gram": "3 pl. fut. med.", "es": "pensarán", "analisis": "√man (pensar)"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "ac. sg. pron.", "es": "de ti, a ti"}, {"iast": "mahā-rathāḥ", "sa": "महारथाः", "gram": "nom. pl. m. comp.", "es": "los grandes guerreros de carro", "ref": "maharatha"}, {"iast": "yeṣām", "sa": "येषाम्", "gram": "gen. pl. m. pron.", "es": "de quienes, para quienes"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "tvam", "sa": "त्वम्", "gram": "nom. sg. pron.", "es": "tú"}, {"iast": "bahu-mataḥ", "sa": "बहुमतः", "gram": "nom. sg. m. comp.", "es": "muy estimado", "analisis": "bahu (mucho) + mata (estimado, ppp de √man)"}, {"iast": "bhūtvā", "sa": "भूत्वा", "gram": "abs.", "es": "habiendo sido", "analisis": "√bhū (ser)"}, {"iast": "yāsyasi", "sa": "यास्यसि", "gram": "2 sg. fut. act.", "es": "irás a parar, caerás", "analisis": "√yā (ir)"}, {"iast": "lāghavam", "sa": "लाघवम्", "gram": "ac. sg. n.", "es": "ligereza, menosprecio", "analisis": "de laghu (ligero, de poco peso)"}], "nota": "<p>Los <em>mahārathas</em> son los grandes guerreros de ambos ejércitos enumerados en el capítulo 1 (<a class=\"vref\" href=\"capitulo-01.html#v4\" data-v=\"1.4\">1.4</a>–<a class=\"vref\" href=\"capitulo-01.html#v6\" data-v=\"1.6\">1.6</a>), entre ellos <a class=\"t\" href=\"glosario.html#karna\" data-t=\"karna\">Karṇa</a>, su gran rival. Nadie atribuiría la retirada de Arjuna a la compasión: la leerían como cobardía. <em>Lāghava</em>, literalmente «ligereza», es lo contrario del peso o la gravedad que da la estima.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 36, "hablante": "krsna", "sa": ["अवाच्यवादांश्च बहून्वदिष्यन्ति तवाहिताः ।", "निन्दन्तस्तव सामर्थ्यं ततो दुःखतरं नु किम् ॥३६॥"], "iast": ["avācya-vādāṃś ca bahūn vadiṣyanti tavāhitāḥ", "nindantas tava sāmarthyaṃ tato duḥkhataraṃ nu kim"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Tus enemigos dirán de ti muchas cosas que no deberían decirse, denigrando tu valía. ¿Qué puede haber más doloroso que eso?</span>", "palabras": [{"iast": "avācya-vādān", "sa": "अवाच्यवादान्", "gram": "ac. pl. m. comp.", "es": "palabras que no deben decirse", "analisis": "a-vācya (indecible, gerundivo de √vac, decir) + vāda (palabra, dicho)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "bahūn", "sa": "बहून्", "gram": "ac. pl. m. adj.", "es": "muchas"}, {"iast": "vadiṣyanti", "sa": "वदिष्यन्ति", "gram": "3 pl. fut. act.", "es": "dirán", "analisis": "√vad (hablar)"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tuyos"}, {"iast": "ahitāḥ", "sa": "अहिताः", "gram": "nom. pl. m.", "es": "los enemigos", "analisis": "a (no) + hita (favorable, amigo)"}, {"iast": "nindantaḥ", "sa": "निन्दन्तः", "gram": "nom. pl. m. part. pres.", "es": "denigrando", "analisis": "√nind (censurar, vituperar)"}, {"iast": "tava", "sa": "तव", "gram": "gen. sg. pron.", "es": "tu"}, {"iast": "sāmarthyam", "sa": "सामर्थ्यम्", "gram": "ac. sg. n.", "es": "capacidad, valía", "analisis": "de samartha (capaz)"}, {"iast": "tataḥ", "sa": "ततः", "gram": "ind.", "es": "que eso"}, {"iast": "duḥkhataram", "sa": "दुःखतरम्", "gram": "nom. sg. n. adj.", "es": "más doloroso", "analisis": "comparativo (-tara) de duḥkha (dolor)"}, {"iast": "nu", "sa": "नु", "gram": "ind.", "es": "acaso"}, {"iast": "kim", "sa": "किम्", "gram": "nom. sg. n. pron.", "es": "¿qué?"}], "nota": "", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 37, "hablante": "krsna", "sa": ["हतो वा प्राप्स्यसि स्वर्गं जित्वा वा भोक्ष्यसे महीम् ।", "तस्मादुत्तिष्ठ कौन्तेय युद्धाय कृतनिश्चयः ॥३७॥"], "iast": ["hato vā prāpsyasi svargaṃ jitvā vā bhokṣyase mahīm", "tasmād uttiṣṭha kaunteya yuddhāya kṛta-niścayaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Si mueres, alcanzarás el <a class=\"t\" href=\"glosario.html#svarga\" data-t=\"svarga\">cielo</a>; si vences, gozarás de la tierra. Por eso, levántate, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, resuelto a combatir.</span>", "palabras": [{"iast": "hataḥ", "sa": "हतः", "gram": "nom. sg. m. ppp", "es": "muerto, abatido", "analisis": "√han (golpear, matar)"}, {"iast": "vā", "sa": "वा", "gram": "ind.", "es": "o, si"}, {"iast": "prāpsyasi", "sa": "प्राप्स्यसि", "gram": "2 sg. fut. act.", "es": "alcanzarás", "analisis": "pra-√āp (alcanzar)"}, {"iast": "svargam", "sa": "स्वर्गम्", "gram": "ac. sg. m.", "es": "el cielo", "ref": "svarga"}, {"iast": "jitvā", "sa": "जित्वा", "gram": "abs.", "es": "venciendo", "analisis": "√ji (vencer)"}, {"iast": "vā", "sa": "वा", "gram": "ind.", "es": "o, si"}, {"iast": "bhokṣyase", "sa": "भोक्ष्यसे", "gram": "2 sg. fut. med.", "es": "gozarás", "analisis": "√bhuj (disfrutar, comer)"}, {"iast": "mahīm", "sa": "महीम्", "gram": "ac. sg. f.", "es": "la tierra"}, {"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. pron.", "es": "por eso"}, {"iast": "uttiṣṭha", "sa": "उत्तिष्ठ", "gram": "2 sg. impv. act.", "es": "levántate", "analisis": "ud-√sthā (ponerse en pie)"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh Kaunteya, hijo de Kuntī", "ref": "kaunteya"}, {"iast": "yuddhāya", "sa": "युद्धाय", "gram": "dat. sg. n.", "es": "para el combate"}, {"iast": "kṛta-niścayaḥ", "sa": "कृतनिश्चयः", "gram": "nom. sg. m. comp.", "es": "resuelto", "analisis": "kṛta (hecho) + niścaya (determinación): «el que ha tomado una resolución»"}], "nota": "<p>El imperativo <em>uttiṣṭha</em>, «levántate», responde a la imagen con que cierra el capítulo 1: Arjuna sentado en el carro, con el arco caído (<a class=\"vref\" href=\"capitulo-01.html#v47\" data-v=\"1.47\">1.47</a>). Kṛṣṇa ya lo había exhortado así en <a class=\"vref\" href=\"capitulo-02.html#v3\" data-v=\"2.3\">2.3</a>. El dilema de <a class=\"vref\" href=\"capitulo-02.html#v6\" data-v=\"2.6\">2.6</a> —no sabemos qué es mejor, vencer o ser vencidos— recibe aquí una respuesta en los términos del propio Arjuna: los dos desenlaces son buenos.</p>", "interp": [{"titulo": "¿Motivos interesados?", "html": "<p>Prometer el cielo o un reino parece contradecir lo que la Gītā enseñará enseguida: actuar sin buscar el fruto (<a class=\"vref\" href=\"capitulo-02.html#v47\" data-v=\"2.47\">2.47</a>). Los comentaristas clásicos lo explican como una concesión pedagógica: Kṛṣṇa habla primero al guerrero que Arjuna todavía es, con razones que él reconoce, y en el verso siguiente retira esos mismos motivos y le pide igualar victoria y derrota.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}, {"titulo": "Gandhi: la guerra como alegoría", "html": "<p><a class=\"t\" href=\"glosario.html#gandhi\" data-t=\"gandhi\">Gandhi</a>, que tradujo la Gītā al gujarati con el título de <em>Anāsaktiyoga</em>, «el yoga del desapego», no leyó en este llamamiento una justificación de la guerra física. Para él, el poema usa la batalla como marco para describir el combate que se libra en el corazón humano entre el bien y el mal. Su mensaje central sería la renuncia al fruto de la acción, y llevado hasta el final conduce, según él, a la no violencia. En la introducción escribe que, tras cuarenta años de esfuerzo por vivir esa enseñanza, ha llegado a sentir que la renuncia perfecta es imposible sin la observancia perfecta de la <em>ahiṃsā</em> en todas sus formas; y admite a la vez que la Gītā no se escribió para establecer la ahiṃsā.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 38, "hablante": "krsna", "sa": ["सुखदुःखे समे कृत्वा लाभालाभौ जयाजयौ ।", "ततो युद्धाय युज्यस्व नैवं पापमवाप्स्यसि ॥३८॥"], "iast": ["sukha-duḥkhe same kṛtvā lābhālābhau jayājayau", "tato yuddhāya yujyasva naivaṃ pāpam avāpsyasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Tomando por <a class=\"t\" href=\"glosario.html#samatva\" data-t=\"samatva\">iguales</a> el placer y el dolor, la ganancia y la pérdida, la victoria y la derrota, disponte entonces al combate: así no incurrirás en <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a>.</span>", "palabras": [{"iast": "sukha-duḥkhe", "sa": "सुखदुःखे", "gram": "ac. du. n. comp.", "es": "el placer y el dolor", "analisis": "sukha (placer, bienestar) + duḥkha (dolor, malestar)"}, {"iast": "same", "sa": "समे", "gram": "ac. du. n. adj.", "es": "iguales", "ref": "samatva", "analisis": "sama (igual)"}, {"iast": "kṛtvā", "sa": "कृत्वा", "gram": "abs.", "es": "haciendo, tomando por", "analisis": "√kṛ (hacer)"}, {"iast": "lābha-alābhau", "sa": "लाभालाभौ", "gram": "ac. du. m. comp.", "es": "la ganancia y la pérdida", "analisis": "lābha (ganancia, de √labh, obtener) + a-lābha (no ganancia)"}, {"iast": "jaya-ajayau", "sa": "जयाजयौ", "gram": "ac. du. m. comp.", "es": "la victoria y la derrota", "analisis": "jaya (victoria, de √ji, vencer) + a-jaya (no victoria)"}, {"iast": "tataḥ", "sa": "ततः", "gram": "ind.", "es": "entonces"}, {"iast": "yuddhāya", "sa": "युद्धाय", "gram": "dat. sg. n.", "es": "para el combate"}, {"iast": "yujyasva", "sa": "युज्यस्व", "gram": "2 sg. impv. med.", "es": "disponte, aplícate", "analisis": "√yuj (uncir, unir), la raíz de yoga"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "evam", "sa": "एवम्", "gram": "ind.", "es": "así"}, {"iast": "pāpam", "sa": "पापम्", "gram": "ac. sg. n.", "es": "pecado", "ref": "papa"}, {"iast": "avāpsyasi", "sa": "अवाप्स्यसि", "gram": "2 sg. fut. act.", "es": "incurrirás en"}], "nota": "<p>Primera formulación de la <a class=\"t\" href=\"glosario.html#samatva\" data-t=\"samatva\">ecuanimidad</a> que el capítulo convertirá en definición del yoga (<a class=\"vref\" href=\"capitulo-02.html#v48\" data-v=\"2.48\">2.48</a>). Las tres parejas no se eligen al azar: el placer y el dolor son el plano de los sentidos; la ganancia y la pérdida, el de los intereses; la victoria y la derrota, el del guerrero. El verbo <em>yujyasva</em>, «disponte, úncete», procede de la misma raíz que <em>yoga</em> y prepara el giro del verso siguiente.</p><p>El verso responde también al miedo de Arjuna: si combate sin buscar placer, ganancia ni victoria, la acción no le dejará <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a>.</p>", "interp": [{"titulo": "El gozne del capítulo", "html": "<p>El verso contradice en apariencia al anterior: en <a class=\"vref\" href=\"capitulo-02.html#v37\" data-v=\"2.37\">2.37</a>, la victoria y el cielo eran motivos para luchar; aquí, victoria y derrota deben dar igual. No es incoherencia, sino un cambio deliberado de nivel. Con este verso termina la apelación a la honra y empieza la enseñanza propia de la Gītā, que <a class=\"vref\" href=\"capitulo-02.html#v39\" data-v=\"2.39\">2.39</a> anuncia como «el entendimiento según el yoga»: no qué hacer, sino con qué disposición hacerlo.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "La ecuanimidad en la acción", "html": "<p>Los lectores modernos que han hecho de la Gītā una guía para la vida activa, como Tilak o Gandhi, ven aquí el germen de su enseñanza central: no la retirada del mundo, sino el compromiso pleno con la tarea, sin dejarse gobernar por el resultado. Gandhi lo resumió en la palabra <em>anāsakti</em>, «desapego»: entregarse por entero a la acción sin apegarse a su fruto.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "igualar-los-contrarios"}, {"n": 39, "hablante": "krsna", "sa": ["एषा तेऽभिहिता साङ्ख्ये बुद्धिर्योगे त्विमां शृणु ।", "बुद्ध्या युक्तो यया पार्थ कर्मबन्धं प्रहास्यसि ॥३९॥"], "iast": ["eṣā te 'bhihitā sāṅkhye buddhir yoge tv imāṃ śṛṇu", "buddhyā yukto yayā pārtha karma-bandhaṃ prahāsyasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Esto que te he expuesto es el entendimiento según el <a class=\"t\" href=\"glosario.html#sankhya\" data-t=\"sankhya\">sāṅkhya</a>; escucha ahora cómo es según el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>: unido a ese <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, te desprenderás de la atadura de la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>.</span>", "palabras": [{"iast": "eṣā", "sa": "एषा", "gram": "nom. sg. f. pron.", "es": "esta", "analisis": "demostrativo etad"}, {"iast": "te", "sa": "ते", "gram": "dat. sg. pron.", "es": "a ti", "analisis": "forma enclítica de tvam (tú)"}, {"iast": "abhihitā", "sa": "अभिहिता", "gram": "nom. sg. f. ppp", "es": "expuesta", "analisis": "abhi-√dhā (decir, exponer)"}, {"iast": "sāṅkhye", "sa": "साङ्ख्ये", "gram": "loc. sg. n.", "es": "según el sāṅkhya, en la vía del discernimiento", "ref": "sankhya", "analisis": "derivado de saṃkhyā (enumeración, cálculo, discernimiento)"}, {"iast": "buddhiḥ", "sa": "बुद्धिः", "gram": "nom. sg. f.", "es": "el entendimiento", "ref": "buddhi", "analisis": "√budh (despertar, comprender)"}, {"iast": "yoge", "sa": "योगे", "gram": "loc. sg. m.", "es": "según el yoga", "ref": "yoga", "analisis": "√yuj (uncir, unir, aplicar)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero, ahora"}, {"iast": "imām", "sa": "इमाम्", "gram": "ac. sg. f. pron.", "es": "esta", "analisis": "demostrativo idam"}, {"iast": "śṛṇu", "sa": "शृणु", "gram": "2 sg. impv. act.", "es": "escucha", "analisis": "√śru (oír)"}, {"iast": "buddhyā", "sa": "बुद्ध्या", "gram": "instr. sg. f.", "es": "con el entendimiento", "ref": "buddhi"}, {"iast": "yuktaḥ", "sa": "युक्तः", "gram": "nom. sg. m. ppp", "es": "unido, provisto", "analisis": "√yuj (uncir, unir)"}, {"iast": "yayā", "sa": "यया", "gram": "instr. sg. f. pron.", "es": "con el cual", "analisis": "relativo yad"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "karma-bandham", "sa": "कर्मबन्धम्", "gram": "ac. sg. m. comp.", "es": "la atadura de la acción", "ref": "karma", "analisis": "karman (acción) + bandha (atadura, de √bandh, atar)"}, {"iast": "prahāsyasi", "sa": "प्रहास्यसि", "gram": "2 sg. fut. act.", "es": "te desprenderás de", "analisis": "pra-√hā (dejar, abandonar)"}], "nota": "<p>Verso bisagra del capítulo. Lo dicho hasta aquí (<a class=\"vref\" href=\"capitulo-02.html#v11\" data-v=\"2.11\">2.11</a>–<a class=\"vref\" href=\"capitulo-02.html#v38\" data-v=\"2.38\">2.38</a>) era el discernimiento entre el sí-mismo imperecedero y el cuerpo que muere; desde aquí Kṛṣṇa expone el mismo entendimiento aplicado a la acción, al que llamará <em>buddhi-yoga</em>, el yoga del entendimiento (<a class=\"vref\" href=\"capitulo-02.html#v49\" data-v=\"2.49\">2.49</a>).</p><p><em>Sāṅkhya</em> y <em>yoga</em> no designan todavía las escuelas filosóficas clásicas de esos nombres, cuyos textos fundacionales se fechan, por lo general, después de la Gītā (la <em>Sāṅkhya-kārikā</em>, hacia los siglos IV–V d. C.; los <em>Yoga-sūtra</em>, con más discusión, entre los primeros siglos de nuestra era y c. 400 d. C.), sino dos enfoques: el del conocimiento que discierne y el de la disciplina en la acción. La Gītā volverá sobre ellos en <a class=\"vref\" href=\"capitulo-03.html#v3\" data-v=\"3.3\">3.3</a> y en <a class=\"vref\" href=\"capitulo-05.html#v4\" data-v=\"5.4\">5.4</a>–<a class=\"vref\" href=\"capitulo-05.html#v5\" data-v=\"5.5\">5.5</a>, para afirmar que en el fondo son uno.</p><p>La «atadura de la acción» (<em>karma-bandha</em>) es la idea de que toda acción hecha con deseo deja un residuo que obliga a renacer para recoger su fruto.</p>", "interp": [{"titulo": "Conocimiento y medio para el conocimiento", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende aquí <em>sāṅkhya</em> como el discernimiento de la realidad suprema, el sí-mismo, tal como se ha expuesto en los versos anteriores, y <em>yoga</em> como el medio para alcanzar ese conocimiento: el <a class=\"t\" href=\"glosario.html#karma-yoga\" data-t=\"karma-yoga\"><em>karma-yoga</em></a>, la acción hecha sin apego y como adoración del Señor, y también la práctica de la absorción (<em>samādhi-yoga</em>). Para él son dos vías para dos clases de personas, y no pueden combinarse en una sola: la acción prepara, pero sólo el conocimiento, obtenido por la gracia del Señor, libera.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Sāṅkhya y yoga antes de las escuelas", "html": "<p>El indólogo Franklin Edgerton insistió en que, en la Gītā, <em>sāṅkhya</em> y <em>yoga</em> significan sobre todo «método del conocimiento» y «método de la acción disciplinada», y no los sistemas filosóficos posteriores. Los elementos de la cosmología sāṅkhya que aparecen en otros capítulos (las <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>, la naturaleza y el espíritu) pertenecerían a una fase anterior a su sistematización clásica.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 40, "hablante": "krsna", "sa": ["नेहाभिक्रमनाशोऽस्ति प्रत्यवायो न विद्यते ।", "स्वल्पमप्यस्य धर्मस्य त्रायते महतो भयात् ॥४०॥"], "iast": ["nehābhikrama-nāśo 'sti pratyavāyo na vidyate", "svalpam apy asya dharmasya trāyate mahato bhayāt"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">En este camino no se pierde ningún esfuerzo emprendido ni hay daño posible; aun un poco de este <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a> protege de un gran temor.</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí, en este camino"}, {"iast": "abhikrama-nāśaḥ", "sa": "अभिक्रमनाशः", "gram": "nom. sg. m. comp.", "es": "pérdida del esfuerzo emprendido", "analisis": "abhikrama (comienzo, empresa; de abhi-√kram, avanzar) + nāśa (pérdida, de √naś, perecer)"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres. act.", "es": "hay", "analisis": "√as (ser)"}, {"iast": "pratyavāyaḥ", "sa": "प्रत्यवायः", "gram": "nom. sg. m.", "es": "daño, efecto adverso", "analisis": "prati-ava-√i (volverse en contra): en el ritual, el perjuicio que acarrea un rito mal hecho u omitido"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "vidyate", "sa": "विद्यते", "gram": "3 sg. pres. pas.", "es": "se da, existe", "analisis": "√vid (encontrar; en pasiva, existir)"}, {"iast": "svalpam", "sa": "स्वल्पम्", "gram": "nom. sg. n. adj.", "es": "muy poco", "analisis": "su (bien, muy) + alpa (poco)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. m. pron.", "es": "de este", "analisis": "demostrativo idam"}, {"iast": "dharmasya", "sa": "धर्मस्य", "gram": "gen. sg. m.", "es": "de este dharma, de esta práctica", "ref": "dharma"}, {"iast": "trāyate", "sa": "त्रायते", "gram": "3 sg. pres. med.", "es": "protege, salva", "analisis": "√trai (proteger)"}, {"iast": "mahataḥ", "sa": "महतः", "gram": "abl. sg. n. adj.", "es": "grande", "analisis": "mahat (grande)"}, {"iast": "bhayāt", "sa": "भयात्", "gram": "abl. sg. n.", "es": "del temor, del peligro", "analisis": "√bhī (temer)"}], "nota": "<p>Kṛṣṇa contrapone el yoga de la acción al rito védico. En el rito, un acto interrumpido no da fruto y un error de procedimiento acarrea un perjuicio (<em>pratyavāya</em>); en este camino, en cambio, nada de lo hecho se pierde. El «gran temor» es, para los comentaristas, el del <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">saṃsāra</a>, el ciclo de nacimiento y muerte. La idea reaparece en <a class=\"vref\" href=\"capitulo-06.html#v40\" data-v=\"6.40\">6.40</a>: quien obra el bien no va a mal fin, aunque no alcance la meta en esta vida.</p>", "interp": [{"titulo": "Lo poco que no se pierde", "html": "<p>Para los comentaristas vedánticos, ese «poco» es la acción sin apego practicada aunque sea de manera incompleta: purifica la mente y deja una disposición que fructificará más adelante, si no en esta vida, en la siguiente. Es lo que Kṛṣṇa explicará a propósito del yogui que no llega a la meta (<a class=\"vref\" href=\"capitulo-06.html#v41\" data-v=\"6.41\">6.41</a>–<a class=\"vref\" href=\"capitulo-06.html#v45\" data-v=\"6.45\">6.45</a>).</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "En este camino no se pierde ningún esfuerzo emprendido ni hay daño posible; aun un poco de este <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a> protege de un gran peligro.", "nota": "<p><em>Bhaya</em> (de √bhī, «temer») es tanto la emoción como lo que la causa: «temor» y «peligro». «Peligro» presenta el ciclo de renacimientos como una amenaza de la que uno queda a salvo; «temor», la opción principal, como una angustia de la que uno se libera, y conserva el eco con <a class=\"vref\" href=\"capitulo-02.html#v35\" data-v=\"2.35\">2.35</a> y <a class=\"vref\" href=\"capitulo-02.html#v56\" data-v=\"2.56\">2.56</a>, donde <em>bhaya</em> es claramente miedo. <em>Trāyate</em> admite también «salva» o «libra»: «aun un poco de este dharma libra de un gran temor».</p>"}]}, {"n": 41, "hablante": "krsna", "sa": ["व्यवसायात्मिका बुद्धिरेकेह कुरुनन्दन ।", "बहुशाखा ह्यनन्ताश्च बुद्धयोऽव्यवसायिनाम् ॥४१॥"], "iast": ["vyavasāyātmikā buddhir ekeha kuru-nandana", "bahu-śākhā hy anantāś ca buddhayo 'vyavasāyinām"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">En este camino, oh <a class=\"t\" href=\"glosario.html#kurunandana\" data-t=\"kurunandana\">Kuru-nandana</a>, el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> resuelto es uno solo; los entendimientos de los irresolutos tienen muchas ramas y no tienen fin.</span>", "palabras": [{"iast": "vyavasāya-ātmikā", "sa": "व्यवसायात्मिका", "gram": "nom. sg. f. adj. comp.", "es": "resuelto, de naturaleza decidida", "analisis": "vyavasāya (resolución, de vi-ava-√so, decidir) + ātmaka (que tiene por naturaleza)"}, {"iast": "buddhiḥ", "sa": "बुद्धिः", "gram": "nom. sg. f.", "es": "el entendimiento", "ref": "buddhi"}, {"iast": "ekā", "sa": "एका", "gram": "nom. sg. f. num.", "es": "una sola"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí, en este camino"}, {"iast": "kuru-nandana", "sa": "कुरुनन्दन", "gram": "voc. sg. m. comp.", "es": "oh alegría de los Kurus", "ref": "kurunandana", "analisis": "kuru (la dinastía Kuru) + nandana (que alegra; hijo; de √nand, alegrarse)"}, {"iast": "bahu-śākhāḥ", "sa": "बहुशाखाः", "gram": "nom. pl. f. adj. comp.", "es": "de muchas ramas", "analisis": "bahu (mucho) + śākhā (rama)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "anantāḥ", "sa": "अनन्ताः", "gram": "nom. pl. f. adj.", "es": "sin fin", "analisis": "an (no) + anta (fin)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "buddhayaḥ", "sa": "बुद्धयः", "gram": "nom. pl. f.", "es": "los entendimientos", "ref": "buddhi"}, {"iast": "avyavasāyinām", "sa": "अव्यवसायिनाम्", "gram": "gen. pl. m. adj.", "es": "de los irresolutos", "analisis": "a (no) + vyavasāyin (resuelto)"}], "nota": "<p>Primera definición del entendimiento propio del yoga: <em>vyavasāyātmikā</em>, «de naturaleza resuelta», fijo en una sola meta. Frente a él, la mente de quien obra movido por los deseos se ramifica como un árbol: cada deseo cumplido engendra otros. La imagen vegetal prepara la de la «palabra florida» del verso siguiente (<a class=\"vref\" href=\"capitulo-02.html#v42\" data-v=\"2.42\">2.42</a>) y la crítica de quienes están absortos en el goce y el poder (<a class=\"vref\" href=\"capitulo-02.html#v44\" data-v=\"2.44\">2.44</a>).</p>", "interp": [{"titulo": "Una sola meta: la liberación", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> precisa que el entendimiento resuelto es el que está decidido acerca de la verdadera naturaleza del sí-mismo y se propone una única meta, la liberación. Quien realiza los ritos para obtener sus frutos (el cielo, hijos, ganado, alimento) tiene, en cambio, tantos propósitos como frutos desea, y su entendimiento se dispersa con ellos.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "La devoción de una sola meta", "html": "<p>Los comentaristas devocionales, en particular los de la escuela <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, identifican este entendimiento de una sola meta con la devoción exclusiva a Kṛṣṇa: quien tiene a Dios por único fin deja de dispersarse entre metas parciales.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "En este camino, oh <a class=\"t\" href=\"glosario.html#kurunandana\" data-t=\"kurunandana\">Kuru-nandana</a>, los resueltos tienen un solo <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>; los irresolutos, entendimientos de muchas ramas y sin fin.", "nota": "<p>Lectura simétrica: resueltos frente a irresolutos. El sánscrito no lo es del todo: en la primera mitad, <em>vyavasāyātmikā</em>, «de naturaleza resuelta», es un adjetivo que califica al entendimiento (femenino singular, como <em>buddhiḥ</em>); sólo en la segunda habla de personas, <em>avyavasāyinām</em>, «de los irresolutos». El sentido apenas cambia, pero la traducción principal conserva la asimetría.</p>"}, {"html": "En este camino, oh <a class=\"t\" href=\"glosario.html#kurunandana\" data-t=\"kurunandana\">Kuru-nandana</a>, el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> que tiene certeza es uno solo; los de quienes carecen de ella se ramifican sin fin.", "nota": "<p><em>Vyavasāya</em> es «resolución», pero también «determinación» en el sentido de saber con certeza. Los comentaristas clásicos lo glosan como <em>niścaya</em>, «certeza, convicción firme»: un entendimiento que ha llegado a una conclusión sobre lo que importa —para ellos, sobre la naturaleza del sí-mismo— y por eso no se dispersa. Con «resuelto» el acento está en la voluntad; con «certeza», en el conocimiento.</p>"}], "ens": "entendimiento-resuelto"}, {"n": 42, "hablante": "krsna", "sa": ["यामिमां पुष्पितां वाचं प्रवदन्त्यविपश्चितः ।", "वेदवादरताः पार्थ नान्यदस्तीति वादिनः ॥४२॥"], "iast": ["yām imāṃ puṣpitāṃ vācaṃ pravadanty avipaścitaḥ", "veda-vāda-ratāḥ pārtha nānyad astīti vādinaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Esa palabra florida que proclaman los ignorantes, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, complacidos en las <a class=\"t\" href=\"glosario.html#vedavada\" data-t=\"vedavada\">palabras del Veda</a> y afirmando que no hay nada más,</span>", "palabras": [{"iast": "yām", "sa": "याम्", "gram": "ac. sg. f. pron.", "es": "la cual", "analisis": "relativo yad"}, {"iast": "imām", "sa": "इमाम्", "gram": "ac. sg. f. pron.", "es": "esta"}, {"iast": "puṣpitām", "sa": "पुष्पिताम्", "gram": "ac. sg. f. ppp", "es": "florida", "analisis": "de puṣpa (flor): «florecida»"}, {"iast": "vācam", "sa": "वाचम्", "gram": "ac. sg. f.", "es": "palabra, discurso", "analisis": "√vac (hablar)"}, {"iast": "pravadanti", "sa": "प्रवदन्ति", "gram": "3 pl. pres. act.", "es": "proclaman", "analisis": "pra-√vad (hablar, declarar)"}, {"iast": "avipaścitaḥ", "sa": "अविपश्चितः", "gram": "nom. pl. m. adj.", "es": "los ignorantes", "analisis": "a (no) + vipaścit (sabio, perspicaz)"}, {"iast": "veda-vāda-ratāḥ", "sa": "वेदवादरताः", "gram": "nom. pl. m. adj. comp.", "es": "complacidos en las palabras del Veda", "ref": "vedavada", "analisis": "veda + vāda (palabra, doctrina) + rata (que se deleita, de √ram)"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "anyat", "sa": "अन्यत्", "gram": "nom. sg. n. pron.", "es": "otra cosa"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres. act.", "es": "hay", "analisis": "√as (ser)"}, {"iast": "iti", "sa": "इति", "gram": "ind.", "es": "así (cierra la cita)"}, {"iast": "vādinaḥ", "sa": "वादिनः", "gram": "nom. pl. m.", "es": "que afirman", "analisis": "√vad (hablar)"}], "nota": "<p>Los versos 2.42–2.44 forman una sola frase. Kṛṣṇa no ataca al <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Veda</a> en sí, sino a quienes se quedan en la parte de los textos que promete recompensas por los ritos y concluyen que «no hay nada más» (<em>nānyad asti</em>): nada por encima del cielo que se gana con el sacrificio. La tradición los identifica con los ritualistas de la escuela <em>Pūrva-Mīmāṃsā</em>, para quienes el sentido del Veda es prescribir acciones. La palabra es «florida» como un árbol en flor: hermosa de oír, pero sin el fruto verdadero.</p>", "interp": [{"titulo": "Rito y conocimiento dentro del Veda", "html": "<p>Para los comentaristas vedánticos, Kṛṣṇa distingue dentro del propio Veda entre la sección de los ritos (<em>karma-kāṇḍa</em>) y la del conocimiento (<em>jñāna-kāṇḍa</em>, las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a>). Censura a quienes toman las promesas de la primera —el cielo, la prosperidad— como el fin último e ignoran la segunda.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}, {"titulo": "Un eco de la crítica upaniṣádica", "html": "<p>Los historiadores ven en estos versos la continuación de una crítica al ritualismo que ya está en las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a>: la <em>Muṇḍaka Upaniṣad</em> (1.2.7) llama a los sacrificios «barcas frágiles» y se burla de quienes, teniéndose por sabios, vuelven una y otra vez a la vejez y la muerte. La Gītā no rompe con el Veda, que venera en otros lugares (<a class=\"vref\" href=\"capitulo-15.html#v15\" data-v=\"15.15\">15.15</a>), pero lo relativiza: el rito es un medio, no la meta.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 43, "hablante": "krsna", "sa": ["कामात्मानः स्वर्गपरा जन्मकर्मफलप्रदाम् ।", "क्रियाविशेषबहुलां भोगैश्वर्यगतिं प्रति ॥४३॥"], "iast": ["kāmātmānaḥ svarga-parā janma-karma-phala-pradām", "kriyā-viśeṣa-bahulāṃ bhogaiśvarya-gatiṃ prati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">hombres hechos de <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a> que tienen el <a class=\"t\" href=\"glosario.html#svarga\" data-t=\"svarga\">cielo</a> por meta suprema; palabra que promete un nuevo nacimiento como <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a> de la acción y abunda en ritos particulares encaminados al goce y al poder:</span>", "palabras": [{"iast": "kāma-ātmānaḥ", "sa": "कामात्मानः", "gram": "nom. pl. m. adj. comp.", "es": "hechos de deseo", "ref": "kama", "analisis": "kāma (deseo) + ātman (sí-mismo, naturaleza): «cuyo ser es el deseo»"}, {"iast": "svarga-parāḥ", "sa": "स्वर्गपराः", "gram": "nom. pl. m. adj. comp.", "es": "que tienen el cielo por meta suprema", "ref": "svarga", "analisis": "svarga (cielo) + para (supremo)"}, {"iast": "janma-karma-phala-pradām", "sa": "जन्मकर्मफलप्रदाम्", "gram": "ac. sg. f. adj. comp.", "es": "que promete el nacimiento como fruto de la acción", "ref": "phala", "analisis": "janman (nacimiento) + karman (acción) + phala (fruto) + prada (que da, de pra-√dā)"}, {"iast": "kriyā-viśeṣa-bahulām", "sa": "क्रियाविशेषबहुलाम्", "gram": "ac. sg. f. adj. comp.", "es": "abundante en ritos particulares", "analisis": "kriyā (acto, rito) + viśeṣa (particular) + bahula (abundante)"}, {"iast": "bhoga-aiśvarya-gatim", "sa": "भोगैश्वर्यगतिम्", "gram": "ac. sg. f. comp.", "es": "la obtención de goce y de poder", "analisis": "bhoga (goce, de √bhuj) + aiśvarya (señorío, poder) + gati (logro, camino)"}, {"iast": "prati", "sa": "प्रति", "gram": "ind.", "es": "hacia, en orden a"}], "nota": "<p><em>Kāmātmānaḥ</em>, literalmente «cuyo ser (<em>ātman</em>) es el deseo»: personas enteramente hechas de deseo. El cielo (<em>svarga</em>) que prometen los ritos no es eterno: según <a class=\"vref\" href=\"capitulo-09.html#v21\" data-v=\"9.21\">9.21</a>, quienes llegan a él vuelven al mundo de los mortales cuando se agota su mérito. Por eso la recompensa del rito es, en último término, «nacimiento»: otra vuelta del ciclo.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 44, "hablante": "krsna", "sa": ["भोगैश्वर्यप्रसक्तानां तयापहृतचेतसाम् ।", "व्यवसायात्मिका बुद्धिः समाधौ न विधीयते ॥४४॥"], "iast": ["bhogaiśvarya-prasaktānāṃ tayāpahṛta-cetasām", "vyavasāyātmikā buddhiḥ samādhau na vidhīyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">a quienes están apegados al goce y al poder, con la mente arrebatada por esa palabra, no se les da el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> resuelto en el <a class=\"t\" href=\"glosario.html#samadhi\" data-t=\"samadhi\">samādhi</a>.</span>", "palabras": [{"iast": "bhoga-aiśvarya-prasaktānām", "sa": "भोगैश्वर्यप्रसक्तानाम्", "gram": "gen. pl. m. adj. comp.", "es": "de los apegados al goce y al poder", "analisis": "bhoga (goce) + aiśvarya (poder) + prasakta (apegado, de pra-√sañj)"}, {"iast": "tayā", "sa": "तया", "gram": "instr. sg. f. pron.", "es": "por ella (esa palabra)"}, {"iast": "apahṛta-cetasām", "sa": "अपहृतचेतसाम्", "gram": "gen. pl. m. adj. comp.", "es": "de mente arrebatada", "analisis": "apahṛta (arrebatado, de apa-√hṛ) + cetas (mente, pensamiento)"}, {"iast": "vyavasāya-ātmikā", "sa": "व्यवसायात्मिका", "gram": "nom. sg. f. adj. comp.", "es": "resuelto", "analisis": "vyavasāya (resolución) + ātmaka (que tiene por naturaleza)"}, {"iast": "buddhiḥ", "sa": "बुद्धिः", "gram": "nom. sg. f.", "es": "el entendimiento", "ref": "buddhi"}, {"iast": "samādhau", "sa": "समाधौ", "gram": "loc. sg. m.", "es": "en el samādhi, en la concentración", "ref": "samadhi", "analisis": "sam-ā-√dhā (poner junto, fijar)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "vidhīyate", "sa": "विधीयते", "gram": "3 sg. pres. pas.", "es": "se establece, se da", "analisis": "vi-√dhā (disponer, establecer)"}], "nota": "<p><em>Samādhi</em> no tiene aquí todavía el sentido técnico de los <em>Yoga-sūtra</em>, el de la absorción completa de la meditación. Unos comentaristas, como <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, lo entienden como la mente misma, «aquello en lo que todo se reúne» para la experiencia de la persona; otros, como la concentración en el sí-mismo o en Dios. En cualquier caso, el verso dice que la dispersión del deseo hace imposible la firmeza interior que Kṛṣṇa describirá en <a class=\"vref\" href=\"capitulo-02.html#v53\" data-v=\"2.53\">2.53</a> y al final del capítulo.</p>", "interp": [{"titulo": "Samādhi, la mente misma", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> no lee aquí <em>samādhi</em> como absorción meditativa: lo glosa como el órgano interno (<em>antaḥkaraṇa</em>), el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>, porque es «aquello en lo que todo se reúne para la experiencia de la persona». El verso dice, así, que en la mente de quienes viven entregados al goce y al poder no llega a surgir la convicción resuelta, ni sobre el conocimiento ni sobre el yoga.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 45, "hablante": "krsna", "sa": ["त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन ।", "निर्द्वन्द्वो नित्यसत्त्वस्थो निर्योगक्षेम आत्मवान् ॥४५॥"], "iast": ["traiguṇya-viṣayā vedā nistraiguṇyo bhavārjuna", "nirdvandvo nitya-sattva-stho niryoga-kṣema ātmavān"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Vedas</a> tratan de lo que pertenece a las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>; tú, oh <a class=\"t\" href=\"glosario.html#arjuna\" data-t=\"arjuna\">Arjuna</a>, líbrate de las tres guṇas: libre de los pares de opuestos, asentado siempre en <a class=\"t\" href=\"glosario.html#sattva\" data-t=\"sattva\">sattva</a>, sin afán de adquirir ni de conservar, dueño de ti mismo.</span>", "palabras": [{"iast": "traiguṇya-viṣayāḥ", "sa": "त्रैगुण्यविषयाः", "gram": "nom. pl. m. adj. comp.", "es": "que tratan de lo que pertenece a las tres guṇas", "ref": "traigunya", "analisis": "traiguṇya (el conjunto de las tres guṇas) + viṣaya (ámbito, objeto)"}, {"iast": "vedāḥ", "sa": "वेदाः", "gram": "nom. pl. m.", "es": "los Vedas", "ref": "veda"}, {"iast": "nistraiguṇyaḥ", "sa": "निस्त्रैगुण्यः", "gram": "nom. sg. m. adj.", "es": "libre de las tres guṇas", "ref": "traigunya", "analisis": "nis (sin) + traiguṇya"}, {"iast": "bhava", "sa": "भव", "gram": "2 sg. impv. act.", "es": "sé, hazte", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "arjuna", "sa": "अर्जुन", "gram": "voc. sg. m.", "es": "oh Arjuna", "ref": "arjuna"}, {"iast": "nirdvandvaḥ", "sa": "निर्द्वन्द्वः", "gram": "nom. sg. m. adj.", "es": "libre de los pares de opuestos", "analisis": "nis (sin) + dvandva (par: frío y calor, placer y dolor)"}, {"iast": "nitya-sattva-sthaḥ", "sa": "नित्यसत्त्वस्थः", "gram": "nom. sg. m. adj. comp.", "es": "asentado siempre en sattva", "ref": "sattva", "analisis": "nitya (siempre) + sattva + stha (que está, de √sthā)"}, {"iast": "niryoga-kṣemaḥ", "sa": "निर्योगक्षेमः", "gram": "nom. sg. m. adj. comp.", "es": "sin afán de adquirir ni de conservar", "analisis": "nis (sin) + yoga (adquisición) + kṣema (conservación, seguridad)"}, {"iast": "ātmavān", "sa": "आत्मवान्", "gram": "nom. sg. m. adj.", "es": "dueño de sí", "ref": "atman", "analisis": "ātman + -vat (que posee)"}], "nota": "<p><em>Traiguṇya</em> es el conjunto de las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a> —<a class=\"t\" href=\"glosario.html#sattva\" data-t=\"sattva\">sattva</a>, <a class=\"t\" href=\"glosario.html#rajas\" data-t=\"rajas\">rajas</a> y <a class=\"t\" href=\"glosario.html#tamas\" data-t=\"tamas\">tamas</a>—, es decir, todo lo que pertenece a la naturaleza cambiante. Los ritos del Veda prometen bienes de ese orden; Kṛṣṇa invita a situarse por encima. Los «pares de opuestos» (<em>dvandva</em>) son el frío y el calor, el placer y el dolor, el éxito y el fracaso (<a class=\"vref\" href=\"capitulo-02.html#v14\" data-v=\"2.14\">2.14</a>, <a class=\"vref\" href=\"capitulo-02.html#v38\" data-v=\"2.38\">2.38</a>). <em>Yoga-kṣema</em>, «adquirir y conservar», es la preocupación por procurarse lo que no se tiene y guardar lo que se tiene; en <a class=\"vref\" href=\"capitulo-09.html#v22\" data-v=\"9.22\">9.22</a> Kṛṣṇa promete hacerse cargo de ella para quienes lo adoran.</p><p>La aparente paradoja —estar libre de las tres guṇas y a la vez «asentado siempre en sattva»— se resuelve de dos maneras: sattva, la cualidad de la claridad, sería el escalón desde el que se trasciende; o bien <em>sattva</em> tendría aquí su sentido etimológico de «ser, realidad», y el verso pediría permanecer en lo que siempre es. El capítulo 14 describe por extenso a quien ha trascendido las guṇas (<a class=\"vref\" href=\"capitulo-14.html#v22\" data-v=\"14.22\">14.22</a>–<a class=\"vref\" href=\"capitulo-14.html#v26\" data-v=\"14.26\">14.26</a>).</p>", "interp": [{"titulo": "Los Vedas, dentro del mundo condicionado", "html": "<p>Pocos versos muestran tan claramente la distancia que la Gītā toma respecto del ritualismo védico: decir que los Vedas «tratan de las tres guṇas» es situarlos dentro del mundo condicionado. La Gītā, sin embargo, no pide abandonar los ritos, sino hacerlos sin buscar su fruto, como un sacrificio que sostiene el orden del mundo (<a class=\"vref\" href=\"capitulo-03.html#v9\" data-v=\"3.9\">3.9</a>–<a class=\"vref\" href=\"capitulo-03.html#v15\" data-v=\"3.15\">3.15</a>).</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}, {"titulo": "Trascender las guṇas por la devoción", "html": "<p>La lectura devocional responde a la pregunta de cómo se trascienden las guṇas con la respuesta que el propio Kṛṣṇa dará en <a class=\"vref\" href=\"capitulo-14.html#v26\" data-v=\"14.26\">14.26</a>: quien le sirve con devoción inquebrantable supera las tres guṇas y se hace apto para <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "mas-alla-de-los-guna"}, {"n": 46, "hablante": "krsna", "sa": ["यावानर्थ उदपाने सर्वतः सम्प्लुतोदके ।", "तावान्सर्वेषु वेदेषु ब्राह्मणस्य विजानतः ॥४६॥"], "iast": ["yāvān artha udapāne sarvataḥ samplutodake", "tāvān sarveṣu vedeṣu brāhmaṇasya vijānataḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Tanta utilidad como tiene un pozo cuando el agua lo inunda todo, tanta tienen todos los <a class=\"t\" href=\"glosario.html#veda\" data-t=\"veda\">Vedas</a> para el <a class=\"t\" href=\"glosario.html#brahmana\" data-t=\"brahmana\">brahmán</a> que conoce.</span>", "palabras": [{"iast": "yāvān", "sa": "यावान्", "gram": "nom. sg. m. adj.", "es": "cuanta", "analisis": "relativo de cantidad"}, {"iast": "arthaḥ", "sa": "अर्थः", "gram": "nom. sg. m.", "es": "utilidad, provecho"}, {"iast": "udapāne", "sa": "उदपाने", "gram": "loc. sg. m.", "es": "en un pozo, en un estanque", "analisis": "uda (agua) + pāna (bebida)"}, {"iast": "sarvataḥ", "sa": "सर्वतः", "gram": "ind.", "es": "por todas partes"}, {"iast": "sampluta-udake", "sa": "सम्प्लुतोदके", "gram": "loc. sg. n. comp.", "es": "cuando el agua lo inunda todo", "analisis": "sampluta (desbordado, de sam-√plu) + udaka (agua)"}, {"iast": "tāvān", "sa": "तावान्", "gram": "nom. sg. m. adj.", "es": "tanta"}, {"iast": "sarveṣu", "sa": "सर्वेषु", "gram": "loc. pl. m. adj.", "es": "en todos"}, {"iast": "vedeṣu", "sa": "वेदेषु", "gram": "loc. pl. m.", "es": "en los Vedas", "ref": "veda"}, {"iast": "brāhmaṇasya", "sa": "ब्राह्मणस्य", "gram": "gen. sg. m.", "es": "para el brahmán", "ref": "brahmana"}, {"iast": "vijānataḥ", "sa": "विजानतः", "gram": "gen. sg. m. part. pres.", "es": "que conoce", "analisis": "vi-√jñā (conocer, discernir)"}], "nota": "<p>Verso de sentido discutido. La imagen: cuando el agua anega toda la comarca, un pozo o un estanque ya no presta un servicio especial, porque el agua está en todas partes. Así, para quien conoce, los Vedas —en su parte ritual— ya no aportan nada que no tenga. «Brahmán» designa aquí, más que al miembro de una clase, a quien conoce <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>.</p>", "interp": [{"titulo": "Lo menor contenido en lo mayor", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lee el verso como una comparación de magnitudes: todos los beneficios que procuran los ritos, como el agua repartida en muchos pequeños depósitos, quedan incluidos en la plenitud del conocimiento de brahman, como en una gran extensión de agua. No se trata de despreciar los ritos, sino de reconocer que su fruto está contenido en uno mayor.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Tomar sólo lo necesario", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> propone otra lectura: de un gran depósito que sirve para todos los usos, el sediento toma sólo el agua que necesita; del mismo modo, quien busca la liberación toma de los Vedas sólo lo que conduce a ella, y no todo lo que enseñan.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 47, "hablante": "krsna", "sa": ["कर्मण्येवाधिकारस्ते मा फलेषु कदाचन ।", "मा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि ॥४७॥"], "iast": ["karmaṇy evādhikāras te mā phaleṣu kadācana", "mā karma-phala-hetur bhūr mā te saṅgo 'stv akarmaṇi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Tu derecho es sólo a la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>, nunca a sus <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">frutos</a>. Que el fruto de la acción no sea tu motivo, ni te apegues a la inacción.</span>", "palabras": [{"iast": "karmaṇi", "sa": "कर्मणि", "gram": "loc. sg. n.", "es": "en la acción", "ref": "karma"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "sólo"}, {"iast": "adhikāraḥ", "sa": "अधिकारः", "gram": "nom. sg. m.", "es": "derecho, competencia", "analisis": "adhi-√kṛ (encargar, poner al frente): «lo que a uno le corresponde»"}, {"iast": "te", "sa": "ते", "gram": "gen. sg. pron.", "es": "tuyo, de ti"}, {"iast": "mā", "sa": "मा", "gram": "ind.", "es": "no (prohibición)"}, {"iast": "phaleṣu", "sa": "फलेषु", "gram": "loc. pl. n.", "es": "en los frutos", "ref": "phala"}, {"iast": "kadācana", "sa": "कदाचन", "gram": "ind.", "es": "nunca, en ningún momento"}, {"iast": "mā", "sa": "मा", "gram": "ind.", "es": "no"}, {"iast": "karma-phala-hetuḥ", "sa": "कर्मफलहेतुः", "gram": "nom. sg. m. comp.", "es": "movido por el fruto de la acción", "ref": "phala", "analisis": "karman (acción) + phala (fruto) + hetu (causa, motivo)"}, {"iast": "bhūḥ", "sa": "भूः", "gram": "2 sg. aor. act.", "es": "seas", "analisis": "√bhū (ser); aoristo sin aumento tras mā, que expresa prohibición"}, {"iast": "mā", "sa": "मा", "gram": "ind.", "es": "no"}, {"iast": "te", "sa": "ते", "gram": "gen. sg. pron.", "es": "tuyo"}, {"iast": "saṅgaḥ", "sa": "सङ्गः", "gram": "nom. sg. m.", "es": "apego", "analisis": "√sañj (adherirse)"}, {"iast": "astu", "sa": "अस्तु", "gram": "3 sg. impv. act.", "es": "haya", "analisis": "√as (ser)"}, {"iast": "akarmaṇi", "sa": "अकर्मणि", "gram": "loc. sg. n.", "es": "a la inacción", "ref": "karma", "analisis": "a (no) + karman (acción)"}], "nota": "<p>El verso más citado de la Gītā. Tiene cuatro miembros: el derecho (<em>adhikāra</em>) se limita a la acción; no se extiende a los frutos; el fruto no debe ser el motivo de obrar; y la conclusión no es dejar de actuar, porque también se puede uno apegar a la inacción. <em>Adhikāra</em> es un término técnico de la Mīmāṃsā, la exégesis del ritual védico: el derecho o la cualificación que habilita a alguien para realizar un rito y reclamar su fruto (es el tema del libro VI de los <em>Mīmāṃsā-sūtra</em>). Kṛṣṇa conserva la palabra pero corta el vínculo: hay título para actuar, no para cobrar.</p><p>El último miembro responde directamente a la tentación de Arjuna, que ha decidido no combatir (<a class=\"vref\" href=\"capitulo-01.html#v46\" data-v=\"1.46\">1.46</a>, <a class=\"vref\" href=\"capitulo-02.html#v9\" data-v=\"2.9\">2.9</a>).</p>", "interp": [{"titulo": "A ti te corresponde la acción", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> glosa: «tu competencia (<em>adhikāra</em>) es sólo para la acción, no para la firmeza en el conocimiento (<em>jñāna-niṣṭhā</em>)», la vida del renunciante dedicado sólo al conocimiento; en otros lugares dirá que el conocedor del sí-mismo sólo está habilitado para la renuncia (<a class=\"vref\" href=\"capitulo-02.html#v69\" data-v=\"2.69\">2.69</a>). Usa, pues, <em>adhikāra</em> en el sentido técnico de habilitación, pero en la segunda mitad, «nunca a sus frutos», lo entiende sin tecnicismo: «que no haya en ti sed del fruto». Como explica en los versos siguientes (<a class=\"vref\" href=\"capitulo-02.html#v48\" data-v=\"2.48\">2.48</a>, <a class=\"vref\" href=\"capitulo-02.html#v50\" data-v=\"2.50\">2.50</a>), la acción sin deseo no libera por sí misma, pero purifica la mente y lleva así al conocimiento, que es lo único que libera.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El karma-yoga como camino completo", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, el verso describe el <a class=\"t\" href=\"glosario.html#karma-yoga\" data-t=\"karma-yoga\"><em>karma-yoga</em></a> del que busca la liberación: tiene derecho a cumplir los ritos y deberes que le corresponden, pero no a sus frutos, porque la acción hecha por el fruto ata, mientras que la acción sin fruto, hecha como culto al Señor, es causa de liberación. Tampoco debe tenerse por agente: la agencia ha de atribuirse a las cualidades de la naturaleza o al Señor. Que este camino no sea una mera preparación, sino superior incluso para quien podría seguir el del conocimiento, lo sostendrá Rāmānuja al comentar <a class=\"vref\" href=\"capitulo-03.html#v8\" data-v=\"3.8\">3.8</a> y <a class=\"vref\" href=\"capitulo-05.html#v2\" data-v=\"5.2\">5.2</a>.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "El fruto se ofrece", "html": "<p>La lectura devocional completa el verso con <a class=\"vref\" href=\"capitulo-09.html#v27\" data-v=\"9.27\">9.27</a>: «Lo que hagas, lo que comas, lo que ofrezcas…, hazlo como ofrenda a mí». Renunciar al fruto no deja la acción sin destinatario: el fruto se ofrece a Kṛṣṇa. En la tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a>, esa acción ofrecida es el comienzo de la devoción.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}, {"titulo": "Tilak: la acción como mensaje central", "html": "<p><a class=\"t\" href=\"glosario.html#tilak\" data-t=\"tilak\">Tilak</a>, en su <em>Gītā-rahasya</em>, hizo de este verso el eje de la obra: la Gītā enseñaría ante todo el <a class=\"t\" href=\"glosario.html#karma-yoga\" data-t=\"karma-yoga\"><em>karma-yoga</em></a>, la acción desinteresada que el sabio sigue realizando incluso después de alcanzar el conocimiento, frente a la lectura de Śaṅkara, que veía en la renuncia la meta final. Su interpretación inspiró a una generación de nacionalistas indios a ver en la acción política desinteresada un deber religioso.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}, {"titulo": "Gandhi: el yoga del desapego", "html": "<p><a class=\"t\" href=\"glosario.html#gandhi\" data-t=\"gandhi\">Gandhi</a> tituló su traducción gujarati de la Gītā <em>Anāsakti-yoga</em>, «el yoga del desapego», y consideraba la renuncia al fruto de la acción el mensaje central del poema y la base de su propia práctica: actuar con todas las fuerzas, sin hacer depender la acción de su éxito.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}, {"titulo": "¿El deber por el deber?", "html": "<p>Muchos lectores occidentales han comparado el verso con la ética kantiana del deber por el deber. La semejanza es real —ambos separan el valor de la acción de sus consecuencias para quien la hace—, pero el fundamento difiere: en la Gītā el deber se define por el <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a> propio, y la renuncia al fruto tiene por meta la liberación del sí-mismo, no la autonomía de la razón.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "A ti te incumbe sólo la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>, nunca sus <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">frutos</a>. No seas causa de los frutos de la acción, ni te apegues a la inacción.", "nota": "<p>Dos opciones distintas de la traducción principal. <em>Adhikāra</em> puede entenderse no como «derecho» sino como «incumbencia, competencia»: lo que a uno le toca, más que lo que puede reclamar. Y <em>mā karma-phala-hetur bhūḥ</em> admite dos análisis del compuesto: «no seas alguien cuyo motivo es el fruto de la acción» (la traducción principal) o «no seas la causa (<em>hetu</em>) de los frutos de la acción», es decir, no obres como quien se tiene por autor de los resultados y los persigue.</p>"}], "ens": "actuar-sin-apego"}, {"n": 48, "hablante": "krsna", "sa": ["योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय ।", "सिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते ॥४८॥"], "iast": ["yoga-sthaḥ kuru karmāṇi saṅgaṃ tyaktvā dhanañjaya", "siddhy-asiddhyoḥ samo bhūtvā samatvaṃ yoga ucyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Establecido en el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>, realiza tus <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a> abandonando el apego, oh <a class=\"t\" href=\"glosario.html#dhananjaya\" data-t=\"dhananjaya\">Dhanañjaya</a>, igual ante el éxito y el fracaso: a esa <a class=\"t\" href=\"glosario.html#samatva\" data-t=\"samatva\">ecuanimidad</a> se la llama yoga.</span>", "palabras": [{"iast": "yoga-sthaḥ", "sa": "योगस्थः", "gram": "nom. sg. m. adj. comp.", "es": "establecido en el yoga", "ref": "yoga", "analisis": "yoga + stha (que está, de √sthā)"}, {"iast": "kuru", "sa": "कुरु", "gram": "2 sg. impv. act.", "es": "haz, realiza", "analisis": "√kṛ (hacer)"}, {"iast": "karmāṇi", "sa": "कर्माणि", "gram": "ac. pl. n.", "es": "las acciones", "ref": "karma"}, {"iast": "saṅgam", "sa": "सङ्गम्", "gram": "ac. sg. m.", "es": "el apego", "analisis": "√sañj (adherirse)"}, {"iast": "tyaktvā", "sa": "त्यक्त्वा", "gram": "abs.", "es": "abandonando", "analisis": "√tyaj (abandonar)"}, {"iast": "dhanañjaya", "sa": "धनञ्जय", "gram": "voc. sg. m.", "es": "oh Dhanañjaya", "ref": "dhananjaya"}, {"iast": "siddhy-asiddhyoḥ", "sa": "सिद्ध्यसिद्ध्योः", "gram": "loc. du. f. comp.", "es": "ante el éxito y el fracaso", "analisis": "siddhi (logro, de √sidh) + asiddhi (fracaso)"}, {"iast": "samaḥ", "sa": "समः", "gram": "nom. sg. m. adj.", "es": "igual, ecuánime"}, {"iast": "bhūtvā", "sa": "भूत्वा", "gram": "abs.", "es": "haciéndote", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "samatvam", "sa": "समत्वम्", "gram": "nom. sg. n.", "es": "la ecuanimidad", "ref": "samatva", "analisis": "sama (igual) + -tva (cualidad)"}, {"iast": "yogaḥ", "sa": "योगः", "gram": "nom. sg. m.", "es": "yoga", "ref": "yoga"}, {"iast": "ucyate", "sa": "उच्यते", "gram": "3 sg. pres. pas.", "es": "se llama", "analisis": "√vac (decir)"}], "nota": "<p>Primera de las definiciones de yoga que da la Gītā: <em>samatvaṃ yoga ucyate</em>, «la ecuanimidad se llama yoga». No es una postura ni un ejercicio de respiración, sino una actitud ante el resultado de los propios actos. La segunda definición llega dos versos después (<a class=\"vref\" href=\"capitulo-02.html#v50\" data-v=\"2.50\">2.50</a>); en <a class=\"vref\" href=\"capitulo-06.html#v23\" data-v=\"6.23\">6.23</a> se añadirá otra: el yoga como la desunión de la unión con el sufrimiento.</p>", "interp": [{"titulo": "Obrar sólo por el Señor", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> glosa «establecido en el yoga, realiza tus acciones» como obrar sólo por el Señor (<em>īśvarārtham</em>), y aun entonces abandonar el apego que piensa «que el Señor quede complacido conmigo». El éxito y el fracaso ante los que hay que quedar igual son, para él, el conocimiento que nace de la purificación de la mente y lo contrario. Así, el yoga de este verso es todavía un medio: la acción ofrecida sin pedir nada, ni siquiera el favor divino, que prepara para el conocimiento.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Aurobindo: la ecuanimidad como cimiento", "html": "<p><a class=\"t\" href=\"glosario.html#aurobindo\" data-t=\"aurobindo\">Śrī Aurobindo</a> veía en la ecuanimidad —<em>equality</em>, como traduce <em>samatva</em>— el centro del yoga de las obras: no indiferencia, sino «un estado de equilibrio y amplitud interiores que es el fundamento de la libertad espiritual». En sus <em>Essays on the Gita</em> la llama a la vez el signo del liberado y la prueba del aspirante. El primer paso es renunciar al fruto y aceptar con igualdad cualquier resultado; después hay que entregar al Señor la obra misma, hasta dejar de sentirse su agente.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}, {"titulo": "Ecuanimidad no es indiferencia", "html": "<p>El verso no pide que dé igual el resultado, sino que no se dependa de él: Arjuna debe hacer todo lo posible por vencer y, a la vez, quedar igual si no vence. La misma fórmula —igual ante el éxito y el fracaso— volverá en la descripción del que actúa sin quedar atado (<a class=\"vref\" href=\"capitulo-04.html#v22\" data-v=\"4.22\">4.22</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "actuar-sin-apego"}, {"n": 49, "hablante": "krsna", "sa": ["दूरेण ह्यवरं कर्म बुद्धियोगाद्धनञ्जय ।", "बुद्धौ शरणमन्विच्छ कृपणाः फलहेतवः ॥४९॥"], "iast": ["dūreṇa hy avaraṃ karma buddhi-yogād dhanañjaya", "buddhau śaraṇam anviccha kṛpaṇāḥ phala-hetavaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Muy inferior es la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a> al <a class=\"t\" href=\"glosario.html#buddhi-yoga\" data-t=\"buddhi-yoga\">yoga del entendimiento</a>, oh <a class=\"t\" href=\"glosario.html#dhananjaya\" data-t=\"dhananjaya\">Dhanañjaya</a>. Busca refugio en el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>: dignos de lástima son los que obran por el <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a>.</span>", "palabras": [{"iast": "dūreṇa", "sa": "दूरेण", "gram": "instr. sg. n. adv.", "es": "con mucho", "analisis": "de dūra (lejos)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "avaram", "sa": "अवरम्", "gram": "nom. sg. n. adj.", "es": "inferior"}, {"iast": "karma", "sa": "कर्म", "gram": "nom. sg. n.", "es": "la acción", "ref": "karma"}, {"iast": "buddhi-yogāt", "sa": "बुद्धियोगात्", "gram": "abl. sg. m. comp.", "es": "que el yoga del entendimiento", "ref": "buddhi-yoga", "analisis": "buddhi (entendimiento) + yoga"}, {"iast": "dhanañjaya", "sa": "धनञ्जय", "gram": "voc. sg. m.", "es": "oh Dhanañjaya", "ref": "dhananjaya"}, {"iast": "buddhau", "sa": "बुद्धौ", "gram": "loc. sg. f.", "es": "en el entendimiento", "ref": "buddhi"}, {"iast": "śaraṇam", "sa": "शरणम्", "gram": "ac. sg. n.", "es": "refugio"}, {"iast": "anviccha", "sa": "अन्विच्छ", "gram": "2 sg. impv. act.", "es": "busca", "analisis": "anu-√iṣ (buscar)"}, {"iast": "kṛpaṇāḥ", "sa": "कृपणाः", "gram": "nom. pl. m. adj.", "es": "dignos de lástima, mezquinos", "ref": "karpanya", "analisis": "de la familia de √kṛp (lamentarse); emparentado con kārpaṇya"}, {"iast": "phala-hetavaḥ", "sa": "फलहेतवः", "gram": "nom. pl. m. adj. comp.", "es": "los que obran por el fruto", "ref": "phala", "analisis": "phala (fruto) + hetu (motivo)"}], "nota": "<p>«Acción» significa aquí la acción hecha por el fruto, comparada con la que nace del entendimiento ecuánime: no se opone la acción a la contemplación, sino dos maneras de actuar. <em>Kṛpaṇa</em>, «digno de lástima, mezquino», pertenece a la misma familia que la palabra con que Arjuna había descrito su propio estado (<a class=\"t\" href=\"glosario.html#karpanya\" data-t=\"karpanya\"><em>kārpaṇya</em></a>, <a class=\"vref\" href=\"capitulo-02.html#v7\" data-v=\"2.7\">2.7</a>). La <em>Bṛhadāraṇyaka Upaniṣad</em> (3.8.10) llama <em>kṛpaṇa</em> a quien deja este mundo sin haber conocido lo imperecedero.</p>", "interp": [{"titulo": "Buscar refugio", "html": "<p><em>Śaraṇa</em>, «refugio», es una palabra cargada en la tradición devocional: es la misma con que Kṛṣṇa cerrará su enseñanza, «refúgiate sólo en mí» (<em>mām ekaṃ śaraṇaṃ vraja</em>, <a class=\"vref\" href=\"capitulo-18.html#v66\" data-v=\"18.66\">18.66</a>). Los comentaristas vaiṣṇavas leen aquí un primer paso en esa dirección: buscar refugio en el entendimiento es dejar de apoyarse en los propios cálculos sobre el resultado.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "destreza-en-la-accion"}, {"n": 50, "hablante": "krsna", "sa": ["बुद्धियुक्तो जहातीह उभे सुकृतदुष्कृते ।", "तस्माद्योगाय युज्यस्व योगः कर्मसु कौशलम् ॥५०॥"], "iast": ["buddhi-yukto jahātīha ubhe sukṛta-duṣkṛte", "tasmād yogāya yujyasva yogaḥ karmasu kauśalam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien está unido al <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> deja atrás, ya en esta vida, tanto la buena acción como la mala. Por eso, aplícate al <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>: el yoga es destreza en las <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a>.</span>", "palabras": [{"iast": "buddhi-yuktaḥ", "sa": "बुद्धियुक्तः", "gram": "nom. sg. m. adj. comp.", "es": "unido al entendimiento", "ref": "buddhi", "analisis": "buddhi + yukta (unido, de √yuj)"}, {"iast": "jahāti", "sa": "जहाति", "gram": "3 sg. pres. act.", "es": "deja atrás", "analisis": "√hā (abandonar)"}, {"iast": "iha", "sa": "इह", "gram": "ind.", "es": "aquí, en esta vida"}, {"iast": "ubhe", "sa": "उभे", "gram": "ac. du. n.", "es": "ambas"}, {"iast": "sukṛta-duṣkṛte", "sa": "सुकृतदुष्कृते", "gram": "ac. du. n. comp.", "es": "la buena acción y la mala", "analisis": "su-kṛta (bien hecho) + duṣ-kṛta (mal hecho), de √kṛ (hacer)"}, {"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. n. pron.", "es": "por eso"}, {"iast": "yogāya", "sa": "योगाय", "gram": "dat. sg. m.", "es": "al yoga", "ref": "yoga"}, {"iast": "yujyasva", "sa": "युज्यस्व", "gram": "2 sg. impv. pas.", "es": "aplícate, únete", "analisis": "√yuj (uncir, unir)"}, {"iast": "yogaḥ", "sa": "योगः", "gram": "nom. sg. m.", "es": "el yoga", "ref": "yoga"}, {"iast": "karmasu", "sa": "कर्मसु", "gram": "loc. pl. n.", "es": "en las acciones", "ref": "karma"}, {"iast": "kauśalam", "sa": "कौशलम्", "gram": "nom. sg. n.", "es": "destreza, habilidad", "analisis": "de kuśala (hábil, diestro)"}], "nota": "<p>Segunda definición del yoga: <em>yogaḥ karmasu kauśalam</em>, con un juego sobre la raíz <em>yuj</em>: «únete al yoga» (<em>yogāya yujyasva</em>). «Dejar atrás la buena acción y la mala» no significa que dé igual obrar bien o mal, sino que quien actúa sin apego no acumula méritos ni deméritos que lo aten a renacer: tampoco el mérito es la meta.</p>", "interp": [{"titulo": "La destreza de no quedar atado", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y los comentaristas clásicos, la «destreza» consiste en actuar de tal modo que la acción, que por naturaleza ata, pierda su poder de atar: el mismo acto que encadena a quien busca el fruto se convierte en camino de libertad para quien lo realiza con el entendimiento ecuánime.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "¿Excelencia profesional?", "html": "<p>En la India contemporánea, <em>yogaḥ karmasu kauśalam</em> se cita a menudo como lema de excelencia en el trabajo. La lectura «el yoga es la eficacia» no es falsa —<em>kauśala</em> es habilidad—, pero el contexto la matiza: la destreza que importa a Kṛṣṇa no es la de obtener mejores resultados, sino la de no quedar atado por lo que se hace.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "destreza-en-la-accion"}, {"n": 51, "hablante": "krsna", "sa": ["कर्मजं बुद्धियुक्ता हि फलं त्यक्त्वा मनीषिणः ।", "जन्मबन्धविनिर्मुक्ताः पदं गच्छन्त्यनामयम् ॥५१॥"], "iast": ["karma-jaṃ buddhi-yuktā hi phalaṃ tyaktvā manīṣiṇaḥ", "janma-bandha-vinirmuktāḥ padaṃ gacchanty anāmayam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pues los sabios unidos al <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>, abandonando el <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a> que nace de la <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acción</a>, libres de la atadura del nacimiento, alcanzan el estado libre de todo mal.</span>", "palabras": [{"iast": "karma-jam", "sa": "कर्मजम्", "gram": "ac. sg. n. adj. comp.", "es": "nacido de la acción", "ref": "karma", "analisis": "karman (acción) + ja (nacido, de √jan)"}, {"iast": "buddhi-yuktāḥ", "sa": "बुद्धियुक्ताः", "gram": "nom. pl. m. adj. comp.", "es": "unidos al entendimiento", "ref": "buddhi"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "phalam", "sa": "फलम्", "gram": "ac. sg. n.", "es": "el fruto", "ref": "phala"}, {"iast": "tyaktvā", "sa": "त्यक्त्वा", "gram": "abs.", "es": "abandonando", "analisis": "√tyaj (abandonar)"}, {"iast": "manīṣiṇaḥ", "sa": "मनीषिणः", "gram": "nom. pl. m.", "es": "los sabios", "analisis": "de manīṣā (reflexión, sabiduría), √man (pensar)"}, {"iast": "janma-bandha-vinirmuktāḥ", "sa": "जन्मबन्धविनिर्मुक्ताः", "gram": "nom. pl. m. adj. comp.", "es": "libres de la atadura del nacimiento", "analisis": "janman (nacimiento) + bandha (atadura) + vinirmukta (liberado, de vi-nis-√muc)"}, {"iast": "padam", "sa": "पदम्", "gram": "ac. sg. n.", "es": "el estado, la morada"}, {"iast": "gacchanti", "sa": "गच्छन्ति", "gram": "3 pl. pres. act.", "es": "alcanzan", "analisis": "√gam (ir)"}, {"iast": "anāmayam", "sa": "अनामयम्", "gram": "ac. sg. n. adj.", "es": "libre de todo mal", "analisis": "an (no) + āmaya (enfermedad, mal)"}], "nota": "<p>«El estado libre de todo mal» (<em>padam anāmayam</em>) es la <a class=\"t\" href=\"glosario.html#moksa\" data-t=\"moksa\">liberación</a>: <em>āmaya</em> es la enfermedad, y el <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">saṃsāra</a> se concibe a menudo como una enfermedad de la que hay que sanar. El verso cierra el argumento comenzado en <a class=\"vref\" href=\"capitulo-02.html#v39\" data-v=\"2.39\">2.39</a>: el yoga del entendimiento desata la «atadura de la acción».</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "destreza-en-la-accion"}, {"n": 52, "hablante": "krsna", "sa": ["यदा ते मोहकलिलं बुद्धिर्व्यतितरिष्यति ।", "तदा गन्तासि निर्वेदं श्रोतव्यस्य श्रुतस्य च ॥५२॥"], "iast": ["yadā te moha-kalilaṃ buddhir vyatitariṣyati", "tadā gantāsi nirvedaṃ śrotavyasya śrutasya ca"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Cuando tu <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> atraviese la espesura del <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extravío</a>, llegarás a desinteresarte de lo que queda por oír y de lo ya oído.</span>", "palabras": [{"iast": "yadā", "sa": "यदा", "gram": "ind.", "es": "cuando"}, {"iast": "te", "sa": "ते", "gram": "gen. sg. pron.", "es": "tu"}, {"iast": "moha-kalilam", "sa": "मोहकलिलम्", "gram": "ac. sg. n. comp.", "es": "la espesura del extravío", "ref": "moha", "analisis": "moha (extravío, de √muh) + kalila (espesura, mezcla confusa)"}, {"iast": "buddhiḥ", "sa": "बुद्धिः", "gram": "nom. sg. f.", "es": "el entendimiento", "ref": "buddhi"}, {"iast": "vyatitariṣyati", "sa": "व्यतितरिष्यति", "gram": "3 sg. fut. act.", "es": "atraviese", "analisis": "vi-ati-√tṝ (cruzar al otro lado)"}, {"iast": "tadā", "sa": "तदा", "gram": "ind.", "es": "entonces"}, {"iast": "gantāsi", "sa": "गन्तासि", "gram": "2 sg. fut. act.", "es": "llegarás", "analisis": "futuro perifrástico de √gam (ir)"}, {"iast": "nirvedam", "sa": "निर्वेदम्", "gram": "ac. sg. m.", "es": "al desinterés, al desengaño", "analisis": "nis-√vid (desengañarse, cansarse de algo)"}, {"iast": "śrotavyasya", "sa": "श्रोतव्यस्य", "gram": "gen. sg. n. gerundivo", "es": "de lo que queda por oír", "analisis": "√śru (oír)"}, {"iast": "śrutasya", "sa": "श्रुतस्य", "gram": "gen. sg. n. ppp", "es": "de lo ya oído", "analisis": "√śru (oír)"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}], "nota": "<p>«Lo oído» (<em>śruta</em>) alude a la revelación que se escucha, la <a class=\"t\" href=\"glosario.html#sruti\" data-t=\"sruti\"><em>śruti</em></a>, y en particular a las promesas de los ritos de las que se ha hablado en <a class=\"vref\" href=\"capitulo-02.html#v42\" data-v=\"2.42\">2.42</a>–<a class=\"vref\" href=\"capitulo-02.html#v46\" data-v=\"2.46\">2.46</a>. Quien ha visto por sí mismo ya no necesita que le prometan nada. <em>Nirveda</em> no es un hastío amargo, sino el desengaño sereno de quien ha dejado de esperar de lo condicionado lo que no puede dar.</p>", "interp": [{"titulo": "La espesura del extravío", "html": "<p>Para los comentaristas vedánticos, la «espesura del extravío» es la confusión entre el sí-mismo y lo que no lo es: el cuerpo, la mente, sus obras. Cuando el entendimiento la atraviesa, los frutos que prometen los ritos —en este mundo o en el otro— pierden su atractivo, porque se ve que son pasajeros.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "entendimiento-inmovil"}, {"n": 53, "hablante": "krsna", "sa": ["श्रुतिविप्रतिपन्ना ते यदा स्थास्यति निश्चला ।", "समाधावचला बुद्धिस्तदा योगमवाप्स्यसि ॥५३॥"], "iast": ["śruti-vipratipannā te yadā sthāsyati niścalā", "samādhāv acalā buddhis tadā yogam avāpsyasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Cuando tu <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>, ahora desconcertado por lo que has oído, permanezca inmóvil y firme en el <a class=\"t\" href=\"glosario.html#samadhi\" data-t=\"samadhi\">samādhi</a>, entonces alcanzarás el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>.</span>", "palabras": [{"iast": "śruti-vipratipannā", "sa": "श्रुतिविप्रतिपन्ना", "gram": "nom. sg. f. adj. comp.", "es": "desconcertado por lo oído", "ref": "sruti", "analisis": "śruti (lo oído, la revelación) + vipratipanna (confundido, de vi-prati-√pad)"}, {"iast": "te", "sa": "ते", "gram": "gen. sg. pron.", "es": "tu"}, {"iast": "yadā", "sa": "यदा", "gram": "ind.", "es": "cuando"}, {"iast": "sthāsyati", "sa": "स्थास्यति", "gram": "3 sg. fut. act.", "es": "permanezca", "analisis": "√sthā (estar de pie, permanecer)"}, {"iast": "niścalā", "sa": "निश्चला", "gram": "nom. sg. f. adj.", "es": "inmóvil", "analisis": "nis (sin) + cala (que se mueve)"}, {"iast": "samādhau", "sa": "समाधौ", "gram": "loc. sg. m.", "es": "en el samādhi", "ref": "samadhi"}, {"iast": "acalā", "sa": "अचला", "gram": "nom. sg. f. adj.", "es": "firme", "analisis": "a (no) + cala (que se mueve)"}, {"iast": "buddhiḥ", "sa": "बुद्धिः", "gram": "nom. sg. f.", "es": "el entendimiento", "ref": "buddhi"}, {"iast": "tadā", "sa": "तदा", "gram": "ind.", "es": "entonces"}, {"iast": "yogam", "sa": "योगम्", "gram": "ac. sg. m.", "es": "el yoga", "ref": "yoga"}, {"iast": "avāpsyasi", "sa": "अवाप्स्यसि", "gram": "2 sg. fut. act.", "es": "alcanzarás", "analisis": "ava-√āp (obtener)"}], "nota": "<p>Las palabras <em>niścalā</em> y <em>acalā</em>, «inmóvil» y «firme», preparan la pregunta inmediata de Arjuna por el hombre de «sabiduría firme» (<em>sthita-prajña</em>, <a class=\"vref\" href=\"capitulo-02.html#v54\" data-v=\"2.54\">2.54</a>), con la que comienza la última parte del capítulo. <em>Śruti-vipratipanna</em> admite dos lecturas: desconcertado por las muchas y contradictorias promesas de los textos sagrados, o, más en general, por todo lo que uno ha oído decir.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "entendimiento-inmovil"}, {"n": 54, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "स्थितप्रज्ञस्य का भाषा समाधिस्थस्य केशव ।", "स्थितधीः किं प्रभाषेत किमासीत व्रजेत किम् ॥५४॥"], "iast": ["arjuna uvāca", "sthita-prajñasya kā bhāṣā samādhi-sthasya keśava", "sthita-dhīḥ kiṃ prabhāṣeta kim āsīta vrajeta kim"], "rojas": [], "t": "<span class=\"vt-parte\">¿Cómo se describe al de <a class=\"t\" href=\"glosario.html#sthitaprajna\" data-t=\"sthitaprajna\">sabiduría firme</a>, oh <a class=\"t\" href=\"glosario.html#kesava\" data-t=\"kesava\">Keśava</a>, al que permanece en el <a class=\"t\" href=\"glosario.html#samadhi\" data-t=\"samadhi\">samādhi</a>? El de pensamiento firme, ¿cómo habla, cómo se sienta, cómo camina?</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "sthita-prajñasya", "sa": "स्थितप्रज्ञस्य", "gram": "gen. sg. m. comp.", "es": "del de sabiduría firme", "ref": "sthitaprajna", "analisis": "sthita (firme, asentado; ppp de √sthā, estar de pie) + prajñā (sabiduría)"}, {"iast": "kā", "sa": "का", "gram": "nom. sg. f. pron.", "es": "¿cuál?"}, {"iast": "bhāṣā", "sa": "भाषा", "gram": "nom. sg. f.", "es": "descripción, lo que se dice de él", "analisis": "√bhāṣ (hablar)"}, {"iast": "samādhi-sthasya", "sa": "समाधिस्थस्य", "gram": "gen. sg. m. comp.", "es": "del que permanece en el samādhi", "ref": "samadhi", "analisis": "samādhi (concentración, absorción) + stha (que está; de √sthā)"}, {"iast": "keśava", "sa": "केशव", "gram": "voc. sg. m.", "es": "oh Keśava", "ref": "kesava"}, {"iast": "sthita-dhīḥ", "sa": "स्थितधीः", "gram": "nom. sg. m. comp.", "es": "el de pensamiento firme", "analisis": "sthita (firme) + dhī (pensamiento, visión interior; de √dhī, pensar)"}, {"iast": "kim", "sa": "किम्", "gram": "ac. sg. n. pron.", "es": "¿cómo?", "analisis": "usado como adverbio interrogativo"}, {"iast": "prabhāṣeta", "sa": "प्रभाषेत", "gram": "3 sg. opt. med.", "es": "hablaría", "analisis": "pra + √bhāṣ (hablar)"}, {"iast": "kim", "sa": "किम्", "gram": "ac. sg. n. pron.", "es": "¿cómo?"}, {"iast": "āsīta", "sa": "आसीत", "gram": "3 sg. opt. med.", "es": "se sentaría", "analisis": "√ās (sentarse, estar)"}, {"iast": "vrajeta", "sa": "व्रजेत", "gram": "3 sg. opt. med.", "es": "caminaría", "analisis": "√vraj (ir, caminar); forma media irregular, propia del sánscrito épico"}, {"iast": "kim", "sa": "किम्", "gram": "ac. sg. n. pron.", "es": "¿cómo?"}], "nota": "<p>Arjuna recoge las palabras con que Kṛṣṇa acaba de cerrar el verso anterior: un <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> firme e inmóvil en el <a class=\"t\" href=\"glosario.html#samadhi\" data-t=\"samadhi\">samādhi</a> (<a class=\"vref\" href=\"capitulo-02.html#v53\" data-v=\"2.53\">2.53</a>). <em>Sthita-prajña</em>, «el de sabiduría firme», y <em>sthita-dhī</em>, «el de pensamiento firme», son aquí sinónimos.</p><p>Los verbos están en optativo («¿cómo hablaría…?»): Arjuna pide señas reconocibles de un estado interior. <em>Vrajeta</em> es una forma media irregular del verbo <em>vraj</em>, «caminar», propia del sánscrito épico. La respuesta de Kṛṣṇa ocupa el resto del capítulo (<a class=\"vref\" href=\"capitulo-02.html#v55\" data-v=\"2.55\">2.55</a>–<a class=\"vref\" href=\"capitulo-02.html#v72\" data-v=\"2.72\">2.72</a>).</p>", "interp": [{"titulo": "Una pregunta práctica, una respuesta interior", "html": "<p>Arjuna pregunta por la conducta visible: cómo habla, cómo se sienta, cómo camina el sabio. Kṛṣṇa responde casi siempre con disposiciones interiores (lo que ha soltado, lo que no le turba, lo que domina), y sólo de paso con gestos externos, como el retiro de los sentidos. La forma misma del diálogo sugiere que la sabiduría no se reconoce por señales exteriores, sino por la relación de cada uno con sus deseos.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Los versos de la oración de cada tarde", "html": "<p>Los versos <a class=\"vref\" href=\"capitulo-02.html#v54\" data-v=\"2.54\">2.54</a>–<a class=\"vref\" href=\"capitulo-02.html#v72\" data-v=\"2.72\">2.72</a> se recitaban en la oración vespertina del āśram de <a class=\"t\" href=\"glosario.html#gandhi\" data-t=\"gandhi\">Gandhi</a>, que veía en ellos el retrato del ideal que la Gītā propone a todos, no sólo a los ascetas. Vinoba Bhave, su discípulo, les dedicó un libro entero, <em>Sthitaprajña-darśana</em> (en inglés, <em>The Steadfast Wisdom</em>), nacido de las charlas en marathi que dio a sus compañeros de prisión en la cárcel de Seoni en 1944. Para esta lectura, el sabio de sabiduría firme no es un ermitaño, sino alguien que actúa en el mundo sin ser arrastrado por él.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 55, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "प्रजहाति यदा कामान्सर्वान्पार्थ मनोगतान् ।", "आत्मन्येवात्मना तुष्टः स्थितप्रज्ञस्तदोच्यते ॥५५॥"], "iast": ["śrī-bhagavān uvāca", "prajahāti yadā kāmān sarvān pārtha mano-gatān", "ātmany evātmanā tuṣṭaḥ sthita-prajñas tadocyate"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Cuando abandona todos los <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseos</a> que han entrado en la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a>, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>, y halla su contento sólo en el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>, por el sí-mismo, entonces se le llama de <a class=\"t\" href=\"glosario.html#sthitaprajna\" data-t=\"sthitaprajna\">sabiduría firme</a>.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (esplendor, fortuna; aquí, título de respeto) + bhagavat (el que posee bhaga, «fortuna, majestad»)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "prajahāti", "sa": "प्रजहाति", "gram": "3 sg. pres. act.", "es": "abandona", "analisis": "pra + √hā (dejar, abandonar)"}, {"iast": "yadā", "sa": "यदा", "gram": "ind.", "es": "cuando"}, {"iast": "kāmān", "sa": "कामान्", "gram": "ac. pl. m.", "es": "los deseos", "ref": "kama", "analisis": "√kam (desear)"}, {"iast": "sarvān", "sa": "सर्वान्", "gram": "ac. pl. m. adj.", "es": "todos"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "mano-gatān", "sa": "मनोगतान्", "gram": "ac. pl. m. adj. comp.", "es": "que han entrado en la mente", "ref": "manas", "analisis": "manas (mente) + gata (ido, llegado; ppp de √gam, ir)"}, {"iast": "ātmani", "sa": "आत्मनि", "gram": "loc. sg. m.", "es": "en el sí-mismo", "ref": "atman"}, {"iast": "eva", "sa": "एव", "gram": "ind.", "es": "sólo, precisamente"}, {"iast": "ātmanā", "sa": "आत्मना", "gram": "instr. sg. m.", "es": "por el sí-mismo", "ref": "atman"}, {"iast": "tuṣṭaḥ", "sa": "तुष्टः", "gram": "nom. sg. m. ppp", "es": "contento, satisfecho", "analisis": "√tuṣ (estar contento)"}, {"iast": "sthita-prajñaḥ", "sa": "स्थितप्रज्ञः", "gram": "nom. sg. m. comp.", "es": "de sabiduría firme", "ref": "sthitaprajna"}, {"iast": "tadā", "sa": "तदा", "gram": "ind.", "es": "entonces"}, {"iast": "ucyate", "sa": "उच्यते", "gram": "3 sg. pres. pas.", "es": "se le llama", "analisis": "√vac (hablar), pasiva"}], "nota": "<p>Primera respuesta: el sabio se reconoce por lo que ha soltado. <em>Mano-gata</em>, «que han ido a la mente», presenta los deseos como algo que ha entrado en la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> y puede salir de ella, no como parte del <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>.</p><p>La fórmula <em>ātmany evātmanā tuṣṭaḥ</em> repite <em>ātman</em>: «contento en el sí-mismo por el sí-mismo», es decir, sin necesitar nada de fuera. Puede leerse también de modo reflexivo, «contento en sí mismo, por sí mismo»; la traducción conserva el sentido técnico porque toda esta sección habla del conocimiento del sí-mismo.</p>", "interp": [{"titulo": "Rasgos de la meta, medios del camino", "html": "<p>Al comenzar su comentario a este verso, <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> enuncia un principio que aplica a toda la sección: en los textos sobre el sí-mismo, las señas de quien ya ha alcanzado la meta son a la vez los medios que debe cultivar quien aspira a ella, porque se adquieren con esfuerzo. Así, la descripción del de sabiduría firme no es sólo un retrato del sabio, sino un programa de práctica para el discípulo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El contento que no depende de nada", "html": "<p>Los comentaristas vedánticos subrayan el <em>eva</em>, «sólo»: no basta con desear menos; el sabio está contento en el sí-mismo <em>y sólo en él</em>. Mientras la satisfacción dependa de algo externo, el deseo volverá. La renuncia que aquí se describe no es represión, sino la consecuencia natural de haber encontrado una plenitud que no necesita objetos.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "rasgos-sabiduria-firme"}, {"n": 56, "hablante": "krsna", "sa": ["दुःखेष्वनुद्विग्नमनाः सुखेषु विगतस्पृहः ।", "वीतरागभयक्रोधः स्थितधीर्मुनिरुच्यते ॥५६॥"], "iast": ["duḥkheṣv anudvigna-manāḥ sukheṣu vigata-spṛhaḥ", "vīta-rāga-bhaya-krodhaḥ sthita-dhīr munir ucyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Aquel cuya mente no se turba en las desdichas y que no ansía los placeres, libre de apego, de miedo y de <a class=\"t\" href=\"glosario.html#krodha\" data-t=\"krodha\">ira</a>, ése, de pensamiento firme, es llamado <a class=\"t\" href=\"glosario.html#muni\" data-t=\"muni\">sabio</a>.</span>", "palabras": [{"iast": "duḥkheṣu", "sa": "दुःखेषु", "gram": "loc. pl. n.", "es": "en las desdichas"}, {"iast": "anudvigna-manāḥ", "sa": "अनुद्विग्नमनाः", "gram": "nom. sg. m. adj. comp.", "es": "cuya mente no se turba", "ref": "manas", "analisis": "an (no) + udvigna (agitado; ppp de ud-√vij, estremecerse) + manas (mente)"}, {"iast": "sukheṣu", "sa": "सुखेषु", "gram": "loc. pl. n.", "es": "en los placeres"}, {"iast": "vigata-spṛhaḥ", "sa": "विगतस्पृहः", "gram": "nom. sg. m. adj. comp.", "es": "sin ansia", "analisis": "vigata (desaparecido; ppp de vi-√gam) + spṛhā (anhelo, ansia)"}, {"iast": "vīta-rāga-bhaya-krodhaḥ", "sa": "वीतरागभयक्रोधः", "gram": "nom. sg. m. adj. comp.", "es": "libre de apego, de miedo y de ira", "ref": "krodha", "analisis": "vīta (ido; de vi-√i) + rāga (apego, pasión; de √rañj, teñirse) + bhaya (miedo) + krodha (ira)"}, {"iast": "sthita-dhīḥ", "sa": "स्थितधीः", "gram": "nom. sg. m. comp.", "es": "de pensamiento firme"}, {"iast": "muniḥ", "sa": "मुनिः", "gram": "nom. sg. m.", "es": "sabio", "ref": "muni"}, {"iast": "ucyate", "sa": "उच्यते", "gram": "3 sg. pres. pas.", "es": "es llamado", "analisis": "√vac (hablar), pasiva"}], "nota": "<p>Tres rasgos: la desdicha no agita su mente, el placer no despierta su ansia, y las emociones que nacen de ambos —el apego (<em>rāga</em>), el miedo y la ira— se han ido. <em>Rāga</em> viene de una raíz que significa «teñirse, colorearse»: el apego es lo que tiñe la mente con el color de sus objetos.</p><p><em>Muni</em> designa al sabio, tradicionalmente asociado con el silencio (<em>mauna</em>); la Gītā lo identifica aquí con el de pensamiento firme. El compuesto <em>vīta-rāga-bhaya-krodha</em> reaparece literalmente en <a class=\"vref\" href=\"capitulo-04.html#v10\" data-v=\"4.10\">4.10</a>.</p>", "interp": [{"titulo": "Ecuanimidad, no indiferencia", "html": "<p>El verso retoma lo que Kṛṣṇa ya había pedido a Arjuna: soportar el frío y el calor, el placer y el dolor (<a class=\"vref\" href=\"capitulo-02.html#v14\" data-v=\"2.14\">2.14</a>–<a class=\"vref\" href=\"capitulo-02.html#v15\" data-v=\"2.15\">2.15</a>), y combatir tratando por igual placer y dolor, ganancia y pérdida (<a class=\"vref\" href=\"capitulo-02.html#v38\" data-v=\"2.38\">2.38</a>). El sabio sigue sintiendo dolor y placer; lo que ha desaparecido es la agitación y el ansia que los acompañan. En <a class=\"vref\" href=\"capitulo-04.html#v10\" data-v=\"4.10\">4.10</a> el mismo compuesto describirá a quienes, libres de apego, miedo e ira, se han refugiado en Kṛṣṇa: allí la ecuanimidad aparece ligada a la devoción.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "rasgos-sabiduria-firme"}, {"n": 57, "hablante": "krsna", "sa": ["यः सर्वत्रानभिस्नेहस्तत्तत्प्राप्य शुभाशुभम् ।", "नाभिनन्दति न द्वेष्टि तस्य प्रज्ञा प्रतिष्ठिता ॥५७॥"], "iast": ["yaḥ sarvatrānabhisnehas tat tat prāpya śubhāśubham", "nābhinandati na dveṣṭi tasya prajñā pratiṣṭhitā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El que no siente apego por nada y, cuando le llega esto o aquello, bueno o malo, ni lo celebra ni lo aborrece: su <a class=\"t\" href=\"glosario.html#prajna\" data-t=\"prajna\">sabiduría</a> está asentada.</span>", "palabras": [{"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron.", "es": "el que"}, {"iast": "sarvatra", "sa": "सर्वत्र", "gram": "ind.", "es": "en todo, hacia todo"}, {"iast": "anabhisnehaḥ", "sa": "अनभिस्नेहः", "gram": "nom. sg. m. adj.", "es": "sin apego", "analisis": "an (no) + abhisneha (afecto, apego; de abhi-√snih, ser pegajoso, adherirse)"}, {"iast": "tat tat", "sa": "तत् तत्", "gram": "ac. sg. n. pron.", "es": "esto o aquello", "analisis": "pronombre repetido: «cualquier cosa que sea»"}, {"iast": "prāpya", "sa": "प्राप्य", "gram": "abs.", "es": "al obtener", "analisis": "pra + √āp (alcanzar)"}, {"iast": "śubha-aśubham", "sa": "शुभाशुभम्", "gram": "ac. sg. n. comp.", "es": "bueno o malo", "analisis": "śubha (propicio, bueno) + aśubha (desfavorable, malo)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "abhinandati", "sa": "अभिनन्दति", "gram": "3 sg. pres. act.", "es": "se alegra, lo celebra", "analisis": "abhi + √nand (alegrarse)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "dveṣṭi", "sa": "द्वेष्टि", "gram": "3 sg. pres. act.", "es": "aborrece", "analisis": "√dviṣ (odiar)"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. m. pron.", "es": "de él, su"}, {"iast": "prajñā", "sa": "प्रज्ञा", "gram": "nom. sg. f.", "es": "sabiduría", "ref": "prajna", "analisis": "pra + √jñā (conocer)"}, {"iast": "pratiṣṭhitā", "sa": "प्रतिष्ठिता", "gram": "nom. sg. f. ppp", "es": "asentada, firme", "analisis": "prati + √sthā (estar de pie, mantenerse)"}], "nota": "<p><em>Anabhisneha</em> es «sin apego»: <em>sneha</em> es literalmente «aceite, grasa», y de ahí «afecto», lo que hace que una cosa se pegue a otra. <em>Abhinandati</em> es «saludar con alegría, celebrar»; <em>dveṣṭi</em>, «odiar, rechazar». El sabio no es insensible: recibe lo bueno y lo malo (<em>śubhāśubha</em>), pero no lo acoge con euforia ni lo rechaza con aversión.</p><p>La frase final, «su sabiduría está asentada» (<em>tasya prajñā pratiṣṭhitā</em>), funciona como estribillo: cierra también <a class=\"vref\" href=\"capitulo-02.html#v58\" data-v=\"2.58\">2.58</a>, <a class=\"vref\" href=\"capitulo-02.html#v61\" data-v=\"2.61\">2.61</a> y <a class=\"vref\" href=\"capitulo-02.html#v68\" data-v=\"2.68\">2.68</a>.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "rasgos-sabiduria-firme"}, {"n": 58, "hablante": "krsna", "sa": ["यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः ।", "इन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता ॥५८॥"], "iast": ["yadā saṃharate cāyaṃ kūrmo 'ṅgānīva sarvaśaḥ", "indriyāṇīndriyārthebhyas tasya prajñā pratiṣṭhitā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y cuando retira por completo los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a> de los <a class=\"t\" href=\"glosario.html#visaya\" data-t=\"visaya\">objetos de los sentidos</a>, como la tortuga recoge sus miembros, su sabiduría está asentada.</span>", "palabras": [{"iast": "yadā", "sa": "यदा", "gram": "ind.", "es": "cuando"}, {"iast": "saṃharate", "sa": "संहरते", "gram": "3 sg. pres. med.", "es": "retira, recoge", "analisis": "sam + √hṛ (llevar): «recoger, retraer»"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "ayam", "sa": "अयम्", "gram": "nom. sg. m. pron.", "es": "éste"}, {"iast": "kūrmaḥ", "sa": "कूर्मः", "gram": "nom. sg. m.", "es": "la tortuga"}, {"iast": "aṅgāni", "sa": "अङ्गानि", "gram": "ac. pl. n.", "es": "los miembros"}, {"iast": "iva", "sa": "इव", "gram": "ind.", "es": "como"}, {"iast": "sarvaśaḥ", "sa": "सर्वशः", "gram": "ind.", "es": "por completo, por todas partes"}, {"iast": "indriyāṇi", "sa": "इन्द्रियाणि", "gram": "ac. pl. n.", "es": "los sentidos", "ref": "indriya"}, {"iast": "indriya-arthebhyaḥ", "sa": "इन्द्रियार्थेभ्यः", "gram": "abl. pl. m. comp.", "es": "de los objetos de los sentidos", "ref": "visaya", "analisis": "indriya (sentido) + artha (objeto, aquello a lo que se dirige)"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. m. pron.", "es": "de él, su"}, {"iast": "prajñā", "sa": "प्रज्ञा", "gram": "nom. sg. f.", "es": "sabiduría", "ref": "prajna", "analisis": "pra + √jñā (conocer)"}, {"iast": "pratiṣṭhitā", "sa": "प्रतिष्ठिता", "gram": "nom. sg. f. ppp", "es": "asentada, firme", "analisis": "prati + √sthā (estar de pie, mantenerse)"}], "nota": "<p>La tortuga recoge la cabeza y las patas bajo el caparazón: un retiro completo (<em>sarvaśaḥ</em>) y voluntario, que puede deshacerse cuando se quiera. La tortuga no pierde sus miembros; los guarda. <em>Indriyārtha</em>, «objeto de los sentidos», es sinónimo de <a class=\"t\" href=\"glosario.html#visaya\" data-t=\"visaya\"><em>viṣaya</em></a>. El verbo <em>saṃharate</em>, «recoge», está en voz media: el sabio lo hace para sí mismo.</p><p>Con este verso la descripción se vuelve práctica: no sólo cómo es el sabio, sino qué hace.</p>", "interp": [{"titulo": "Volver la mirada hacia dentro", "html": "<p>La imagen prolonga una idea de las <a class=\"t\" href=\"glosario.html#upanisad\" data-t=\"upanisad\">Upaniṣads</a>. La <a class=\"t\" href=\"glosario.html#katha-upanisad\" data-t=\"katha-upanisad\">Kaṭha Upaniṣad</a> (2.1.1) dice que el creador horadó los sentidos hacia fuera, y que por eso el ser humano mira hacia fuera y no hacia su interior; sólo algún sabio, deseando la inmortalidad, vuelve la mirada hacia dentro y ve el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>. Retirar los sentidos como la tortuga es ese giro de la atención.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}, {"titulo": "La tortuga y el pratyāhāra", "html": "<p>Los estudiosos relacionan este verso con el <em>pratyāhāra</em>, «retracción» de los sentidos, quinto de los ocho miembros del yoga que enumeran los <em>Yoga-sūtra</em> atribuidos a Patañjali (2.54 lo define como el estado en que los sentidos, desconectados de sus objetos, imitan por así decir la naturaleza propia de la mente). La Gītā no usa ese término técnico y su datación respecto a los <em>Yoga-sūtra</em> se discute; pero ambos textos comparten la misma práctica: dejar de alimentar los sentidos para que la mente se aquiete.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "retirar-los-sentidos"}, {"n": 59, "hablante": "krsna", "sa": ["विषया विनिवर्तन्ते निराहारस्य देहिनः ।", "रसवर्जं रसोऽप्यस्य परं दृष्ट्वा निवर्तते ॥५९॥"], "iast": ["viṣayā vinivartante nirāhārasya dehinaḥ", "rasa-varjaṃ raso 'py asya paraṃ dṛṣṭvā nivartate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Los objetos de los sentidos se apartan del <a class=\"t\" href=\"glosario.html#dehin\" data-t=\"dehin\">que habita el cuerpo</a> cuando éste se abstiene de ellos, pero no el gusto por ellos; también el gusto se aparta de él cuando ha visto lo supremo.</span>", "palabras": [{"iast": "viṣayāḥ", "sa": "विषयाः", "gram": "nom. pl. m.", "es": "los objetos de los sentidos", "ref": "visaya"}, {"iast": "vinivartante", "sa": "विनिवर्तन्ते", "gram": "3 pl. pres. med.", "es": "se apartan", "analisis": "vi + ni + √vṛt (volverse): «volverse atrás, retirarse»"}, {"iast": "nirāhārasya", "sa": "निराहारस्य", "gram": "gen. sg. m. adj.", "es": "del que se abstiene (de ellos)", "analisis": "nis (sin) + āhāra (alimento, lo que se toma; de ā-√hṛ, tomar)"}, {"iast": "dehinaḥ", "sa": "देहिनः", "gram": "gen. sg. m.", "es": "del que habita el cuerpo", "ref": "dehin", "analisis": "deha (cuerpo) + -in (que posee)"}, {"iast": "rasa-varjam", "sa": "रसवर्जम्", "gram": "ind.", "es": "salvo el gusto", "analisis": "rasa (jugo, sabor, gusto) + varja (exceptuado; de √vṛj, apartar); acusativo adverbial"}, {"iast": "rasaḥ", "sa": "रसः", "gram": "nom. sg. m.", "es": "el gusto"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "también"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. m. pron.", "es": "de él"}, {"iast": "param", "sa": "परम्", "gram": "ac. sg. n. adj.", "es": "lo supremo"}, {"iast": "dṛṣṭvā", "sa": "दृष्ट्वा", "gram": "abs.", "es": "tras ver", "analisis": "√dṛś (ver)"}, {"iast": "nivartate", "sa": "निवर्तते", "gram": "3 sg. pres. med.", "es": "se aparta", "analisis": "ni + √vṛt (volverse)"}], "nota": "<p>Verso difícil y muy comentado. <em>Nirāhāra</em> significa literalmente «sin alimento»: el que ayuna, y por extensión el que no «toma» los objetos de los sentidos, porque en el pensamiento indio la percepción es una forma de alimentarse. La abstinencia aleja los objetos, pero no el <em>rasa</em> —«jugo, sabor, gusto»—, el anhelo que queda cuando el objeto ya no está. Sólo la visión de lo supremo (<em>param</em>) lo extingue.</p><p>Qué sea ese «supremo» es lo que separa a los comentaristas. Para la práctica, el verso advierte que la técnica anterior, retirar los sentidos, no basta por sí sola.</p>", "interp": [{"titulo": "El gusto sutil y la visión de brahman", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende <em>nirāhāra</em> como el que no toma los objetos de los sentidos, incluso el necio que se somete a una austeridad penosa: a él se le retiran los objetos, pero queda un apego sutil, el <em>rasa</em>. Ese resto sólo desaparece cuando ve lo supremo, el <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, la realidad última, y conoce que él mismo es eso. La disciplina prepara; sólo el conocimiento libera.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La dicha mayor del sí-mismo", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee <em>param</em> como el <a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">sí-mismo</a>, cuya naturaleza es una dicha superior a la de cualquier objeto: el gusto por los objetos se apaga cuando se ha visto algo más deseable. Su lectura prepara la del verso <a class=\"vref\" href=\"capitulo-02.html#v61\" data-v=\"2.61\">2.61</a>, donde Kṛṣṇa se presenta como el apoyo que hace posible esa visión.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Un gusto más alto", "html": "<p>La tradición gauḍīya hace de este verso una clave de la vida devocional. Bhaktivedanta Swami Prabhupāda lo traduce hablando de experimentar «un gusto más elevado»: la renuncia forzada no dura, porque el anhelo sigue ahí; sólo cuando el corazón encuentra un sabor superior —el de la devoción a Kṛṣṇa— los placeres menores pierden su atractivo sin esfuerzo.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "retirar-los-sentidos"}, {"n": 60, "hablante": "krsna", "sa": ["यततो ह्यपि कौन्तेय पुरुषस्य विपश्चितः ।", "इन्द्रियाणि प्रमाथीनि हरन्ति प्रसभं मनः ॥६०॥"], "iast": ["yatato hy api kaunteya puruṣasya vipaścitaḥ", "indriyāṇi pramāthīni haranti prasabhaṃ manaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Porque los sentidos turbulentos, oh <a class=\"t\" href=\"glosario.html#kaunteya\" data-t=\"kaunteya\">Kaunteya</a>, arrastran a la fuerza la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> incluso del hombre sabio que se esfuerza.</span>", "palabras": [{"iast": "yatataḥ", "sa": "यततः", "gram": "gen. sg. m. part. pres.", "es": "del que se esfuerza", "analisis": "√yat (esforzarse)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun, incluso"}, {"iast": "kaunteya", "sa": "कौन्तेय", "gram": "voc. sg. m.", "es": "oh Kaunteya", "ref": "kaunteya"}, {"iast": "puruṣasya", "sa": "पुरुषस्य", "gram": "gen. sg. m.", "es": "del hombre"}, {"iast": "vipaścitaḥ", "sa": "विपश्चितः", "gram": "gen. sg. m. adj.", "es": "sabio, entendido"}, {"iast": "indriyāṇi", "sa": "इन्द्रियाणि", "gram": "nom. pl. n.", "es": "los sentidos", "ref": "indriya"}, {"iast": "pramāthīni", "sa": "प्रमाथीनि", "gram": "nom. pl. n. adj.", "es": "turbulentos, que agitan", "analisis": "pra + √math (batir, agitar)"}, {"iast": "haranti", "sa": "हरन्ति", "gram": "3 pl. pres. act.", "es": "arrastran", "analisis": "√hṛ (llevar, arrebatar)"}, {"iast": "prasabham", "sa": "प्रसभम्", "gram": "ind.", "es": "a la fuerza, con violencia"}, {"iast": "manaḥ", "sa": "मनः", "gram": "ac. sg. n.", "es": "la mente", "ref": "manas"}], "nota": "<p>Los sentidos se llaman <em>pramāthin</em>, «que agitan, que baten», de la raíz con que se bate la leche para hacer mantequilla. Arjuna devolverá la palabra a Kṛṣṇa en <a class=\"vref\" href=\"capitulo-06.html#v34\" data-v=\"6.34\">6.34</a>, cuando se queje de que la mente es inestable, <em>pramāthi</em>, poderosa y tenaz.</p><p><em>Puruṣa</em> tiene aquí su sentido corriente de «hombre, persona». El verso explica por qué no basta la voluntad: incluso el sabio (<em>vipaścit</em>) que se esfuerza puede ser arrastrado.</p>", "interp": [{"titulo": "Los caballos desbocados", "html": "<p>Los comentaristas evocan la alegoría del carro de la <a class=\"t\" href=\"glosario.html#katha-upanisad\" data-t=\"katha-upanisad\">Kaṭha Upaniṣad</a> (1.3.3–6): para quien carece de discernimiento y no tiene la mente sujeta, los sentidos son indóciles, como los caballos resabiados de un auriga. El verso no desprecia el esfuerzo, sino que mide su límite: la disciplina sola no basta si falta un apoyo más alto, que el verso siguiente nombrará.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "retirar-los-sentidos"}, {"n": 61, "hablante": "krsna", "sa": ["तानि सर्वाणि संयम्य युक्त आसीत मत्परः ।", "वशे हि यस्येन्द्रियाणि तस्य प्रज्ञा प्रतिष्ठिता ॥६१॥"], "iast": ["tāni sarvāṇi saṃyamya yukta āsīta mat-paraḥ", "vaśe hi yasyendriyāṇi tasya prajñā pratiṣṭhitā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Que, tras dominarlos todos, se siente <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">unido en yoga</a>, teniéndome a mí como meta suprema; pues aquel que tiene los sentidos bajo control, su sabiduría está asentada.</span>", "palabras": [{"iast": "tāni", "sa": "तानि", "gram": "ac. pl. n. pron.", "es": "a ellos"}, {"iast": "sarvāṇi", "sa": "सर्वाणि", "gram": "ac. pl. n. adj.", "es": "todos"}, {"iast": "saṃyamya", "sa": "संयम्य", "gram": "abs.", "es": "tras dominar", "analisis": "sam + √yam (sujetar, refrenar)"}, {"iast": "yuktaḥ", "sa": "युक्तः", "gram": "nom. sg. m. ppp", "es": "unido en yoga, disciplinado", "ref": "yoga", "analisis": "√yuj (uncir, unir)"}, {"iast": "āsīta", "sa": "आसीत", "gram": "3 sg. opt. med.", "es": "que se siente, que permanezca", "analisis": "√ās (sentarse, estar)"}, {"iast": "mat-paraḥ", "sa": "मत्परः", "gram": "nom. sg. m. adj. comp.", "es": "teniéndome a mí como meta suprema", "analisis": "mad (yo, forma de compuesto) + para (supremo, lo más alto)"}, {"iast": "vaśe", "sa": "वशे", "gram": "loc. sg. m.", "es": "bajo control", "analisis": "vaśa (dominio, voluntad)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "yasya", "sa": "यस्य", "gram": "gen. sg. m. pron.", "es": "de quien"}, {"iast": "indriyāṇi", "sa": "इन्द्रियाणि", "gram": "nom. pl. n.", "es": "los sentidos", "ref": "indriya"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. m. pron.", "es": "de él, su"}, {"iast": "prajñā", "sa": "प्रज्ञा", "gram": "nom. sg. f.", "es": "sabiduría", "ref": "prajna", "analisis": "pra + √jñā (conocer)"}, {"iast": "pratiṣṭhitā", "sa": "प्रतिष्ठिता", "gram": "nom. sg. f. ppp", "es": "asentada, firme", "analisis": "prati + √sthā (estar de pie, mantenerse)"}], "nota": "<p><em>Yukta</em>, de la misma raíz que <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>, es el que está «uncido»: unido y disciplinado. <em>Āsīta</em>, «que se siente», puede entenderse en sentido literal —la postura sentada de la meditación que describirá <a class=\"vref\" href=\"capitulo-06.html#v11\" data-v=\"6.11\">6.11</a>–<a class=\"vref\" href=\"capitulo-06.html#v14\" data-v=\"6.14\">6.14</a>— o amplio, «que permanezca».</p><p><em>Mat-para</em>, «que me tiene a mí como lo supremo», es la primera vez que Kṛṣṇa se presenta como meta de la práctica: la respuesta al límite del esfuerzo que señalaba el verso anterior. La idea se desarrollará sobre todo en los capítulos 6 a 12.</p>", "interp": [{"titulo": "«Yo, el sí-mismo interior de todos»", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> glosa <em>mat-para</em> como el que tiene por supremo a «mí, Vāsudeva, el sí-mismo interior de todos». En su lectura, el «mí» de Kṛṣṇa no es una persona distinta del discípulo, sino el sí-mismo que habita en cada uno: sentarse con la mente puesta en él es dirigir la atención hacia la propia realidad última.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El apoyo que purifica", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> da a este verso un peso especial: los sentidos no pueden dominarse con el solo esfuerzo propio, como acaba de decir el verso anterior; sólo cuando la mente se fija en el Señor, apoyo propicio del pensamiento (<em>śubhāśraya</em>), quedan consumidas todas sus faltas, y la mente, purificada y libre del apego a los objetos, somete los sentidos y puede ver el sí-mismo. Rāmānuja cita el Viṣṇu-purāṇa: como el fuego avivado por el viento quema la maleza, así Viṣṇu, presente en el pensamiento de los yoguis, consume todas sus faltas. La devoción no es aquí un añadido a la disciplina, sino lo que la hace posible.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Los sentidos al servicio de Kṛṣṇa", "html": "<p>Para la tradición gauḍīya, <em>mat-paraḥ</em> es la clave de toda la sección: los sentidos no se dominan dejándolos vacíos, sino ocupándolos en el servicio de Kṛṣṇa. Bhaktivedanta Swami Prabhupāda lee aquí la «conciencia de Kṛṣṇa»: quien la tiene dirige hacia lo divino las mismas facultades que, vueltas a los objetos, lo arrastraban.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "retirar-los-sentidos"}, {"n": 62, "hablante": "krsna", "sa": ["ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते ।", "सङ्गात्सञ्जायते कामः कामात्क्रोधोऽभिजायते ॥६२॥"], "iast": ["dhyāyato viṣayān puṃsaḥ saṅgas teṣūpajāyate", "saṅgāt sañjāyate kāmaḥ kāmāt krodho 'bhijāyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Cuando el hombre piensa en los <a class=\"t\" href=\"glosario.html#visaya\" data-t=\"visaya\">objetos de los sentidos</a>, nace en él el apego a ellos; del apego surge el <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a>, y del deseo nace la <a class=\"t\" href=\"glosario.html#krodha\" data-t=\"krodha\">ira</a>;</span>", "palabras": [{"iast": "dhyāyataḥ", "sa": "ध्यायतः", "gram": "gen. sg. m. part. pres.", "es": "que piensa en, que contempla", "analisis": "√dhyai (pensar, contemplar), la raíz de dhyāna, «meditación»"}, {"iast": "viṣayān", "sa": "विषयान्", "gram": "ac. pl. m.", "es": "los objetos de los sentidos", "ref": "visaya"}, {"iast": "puṃsaḥ", "sa": "पुंसः", "gram": "gen. sg. m.", "es": "del hombre", "analisis": "puṃs (varón, ser humano)"}, {"iast": "saṅgaḥ", "sa": "सङ्गः", "gram": "nom. sg. m.", "es": "el apego", "analisis": "sam + √sañj (adherirse)"}, {"iast": "teṣu", "sa": "तेषु", "gram": "loc. pl. m. pron.", "es": "a ellos"}, {"iast": "upajāyate", "sa": "उपजायते", "gram": "3 sg. pres. med.", "es": "nace", "analisis": "upa + √jan (nacer)"}, {"iast": "saṅgāt", "sa": "सङ्गात्", "gram": "abl. sg. m.", "es": "del apego"}, {"iast": "sañjāyate", "sa": "सञ्जायते", "gram": "3 sg. pres. med.", "es": "surge", "analisis": "sam + √jan (nacer)"}, {"iast": "kāmaḥ", "sa": "कामः", "gram": "nom. sg. m.", "es": "el deseo", "ref": "kama"}, {"iast": "kāmāt", "sa": "कामात्", "gram": "abl. sg. m.", "es": "del deseo", "ref": "kama"}, {"iast": "krodhaḥ", "sa": "क्रोधः", "gram": "nom. sg. m.", "es": "la ira", "ref": "krodha", "analisis": "√krudh (enojarse)"}, {"iast": "abhijāyate", "sa": "अभिजायते", "gram": "3 sg. pres. med.", "es": "nace", "analisis": "abhi + √jan (nacer)"}], "nota": "<p>Comienza aquí la célebre cadena causal que termina en el verso siguiente. El punto de partida es mínimo: <em>dhyāyataḥ</em>, «del que piensa en, del que contempla». Es la raíz de <em>dhyāna</em>, «meditación»: la misma atención sostenida que, dirigida a los objetos, ata, y dirigida hacia dentro, libera.</p><p><em>Saṅga</em> es «adherencia, apego»; <em>kāma</em>, el <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseo</a>. La <a class=\"t\" href=\"glosario.html#krodha\" data-t=\"krodha\">ira</a> nace cuando el deseo encuentra un obstáculo: no es lo contrario del deseo, sino su prolongación.</p>", "interp": [{"titulo": "Una cadena de ocho eslabones", "html": "<p>Los dos versos forman una gradación en la que cada término, en ablativo («del apego…», «del deseo…»), engendra el siguiente: pensar en los objetos, apego, deseo, ira, extravío, confusión de la memoria, ruina del entendimiento, ruina de la persona. La figura subraya que la ruina final no es un accidente, sino la consecuencia lenta de algo tan inocente como el lugar donde uno deja descansar la atención. Por eso la técnica de los versos anteriores actúa en el primer eslabón.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Un modo de razonar compartido", "html": "<p>La forma recuerda las cadenas causales del budismo antiguo, como la «originación dependiente», en las que también el anhelo (<em>tṛṣṇā</em>) engendra el aferramiento y éste el sufrimiento. No hace falta suponer una influencia directa: la cadena muestra un modo de analizar el deseo común a las corrientes ascéticas de la época, que la Gītā integra en su propio marco.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}, {"titulo": "Una psicología del deseo", "html": "<p>Muchos lectores modernos ven en estos versos una descripción sorprendentemente precisa de la escalada que lleva de una fantasía a la obsesión, y de la frustración a la ira y a decisiones que uno mismo no reconoce. Para esta lectura, el valor del pasaje no depende de ninguna metafísica: es una observación sobre cómo funciona la mente humana.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "cadena-del-deseo"}, {"n": 63, "hablante": "krsna", "sa": ["क्रोधाद्भवति सम्मोहः सम्मोहात्स्मृतिविभ्रमः ।", "स्मृतिभ्रंशाद्बुद्धिनाशो बुद्धिनाशात्प्रणश्यति ॥६३॥"], "iast": ["krodhād bhavati sammohaḥ sammohāt smṛti-vibhramaḥ", "smṛti-bhraṃśād buddhi-nāśo buddhi-nāśāt praṇaśyati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">de la ira viene el <a class=\"t\" href=\"glosario.html#moha\" data-t=\"moha\">extravío</a>; del extravío, la confusión de la memoria; de la pérdida de la memoria, la ruina del <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>, y por la ruina del entendimiento, el hombre perece.</span>", "palabras": [{"iast": "krodhāt", "sa": "क्रोधात्", "gram": "abl. sg. m.", "es": "de la ira", "ref": "krodha"}, {"iast": "bhavati", "sa": "भवति", "gram": "3 sg. pres. act.", "es": "viene, se produce", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "sammohaḥ", "sa": "सम्मोहः", "gram": "nom. sg. m.", "es": "el extravío", "ref": "moha", "analisis": "sam + moha (extravío; de √muh, aturdirse)"}, {"iast": "sammohāt", "sa": "सम्मोहात्", "gram": "abl. sg. m.", "es": "del extravío", "ref": "moha"}, {"iast": "smṛti-vibhramaḥ", "sa": "स्मृतिविभ्रमः", "gram": "nom. sg. m. comp.", "es": "la confusión de la memoria", "analisis": "smṛti (memoria; de √smṛ, recordar) + vibhrama (desorden, extravío; de vi-√bhram, vagar)"}, {"iast": "smṛti-bhraṃśāt", "sa": "स्मृतिभ्रंशात्", "gram": "abl. sg. m. comp.", "es": "de la pérdida de la memoria", "analisis": "smṛti (memoria) + bhraṃśa (caída, pérdida; de √bhraṃś, caer)"}, {"iast": "buddhi-nāśaḥ", "sa": "बुद्धिनाशः", "gram": "nom. sg. m. comp.", "es": "la ruina del entendimiento", "ref": "buddhi", "analisis": "buddhi (entendimiento) + nāśa (destrucción; de √naś, perecer)"}, {"iast": "buddhi-nāśāt", "sa": "बुद्धिनाशात्", "gram": "abl. sg. m. comp.", "es": "de la ruina del entendimiento", "ref": "buddhi"}, {"iast": "praṇaśyati", "sa": "प्रणश्यति", "gram": "3 sg. pres. act.", "es": "perece, se pierde", "analisis": "pra + √naś (perecer)"}], "nota": "<p>La cadena termina en <em>praṇaśyati</em>, «se pierde, perece»: no la muerte física, sino la ruina de la persona como ser capaz de discernir. <em>Smṛti</em>, «memoria», es aquí el recuerdo de lo que uno sabe y se ha propuesto: perderla es olvidarse de sí. El <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> es justamente la facultad que, según todo este capítulo, debía mantenerse firme.</p><p>La Gītā cierra este arco al final: en <a class=\"vref\" href=\"capitulo-18.html#v73\" data-v=\"18.73\">18.73</a> Arjuna dirá «se ha destruido mi extravío (<em>moha</em>), he recobrado la memoria (<em>smṛti</em>)», como si recorriera la cadena en sentido inverso.</p>", "interp": [{"titulo": "Perecer: perder el fin humano", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> explica que «perece» quiere decir que el hombre se vuelve incapaz de alcanzar el fin humano: mientras conserva el entendimiento, puede todavía discernir y orientarse hacia la liberación; sin él, ha perdido lo que lo hace propiamente humano.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Del extravío a la memoria recobrada", "html": "<p>El verso dibuja en miniatura el arco de toda la obra. Arjuna empezó extraviado (<em>moha</em>), con el entendimiento confundido sobre su deber (<a class=\"vref\" href=\"capitulo-02.html#v7\" data-v=\"2.7\">2.7</a>); al terminar, declara: «se ha destruido mi extravío, he recobrado la memoria por tu gracia» (<a class=\"vref\" href=\"capitulo-18.html#v73\" data-v=\"18.73\">18.73</a>). La enseñanza de Kṛṣṇa consiste, en buena parte, en deshacer la cadena que aquí se describe.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "cadena-del-deseo"}, {"n": 64, "hablante": "krsna", "sa": ["रागद्वेषवियुक्तैस्तु विषयानिन्द्रियैश्चरन् ।", "आत्मवश्यैर्विधेयात्मा प्रसादमधिगच्छति ॥६४॥"], "iast": ["rāga-dveṣa-viyuktais tu viṣayān indriyaiś caran", "ātma-vaśyair vidheyātmā prasādam adhigacchati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero quien es dueño de sí y se mueve entre los <a class=\"t\" href=\"glosario.html#visaya\" data-t=\"visaya\">objetos de los sentidos</a> con unos <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a> libres de atracción y de aversión, sometidos a su gobierno, alcanza la <a class=\"t\" href=\"glosario.html#prasada\" data-t=\"prasada\">serenidad</a>.</span>", "palabras": [{"iast": "rāga-dveṣa-viyuktaiḥ", "sa": "रागद्वेषवियुक्तैः", "gram": "instr. pl. n. comp. ppp", "es": "libres de atracción y aversión", "analisis": "rāga (atracción, apego; √rañj «teñirse») + dveṣa (aversión; √dviṣ «odiar») + viyukta (separado, libre; vi-√yuj)"}, {"iast": "tu", "sa": "तु", "gram": "ind.", "es": "pero"}, {"iast": "viṣayān", "sa": "विषयान्", "gram": "ac. pl. m.", "es": "entre los objetos de los sentidos", "ref": "visaya"}, {"iast": "indriyaiḥ", "sa": "इन्द्रियैः", "gram": "instr. pl. n.", "es": "con los sentidos", "ref": "indriya"}, {"iast": "caran", "sa": "चरन्", "gram": "nom. sg. m. part. pres.", "es": "moviéndose, andando", "analisis": "√car (moverse, andar, vivir)"}, {"iast": "ātma-vaśyaiḥ", "sa": "आत्मवश्यैः", "gram": "instr. pl. n. comp. adj.", "es": "sometidos a uno mismo", "analisis": "ātman (uno mismo) + vaśya (sometido, obediente; √vaś «querer, mandar»)"}, {"iast": "vidheya-ātmā", "sa": "विधेयात्मा", "gram": "nom. sg. m. comp.", "es": "el que se ha disciplinado, dueño de sí", "analisis": "vidheya (dócil, que se deja dirigir; gerundivo de vi-√dhā) + ātman (aquí, uno mismo, la propia mente)"}, {"iast": "prasādam", "sa": "प्रसादम्", "gram": "ac. sg. m.", "es": "la serenidad", "ref": "prasada", "analisis": "pra-√sad (asentarse, aclararse)"}, {"iast": "adhigacchati", "sa": "अधिगच्छति", "gram": "3 sg. pres. act.", "es": "alcanza", "analisis": "adhi-√gam (llegar a, alcanzar)"}], "nota": "<p>Con <em>tu</em>, «pero», Kṛṣṇa contrapone este verso a los dos anteriores (<a class=\"vref\" href=\"capitulo-02.html#v62\" data-v=\"2.62\">2.62</a>–<a class=\"vref\" href=\"capitulo-02.html#v63\" data-v=\"2.63\">2.63</a>), que describen la caída de quien se detiene a pensar en los objetos. El remedio no es dejar de tratar con ellos: el participio <em>caran</em>, «moviéndose, andando entre», supone que el sabio sigue viviendo en el mundo y usando sus sentidos. Lo que cambia es la relación con los objetos: sin <em>rāga</em> ni <em>dveṣa</em>, sin atracción ni aversión, y con los sentidos «sometidos a uno mismo» (<em>ātma-vaśya</em>).</p><p><em>Prasāda</em> deriva de una raíz que significa «asentarse»: es el agua que, al reposar, se aclara. De ahí «claridad, serenidad» y, en el vocabulario devocional, también «favor, gracia» (<a class=\"t\" href=\"glosario.html#prasada\" data-t=\"prasada\">prasāda</a>).</p>", "interp": [{"titulo": "No huir del mundo", "html": "<p>Este verso equilibra la imagen de la tortuga que retrae sus miembros (<a class=\"vref\" href=\"capitulo-02.html#v58\" data-v=\"2.58\">2.58</a>). Retirar los sentidos no significa aislarse: <a class=\"vref\" href=\"capitulo-02.html#v59\" data-v=\"2.59\">2.59</a> ya ha advertido que quien sólo se abstiene de los objetos conserva el gusto por ellos. El sabio que dibuja Kṛṣṇa no vive encerrado, sino que se mueve (<em>caran</em>) entre las cosas sin que lo arrastren la atracción ni la aversión. Es el primer esbozo de una idea central del libro: la libertad no está en dejar de actuar, sino en el modo de actuar.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}, {"titulo": "Con la mente puesta en el Señor", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee estos versos a la luz de <a class=\"vref\" href=\"capitulo-02.html#v61\" data-v=\"2.61\">2.61</a>, donde Kṛṣṇa pide al yogui que se siente «entregado a mí» (<em>mat-paraḥ</em>). Para esta lectura, el esfuerzo propio no basta para someter los sentidos: es la mente fija en el Señor la que desprende el apego, y la serenidad resultante es el fruto de esa orientación hacia Dios.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Serenidad y gracia", "html": "<p>Los lectores devocionales oyen en <em>prasāda</em> también su otro sentido, el de «gracia», que la palabra tiene en la propia Gītā cuando Kṛṣṇa habla de «mi gracia» (<em>mat-prasāda</em>, <a class=\"vref\" href=\"capitulo-18.html#v56\" data-v=\"18.56\">18.56</a>) y Arjuna agradece la suya (<a class=\"vref\" href=\"capitulo-18.html#v73\" data-v=\"18.73\">18.73</a>). En la práctica religiosa hindú, <em>prasāda</em> es además el alimento ofrecido a la divinidad y repartido después entre los fieles: la serenidad del sabio sería, en esta clave, un don recibido más que una conquista.</p>", "trad": "devocional", "tradNombre": "Lecturas devocionales"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "sentidos-dominados"}, {"n": 65, "hablante": "krsna", "sa": ["प्रसादे सर्वदुःखानां हानिरस्योपजायते ।", "प्रसन्नचेतसो ह्याशु बुद्धिः पर्यवतिष्ठते ॥६५॥"], "iast": ["prasāde sarva-duḥkhānāṃ hānir asyopajāyate", "prasanna-cetaso hy āśu buddhiḥ paryavatiṣṭhate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">En la <a class=\"t\" href=\"glosario.html#prasada\" data-t=\"prasada\">serenidad</a> desaparecen todos sus sufrimientos, pues el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> de quien tiene el ánimo sereno pronto se asienta con firmeza.</span>", "palabras": [{"iast": "prasāde", "sa": "प्रसादे", "gram": "loc. sg. m.", "es": "en la serenidad", "ref": "prasada"}, {"iast": "sarva-duḥkhānām", "sa": "सर्वदुःखानाम्", "gram": "gen. pl. n. comp.", "es": "de todos los sufrimientos", "analisis": "sarva (todo) + duḥkha (sufrimiento, dolor)"}, {"iast": "hāniḥ", "sa": "हानिः", "gram": "nom. sg. f.", "es": "la desaparición, la eliminación", "analisis": "√hā (dejar, abandonar)"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. m. pron.", "es": "de él, para él"}, {"iast": "upajāyate", "sa": "उपजायते", "gram": "3 sg. pres. med.", "es": "se produce, sobreviene", "analisis": "upa-√jan (nacer, surgir)"}, {"iast": "prasanna-cetasaḥ", "sa": "प्रसन्नचेतसः", "gram": "gen. sg. m. comp.", "es": "del que tiene el ánimo sereno", "analisis": "prasanna (sereno, aclarado; ppp de pra-√sad) + cetas (ánimo, mente; √cit «percibir»)"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "āśu", "sa": "आशु", "gram": "adv.", "es": "pronto, enseguida"}, {"iast": "buddhiḥ", "sa": "बुद्धिः", "gram": "nom. sg. f.", "es": "el entendimiento", "ref": "buddhi"}, {"iast": "paryavatiṣṭhate", "sa": "पर्यवतिष्ठते", "gram": "3 sg. pres. med.", "es": "se asienta con firmeza", "analisis": "pari-ava-√sthā (quedar firmemente asentado)"}], "nota": "<p>La serenidad tiene dos efectos: desaparece el sufrimiento (<em>duḥkha</em>) y el entendimiento se asienta (<em>paryavatiṣṭhate</em>). Este verbo, compuesto de la raíz <em>sthā</em>, «estar de pie, permanecer», repite la idea de firmeza que da nombre a la sección entera: el sabio <em>sthita-prajña</em>, «de sabiduría firme» (<a class=\"vref\" href=\"capitulo-02.html#v55\" data-v=\"2.55\">2.55</a>).</p>", "interp": [{"titulo": "La claridad como condición del conocimiento", "html": "<p>Los comentaristas vedánticos subrayan el orden del verso: primero se aclara la mente, después se asienta el entendimiento. La agitación no es sólo una molestia moral; impide conocer, como el agua turbia impide ver el fondo. Por eso, para esta tradición, la disciplina de los sentidos no es un fin en sí misma, sino la preparación para el conocimiento del sí-mismo.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "sentidos-dominados"}, {"n": 66, "hablante": "krsna", "sa": ["नास्ति बुद्धिरयुक्तस्य न चायुक्तस्य भावना ।", "न चाभावयतः शान्तिरशान्तस्य कुतः सुखम् ॥६६॥"], "iast": ["nāsti buddhir ayuktasya na cāyuktasya bhāvanā", "na cābhāvayataḥ śāntir aśāntasya kutaḥ sukham"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">No tiene <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> quien no está unido en <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>, ni tiene tampoco contemplación; quien no contempla no tiene <a class=\"t\" href=\"glosario.html#santi\" data-t=\"santi\">paz</a>, y quien no tiene paz, ¿cómo va a ser feliz?</span>", "palabras": [{"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "asti", "sa": "अस्ति", "gram": "3 sg. pres. act.", "es": "hay", "analisis": "√as (ser, haber)"}, {"iast": "buddhiḥ", "sa": "बुद्धिः", "gram": "nom. sg. f.", "es": "entendimiento", "ref": "buddhi"}, {"iast": "ayuktasya", "sa": "अयुक्तस्य", "gram": "gen. sg. m. ppp", "es": "del que no está unido en yoga", "ref": "yoga", "analisis": "a (no) + yukta (unido, disciplinado; ppp de √yuj, la raíz de yoga)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "ayuktasya", "sa": "अयुक्तस्य", "gram": "gen. sg. m. ppp", "es": "del que no está unido en yoga"}, {"iast": "bhāvanā", "sa": "भावना", "gram": "nom. sg. f.", "es": "contemplación", "analisis": "del causativo de √bhū (ser): «hacer que algo sea», cultivarlo en la mente"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "ca", "sa": "च", "gram": "ind.", "es": "y"}, {"iast": "abhāvayataḥ", "sa": "अभावयतः", "gram": "gen. sg. m. part. pres. caus.", "es": "del que no contempla"}, {"iast": "śāntiḥ", "sa": "शान्तिः", "gram": "nom. sg. f.", "es": "paz", "ref": "santi", "analisis": "√śam (calmarse, apaciguarse)"}, {"iast": "aśāntasya", "sa": "अशान्तस्य", "gram": "gen. sg. m. ppp", "es": "del que no tiene paz"}, {"iast": "kutaḥ", "sa": "कुतः", "gram": "ind.", "es": "¿de dónde?, ¿cómo?"}, {"iast": "sukham", "sa": "सुखम्", "gram": "nom. sg. n.", "es": "felicidad, dicha"}], "nota": "<p>El verso es una cadena de negaciones que recorre al revés el camino de los dos anteriores: sin disciplina no hay entendimiento firme, sin él no hay <em>bhāvanā</em>, sin ella no hay paz, y sin paz no hay felicidad. <em>Ayukta</em>, «no unido», es el contrario de <em>yukta</em>, participio de la raíz <em>yuj</em> de la que viene <em>yoga</em>: el que no ha uncido sus sentidos y su mente.</p><p><em>Bhāvanā</em> procede del causativo de <em>bhū</em>, «ser»: «hacer ser», cultivar algo en la mente hasta que se vuelve real para uno. Se traduce aquí por «contemplación»; otras versiones dicen «concentración» o «meditación».</p>", "interp": [{"titulo": "Contemplación del sí-mismo", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende <em>bhāvanā</em> como la dedicación intensa al conocimiento del sí-mismo (<a class=\"t\" href=\"glosario.html#atman\" data-t=\"atman\">ātman</a>). Leído así, el verso describe una progresión: la disciplina de los sentidos hace posible un entendimiento firme; éste, la absorción en el conocimiento del sí-mismo; y de ella nace la paz, que es la única felicidad verdadera.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Una cadena de causas", "html": "<p>La Gītā gusta de estas cadenas, que encadenan estados mentales como causas y efectos. Esta es la réplica positiva de la de <a class=\"vref\" href=\"capitulo-02.html#v62\" data-v=\"2.62\">2.62</a>–<a class=\"vref\" href=\"capitulo-02.html#v63\" data-v=\"2.63\">2.63</a>, que llevaba de pensar en los objetos al apego, al deseo, a la ira, al extravío y a la ruina. Las dos juntas forman un pequeño mapa psicológico: una escalera que baja y otra que sube.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "sentidos-dominados"}, {"n": 67, "hablante": "krsna", "sa": ["इन्द्रियाणां हि चरतां यन्मनोऽनुविधीयते ।", "तदस्य हरति प्रज्ञां वायुर्नावमिवाम्भसि ॥६७॥"], "iast": ["indriyāṇāṃ hi caratāṃ yan mano 'nuvidhīyate", "tad asya harati prajñāṃ vāyur nāvam ivāmbhasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Porque la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> que se deja llevar por los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a> cuando vagan entre sus objetos le arrebata a uno la <a class=\"t\" href=\"glosario.html#prajna\" data-t=\"prajna\">sabiduría</a>, como el viento a una barca sobre el agua.</span>", "palabras": [{"iast": "indriyāṇām", "sa": "इन्द्रियाणाम्", "gram": "gen. pl. n.", "es": "de los sentidos", "ref": "indriya"}, {"iast": "hi", "sa": "हि", "gram": "ind.", "es": "pues"}, {"iast": "caratām", "sa": "चरताम्", "gram": "gen. pl. n. part. pres.", "es": "que vagan", "analisis": "√car (moverse, vagar)"}, {"iast": "yat", "sa": "यत्", "gram": "nom. sg. n. pron.", "es": "la que, aquella que"}, {"iast": "manaḥ", "sa": "मनः", "gram": "nom. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "anuvidhīyate", "sa": "अनुविधीयते", "gram": "3 sg. pres. pas.", "es": "se deja llevar, se ajusta a", "analisis": "anu-vi-√dhā (conformarse a, seguir)"}, {"iast": "tat", "sa": "तत्", "gram": "nom. sg. n. pron.", "es": "ésa"}, {"iast": "asya", "sa": "अस्य", "gram": "gen. sg. m. pron.", "es": "de él, a él"}, {"iast": "harati", "sa": "हरति", "gram": "3 sg. pres. act.", "es": "arrebata, se lleva", "analisis": "√hṛ (llevar, arrebatar)"}, {"iast": "prajñām", "sa": "प्रज्ञाम्", "gram": "ac. sg. f.", "es": "la sabiduría", "ref": "prajna"}, {"iast": "vāyuḥ", "sa": "वायुः", "gram": "nom. sg. m.", "es": "el viento"}, {"iast": "nāvam", "sa": "नावम्", "gram": "ac. sg. f.", "es": "una barca", "analisis": "nau (barca, nave); emparentado con el latín *navis*"}, {"iast": "iva", "sa": "इव", "gram": "ind.", "es": "como"}, {"iast": "ambhasi", "sa": "अम्भसि", "gram": "loc. sg. n.", "es": "sobre el agua"}], "nota": "<p>La imagen es la de una barca sin gobierno, que el viento empuja a la deriva. Hay una pequeña ambigüedad: <em>tat</em>, «ésa», puede referirse a la mente o al sentido que la mente sigue; en ambos casos basta <em>uno</em> de los sentidos desbocados para arrastrar la sabiduría entera. <em>Asya</em>, «de él», es la persona en general, y la traducción lo vierte por «a uno».</p><p>La imagen prolonga la de la <a class=\"t\" href=\"glosario.html#katha-upanisad\" data-t=\"katha-upanisad\">Kaṭha Upaniṣad</a>, donde los sentidos son caballos y la mente las riendas: aquí no hay quien sujete el timón.</p>", "interp": [{"titulo": "Un solo sentido basta", "html": "<p>El genitivo plural <em>indriyāṇāṃ caratām</em>, «de los sentidos que vagan», admite leer que la mente sigue a cualquiera de ellos. Varios comentaristas, entre ellos <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, insisten en esta lectura: no hace falta que todos los sentidos se desboquen; si la mente se va tras uno solo, la sabiduría se pierde. (<a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, en cambio, habla de los sentidos en plural: la mente que los sigue arrastra la sabiduría del renunciante, como el viento a una barca.) El verso siguiente pedirá, en consecuencia, que los sentidos estén retenidos «por completo» (<em>sarvaśaḥ</em>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "sentidos-dominados"}, {"n": 68, "hablante": "krsna", "sa": ["तस्माद्यस्य महाबाहो निगृहीतानि सर्वशः ।", "इन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता ॥६८॥"], "iast": ["tasmād yasya mahā-bāho nigṛhītāni sarvaśaḥ", "indriyāṇīndriyārthebhyas tasya prajñā pratiṣṭhitā"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Por eso, oh <a class=\"t\" href=\"glosario.html#mahabaho\" data-t=\"mahabaho\">Mahābāhu</a>, tiene una <a class=\"t\" href=\"glosario.html#prajna\" data-t=\"prajna\">sabiduría</a> firme aquel cuyos <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a> están por completo retenidos, apartados de sus <a class=\"t\" href=\"glosario.html#visaya\" data-t=\"visaya\">objetos</a>.</span>", "palabras": [{"iast": "tasmāt", "sa": "तस्मात्", "gram": "abl. sg. n. pron.", "es": "por eso"}, {"iast": "yasya", "sa": "यस्य", "gram": "gen. sg. m. pron.", "es": "aquel cuyos"}, {"iast": "mahā-bāho", "sa": "महाबाहो", "gram": "voc. sg. m. comp.", "es": "oh Mahābāhu, de brazos poderosos", "ref": "mahabaho", "analisis": "mahā (grande) + bāhu (brazo)"}, {"iast": "nigṛhītāni", "sa": "निगृहीतानि", "gram": "nom. pl. n. ppp", "es": "retenidos, refrenados", "analisis": "ni-√grah (sujetar, contener)"}, {"iast": "sarvaśaḥ", "sa": "सर्वशः", "gram": "adv.", "es": "por completo"}, {"iast": "indriyāṇi", "sa": "इन्द्रियाणि", "gram": "nom. pl. n.", "es": "los sentidos", "ref": "indriya"}, {"iast": "indriya-arthebhyaḥ", "sa": "इन्द्रियार्थेभ्यः", "gram": "abl. pl. m. comp.", "es": "de los objetos de los sentidos", "ref": "visaya", "analisis": "indriya (sentido) + artha (objeto)"}, {"iast": "tasya", "sa": "तस्य", "gram": "gen. sg. m. pron.", "es": "de ése"}, {"iast": "prajñā", "sa": "प्रज्ञा", "gram": "nom. sg. f.", "es": "la sabiduría", "ref": "prajna"}, {"iast": "pratiṣṭhitā", "sa": "प्रतिष्ठिता", "gram": "nom. sg. f. ppp", "es": "firme, asentada", "analisis": "prati-√sthā (asentarse, afirmarse)"}], "nota": "<p><em>Tasya prajñā pratiṣṭhitā</em>, «su sabiduría está firme», es el estribillo de la descripción del sabio que empezó en <a class=\"vref\" href=\"capitulo-02.html#v55\" data-v=\"2.55\">2.55</a>: lo ha dicho ya en <a class=\"vref\" href=\"capitulo-02.html#v57\" data-v=\"2.57\">2.57</a>, <a class=\"vref\" href=\"capitulo-02.html#v58\" data-v=\"2.58\">2.58</a> y <a class=\"vref\" href=\"capitulo-02.html#v61\" data-v=\"2.61\">2.61</a>, y aquí cierra el argumento con <em>tasmāt</em>, «por eso». El vocativo <em>mahā-bāho</em>, «el de brazos poderosos», recuerda al guerrero que la fuerza que se le pide ahora es la de sujetar sus sentidos.</p>", "interp": [{"titulo": "El guerrero y sus sentidos", "html": "<p>La elección del epíteto (<a class=\"t\" href=\"glosario.html#mahabaho\" data-t=\"mahabaho\">Mahābāhu</a>) no parece casual: Kṛṣṇa se dirige al arquero más fuerte de su tiempo para pedirle una fuerza de otro tipo. El verbo <em>ni-grah</em>, «sujetar, contener», es el mismo que se usa para refrenar caballos o prisioneros, y mantiene viva la imagen del carro que recorre toda la Gītā.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "sentidos-dominados"}, {"n": 69, "hablante": "krsna", "sa": ["या निशा सर्वभूतानां तस्यां जागर्ति संयमी ।", "यस्यां जाग्रति भूतानि सा निशा पश्यतो मुनेः ॥६९॥"], "iast": ["yā niśā sarva-bhūtānāṃ tasyāṃ jāgarti saṃyamī", "yasyāṃ jāgrati bhūtāni sā niśā paśyato muneḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Lo que es noche para todos los seres, en eso vela el que se domina; y aquello en que los seres velan es noche para el <a class=\"t\" href=\"glosario.html#muni\" data-t=\"muni\">sabio</a> que ve.</span>", "palabras": [{"iast": "yā", "sa": "या", "gram": "nom. sg. f. pron.", "es": "la que"}, {"iast": "niśā", "sa": "निशा", "gram": "nom. sg. f.", "es": "noche"}, {"iast": "sarva-bhūtānām", "sa": "सर्वभूतानाम्", "gram": "gen. pl. n. comp.", "es": "de todos los seres", "analisis": "sarva (todo) + bhūta (ser, criatura; ppp de √bhū)"}, {"iast": "tasyām", "sa": "तस्याम्", "gram": "loc. sg. f. pron.", "es": "en ella"}, {"iast": "jāgarti", "sa": "जागर्ति", "gram": "3 sg. pres. act.", "es": "vela, está despierto", "analisis": "√jāgṛ (velar, estar despierto)"}, {"iast": "saṃyamī", "sa": "संयमी", "gram": "nom. sg. m.", "es": "el que se domina", "analisis": "sam-√yam (refrenar, contener)"}, {"iast": "yasyām", "sa": "यस्याम्", "gram": "loc. sg. f. pron.", "es": "en la que"}, {"iast": "jāgrati", "sa": "जाग्रति", "gram": "3 pl. pres. act.", "es": "velan, están despiertos"}, {"iast": "bhūtāni", "sa": "भूतानि", "gram": "nom. pl. n.", "es": "los seres"}, {"iast": "sā", "sa": "सा", "gram": "nom. sg. f. pron.", "es": "ésa"}, {"iast": "niśā", "sa": "निशा", "gram": "nom. sg. f.", "es": "noche"}, {"iast": "paśyataḥ", "sa": "पश्यतः", "gram": "gen. sg. m. part. pres.", "es": "del que ve", "analisis": "√paś (ver)"}, {"iast": "muneḥ", "sa": "मुनेः", "gram": "gen. sg. m.", "es": "para el sabio", "ref": "muni"}], "nota": "<p>Una paradoja al estilo de las Upaniṣads: el sabio y el común de los seres viven en horarios opuestos. Lo que para unos es oscuridad, para el otro es vigilia, y al revés. El verso no dice qué es esa «noche»; lo deja a la reflexión del oyente, y los comentaristas lo han llenado de distintas maneras.</p><p><em>Saṃyamī</em>, «el que se refrena», resume lo dicho sobre el dominio de los sentidos; <em>paśyataḥ</em>, «del que ve», añade que ese dominio no es ceguera, sino una visión más aguda.</p>", "interp": [{"titulo": "La noche de la ignorancia", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, la realidad suprema es «noche» para los seres comunes porque no la ven: son como las criaturas nocturnas, para las que el día es noche; el sabio, en cambio, está despierto a ella. Y el mundo de la multiplicidad, en el que todos los demás están bien despiertos, ocupados en sus deseos y en la distinción entre sujeto y objeto, es para el sabio una noche: la noche de la ignorancia (<em>avidyā</em>), que no toma por real. La paradoja expresa así la inversión de valores que supone el conocimiento del sí-mismo.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Una paradoja con dos lecturas", "html": "<p>El verso admite también una lectura menos metafísica: el sabio no se interesa por aquello que desvela a los demás (la ganancia, la fama, el placer) y, en cambio, está atento a lo que los demás ni advierten. La forma paradójica, que dice algo verdadero con palabras que parecen absurdas, pertenece a una tradición antigua de enigmas en la literatura religiosa india, desde los himnos del Veda hasta las Upaniṣads.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 70, "hablante": "krsna", "sa": ["आपूर्यमाणमचलप्रतिष्ठं समुद्रमापः प्रविशन्ति यद्वत् ।", "तद्वत्कामा यं प्रविशन्ति सर्वे स शान्तिमाप्नोति न कामकामी ॥७०॥"], "iast": ["āpūryamāṇam acala-pratiṣṭhaṃ samudram āpaḥ praviśanti yadvat", "tadvat kāmā yaṃ praviśanti sarve sa śāntim āpnoti na kāma-kāmī"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Como las aguas entran en el océano, que se va colmando sin moverse de su lecho, así alcanza la <a class=\"t\" href=\"glosario.html#santi\" data-t=\"santi\">paz</a> aquel en quien entran todos los <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseos</a>; no el que anda deseando lo que desea.</span>", "palabras": [{"iast": "āpūryamāṇam", "sa": "आपूर्यमाणम्", "gram": "ac. sg. m. part. pres. pas.", "es": "que se va llenando", "analisis": "ā-√pṝ (llenar)"}, {"iast": "acala-pratiṣṭham", "sa": "अचलप्रतिष्ठम्", "gram": "ac. sg. m. comp. adj.", "es": "inmóvil en su asiento", "analisis": "acala (inmóvil; a + √cal «moverse») + pratiṣṭhā (base, asiento)"}, {"iast": "samudram", "sa": "समुद्रम्", "gram": "ac. sg. m.", "es": "en el océano"}, {"iast": "āpaḥ", "sa": "आपः", "gram": "nom. pl. f.", "es": "las aguas"}, {"iast": "praviśanti", "sa": "प्रविशन्ति", "gram": "3 pl. pres. act.", "es": "entran", "analisis": "pra-√viś (entrar)"}, {"iast": "yadvat", "sa": "यद्वत्", "gram": "ind.", "es": "así como"}, {"iast": "tadvat", "sa": "तद्वत्", "gram": "ind.", "es": "del mismo modo"}, {"iast": "kāmāḥ", "sa": "कामाः", "gram": "nom. pl. m.", "es": "los deseos", "ref": "kama"}, {"iast": "yam", "sa": "यम्", "gram": "ac. sg. m. pron.", "es": "en aquel"}, {"iast": "praviśanti", "sa": "प्रविशन्ति", "gram": "3 pl. pres. act.", "es": "entran"}, {"iast": "sarve", "sa": "सर्वे", "gram": "nom. pl. m. adj.", "es": "todos"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "śāntim", "sa": "शान्तिम्", "gram": "ac. sg. f.", "es": "la paz", "ref": "santi"}, {"iast": "āpnoti", "sa": "आप्नोति", "gram": "3 sg. pres. act.", "es": "alcanza", "analisis": "√āp (alcanzar, obtener)"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "kāma-kāmī", "sa": "कामकामी", "gram": "nom. sg. m. comp.", "es": "el que desea los deseos", "ref": "kama", "analisis": "kāma (deseo, objeto deseado) + kāmin (deseoso)"}], "nota": "<p>El metro cambia: frente a las estrofas de ocho sílabas por pie de casi todo el capítulo, este verso es una <em>triṣṭubh</em>, con pies de once sílabas, más amplia y solemne. La imagen lo merece: los ríos desembocan sin cesar en el mar, y el mar ni se desborda ni se mueve de su sitio.</p><p><em>Kāma</em> designa a la vez el deseo y lo deseado. Los deseos, o los objetos deseables, siguen llegando al sabio como llegan los ríos al mar, pero no lo alteran. <em>Kāma-kāmī</em>, «deseoso de deseos», es su contrario: el que vive persiguiendo lo que quiere, como un río que nunca llega al mar.</p>", "interp": [{"titulo": "El mar que no se desborda", "html": "<p>Los comentaristas clásicos subrayan que el texto no dice que al sabio no le lleguen los deseos, sino que entran en él sin producir ningún cambio, como los ríos en el mar. La paz no consiste en que el mundo deje de presentar cosas deseables, sino en una plenitud que no necesita de ellas: el océano ya está lleno antes de que los ríos lleguen.</p>", "trad": "vedanta", "tradNombre": "Vedānta clásico"}, {"titulo": "Plenitud frente a carencia", "html": "<p>El verso contrapone dos imágenes del ser humano: el océano, que recibe sin necesitar, y el <em>kāma-kāmī</em>, que persigue sin llenarse nunca. La diferencia no está en lo que ocurre (los deseos siguen surgiendo), sino en la dirección del movimiento: en el sabio, los deseos entran y se disuelven; en el otro, es él quien sale tras ellos. La misma idea aparece en <a class=\"vref\" href=\"capitulo-02.html#v55\" data-v=\"2.55\">2.55</a>, donde el sabio está «contento en sí mismo, por sí mismo».</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "triṣṭubh (cuatro pies de once sílabas)", "ens": "paz-del-oceano"}, {"n": 71, "hablante": "krsna", "sa": ["विहाय कामान्यः सर्वान्पुमांश्चरति निःस्पृहः ।", "निर्ममो निरहङ्कारः स शान्तिमधिगच्छति ॥७१॥"], "iast": ["vihāya kāmān yaḥ sarvān pumāṃś carati niḥspṛhaḥ", "nirmamo nirahaṅkāraḥ sa śāntim adhigacchati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El hombre que, abandonando todos los <a class=\"t\" href=\"glosario.html#kama\" data-t=\"kama\">deseos</a>, vive sin anhelo, libre del «mío» y del <a class=\"t\" href=\"glosario.html#ahankara\" data-t=\"ahankara\">sentido del yo</a>, alcanza la <a class=\"t\" href=\"glosario.html#santi\" data-t=\"santi\">paz</a>.</span>", "palabras": [{"iast": "vihāya", "sa": "विहाय", "gram": "abs.", "es": "abandonando", "analisis": "vi-√hā (dejar, abandonar)"}, {"iast": "kāmān", "sa": "कामान्", "gram": "ac. pl. m.", "es": "los deseos", "ref": "kama"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. pron.", "es": "quien"}, {"iast": "sarvān", "sa": "सर्वान्", "gram": "ac. pl. m. adj.", "es": "todos"}, {"iast": "pumān", "sa": "पुमान्", "gram": "nom. sg. m.", "es": "el hombre, la persona"}, {"iast": "carati", "sa": "चरति", "gram": "3 sg. pres. act.", "es": "se mueve, vive", "analisis": "√car (moverse, andar, vivir)"}, {"iast": "niḥspṛhaḥ", "sa": "निःस्पृहः", "gram": "nom. sg. m. adj.", "es": "sin anhelo", "analisis": "niḥ (sin) + spṛhā (anhelo, codicia)"}, {"iast": "nirmamaḥ", "sa": "निर्ममः", "gram": "nom. sg. m. adj.", "es": "sin «mío»", "analisis": "nir (sin) + mama (mío, de mí)"}, {"iast": "nirahaṅkāraḥ", "sa": "निरहङ्कारः", "gram": "nom. sg. m. adj.", "es": "sin sentido del yo", "ref": "ahankara", "analisis": "nir (sin) + ahaṃkāra (sentido del yo: aham «yo» + kāra «hacer»)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "śāntim", "sa": "शान्तिम्", "gram": "ac. sg. f.", "es": "la paz", "ref": "santi"}, {"iast": "adhigacchati", "sa": "अधिगच्छति", "gram": "3 sg. pres. act.", "es": "alcanza", "analisis": "adhi-√gam (llegar a, alcanzar)"}], "nota": "<p>Tres adjetivos con prefijo privativo describen al sabio: <em>niḥspṛha</em>, «sin anhelo»; <em>nirmama</em>, literalmente «sin mío», sin sentido de posesión; y <em>nirahaṅkāra</em>, «sin sentido del yo», sin la conciencia de ser el autor y el centro de todo. Volverán juntos, o casi, en la descripción del devoto (<a class=\"vref\" href=\"capitulo-12.html#v13\" data-v=\"12.13\">12.13</a>) y del sabio (<a class=\"vref\" href=\"capitulo-18.html#v53\" data-v=\"18.53\">18.53</a>).</p><p>Como en <a class=\"vref\" href=\"capitulo-02.html#v64\" data-v=\"2.64\">2.64</a> (<em>caran</em>), el verbo es <em>car</em>, aquí <em>carati</em>, «se mueve, vive»: abandonar los deseos no implica dejar de estar en el mundo.</p>", "interp": [{"titulo": "El renunciante errante", "html": "<p>La lectura advaita tiende a ver aquí el retrato del <em>saṃnyāsin</em>, el renunciante que lo ha dejado todo y vive vagando, sin casa ni posesiones. Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, la plena firmeza en el conocimiento es propia de quien ha renunciado también a la acción ritual y mundana, y el <em>carati</em> del verso se refiere a la vida errante del asceta.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Desapego en la acción", "html": "<p>Los intérpretes modernos que leen la Gītā como un tratado de la acción, con <a class=\"t\" href=\"glosario.html#tilak\" data-t=\"tilak\">Tilak</a> a la cabeza, rechazan que el libro recomiende abandonar la vida activa: Kṛṣṇa está exhortando a Arjuna a combatir. Desde esta lectura, <em>carati</em> significa vivir y actuar en el mundo, y lo que se abandona no es la acción, sino el anhelo, la posesión y el yo que se cree su autor.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}, {"titulo": "«Mío»", "html": "<p>Es significativo que el primer capítulo empezara con la pregunta de Dhṛtarāṣṭra por «los míos» (<em>māmakāḥ</em>, <a class=\"vref\" href=\"capitulo-01.html#v1\" data-v=\"1.1\">1.1</a>) y que el discurso del segundo termine con el ideal del <em>nirmama</em>, el que no dice «mío». Entre ambos extremos se sitúa el drama de Arjuna, paralizado por el apego a los suyos (<em>sva-jana</em>, <a class=\"vref\" href=\"capitulo-01.html#v28\" data-v=\"1.28\">1.28</a>).</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "paz-del-oceano"}, {"n": 72, "hablante": "krsna", "sa": ["एषा ब्राह्मी स्थितिः पार्थ नैनां प्राप्य विमुह्यति ।", "स्थित्वास्यामन्तकालेऽपि ब्रह्मनिर्वाणमृच्छति ॥७२॥"], "iast": ["eṣā brāhmī sthitiḥ pārtha naināṃ prāpya vimuhyati", "sthitvāsyām anta-kāle 'pi brahma-nirvāṇam ṛcchati"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Éste es el estado de <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>; quien lo alcanza ya no se extravía. Y quien permanece en él, aunque sea en la hora final, llega a la <a class=\"t\" href=\"glosario.html#nirvana\" data-t=\"nirvana\">extinción en brahman</a>.</span>", "palabras": [{"iast": "eṣā", "sa": "एषा", "gram": "nom. sg. f. pron.", "es": "éste"}, {"iast": "brāhmī", "sa": "ब्राह्मी", "gram": "nom. sg. f. adj.", "es": "de brahman", "ref": "brahman", "analisis": "adjetivo derivado de brahman"}, {"iast": "sthitiḥ", "sa": "स्थितिः", "gram": "nom. sg. f.", "es": "estado, permanencia", "analisis": "√sthā (estar de pie, permanecer)"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "na", "sa": "न", "gram": "ind.", "es": "no"}, {"iast": "enām", "sa": "एनाम्", "gram": "ac. sg. f. pron.", "es": "éste, lo"}, {"iast": "prāpya", "sa": "प्राप्य", "gram": "abs.", "es": "habiéndolo alcanzado", "analisis": "pra-√āp (alcanzar)"}, {"iast": "vimuhyati", "sa": "विमुह्यति", "gram": "3 sg. pres. act.", "es": "se extravía", "analisis": "vi-√muh (confundirse, extraviarse); de la misma raíz que moha"}, {"iast": "sthitvā", "sa": "स्थित्वा", "gram": "abs.", "es": "permaneciendo", "analisis": "√sthā (permanecer)"}, {"iast": "asyām", "sa": "अस्याम्", "gram": "loc. sg. f. pron.", "es": "en él"}, {"iast": "anta-kāle", "sa": "अन्तकाले", "gram": "loc. sg. m. comp.", "es": "en la hora final", "analisis": "anta (fin) + kāla (tiempo)"}, {"iast": "api", "sa": "अपि", "gram": "ind.", "es": "aun, incluso"}, {"iast": "brahma-nirvāṇam", "sa": "ब्रह्मनिर्वाणम्", "gram": "ac. sg. n. comp.", "es": "la extinción en brahman", "ref": "nirvana", "analisis": "brahman + nirvāṇa (extinción, apagamiento; nir-√vā «apagarse soplando»)"}, {"iast": "ṛcchati", "sa": "ऋच्छति", "gram": "3 sg. pres. act.", "es": "llega a, alcanza", "analisis": "√ṛ (ir, alcanzar)"}], "nota": "<p>Con este verso termina la respuesta a la pregunta de Arjuna sobre el sabio de sabiduría firme (<a class=\"vref\" href=\"capitulo-02.html#v54\" data-v=\"2.54\">2.54</a>), y con ella el capítulo. <em>Brāhmī sthiti</em>, «el estado de brahman», nombra la meta de todo lo descrito: no un estado de ánimo pasajero, sino una permanencia (<em>sthiti</em>, de la misma raíz que <em>sthita-prajña</em>). <em>Vimuhyati</em>, «se extravía», remite al <em>moha</em>, el extravío en que estaba sumido Arjuna.</p><p><em>Anta-kāle &#x27;pi</em>, «aun en la hora final», se entiende de dos modos: incluso si se alcanza este estado sólo en el momento de la muerte, o bien permaneciendo en él hasta ese momento. La importancia del último instante será un tema del capítulo 8 (<a class=\"vref\" href=\"capitulo-08.html#v5\" data-v=\"8.5\">8.5</a>–<a class=\"vref\" href=\"capitulo-08.html#v6\" data-v=\"8.6\">8.6</a>).</p><p><em>Brahma-nirvāṇa</em>, «la extinción en brahman», aparece aquí por primera vez; volverá en <a class=\"vref\" href=\"capitulo-05.html#v24\" data-v=\"5.24\">5.24</a>–<a class=\"vref\" href=\"capitulo-05.html#v26\" data-v=\"5.26\">5.26</a>. <em>Nirvāṇa</em> es el apagarse de una llama al soplarla, la misma palabra que el budismo usa para la liberación.</p>", "interp": [{"titulo": "Ser brahman", "html": "<p>Para la lectura advaita, «el estado de brahman» es el conocimiento de que el sí-mismo no es otro que <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, y la «extinción en brahman» es la <a class=\"t\" href=\"glosario.html#moksa\" data-t=\"moksa\">liberación</a>: lo que se apaga no es el ser, sino la ilusión de ser un individuo separado. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> ve en este verso la culminación del camino del conocimiento que el capítulo ha expuesto desde <a class=\"vref\" href=\"capitulo-02.html#v11\" data-v=\"2.11\">2.11</a>.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Extinción sin disolución", "html": "<p>Las escuelas teístas del Vedānta no entienden la liberación como disolución de la persona. Para el <a class=\"t\" href=\"glosario.html#visistadvaita\" data-t=\"visistadvaita\">Viśiṣṭādvaita</a>, el alma liberada conserva su individualidad y goza de brahman, que es Dios personal, del que es parte inseparable como un cuerpo de su alma. Lo que se «extingue» es el sufrimiento y la sujeción al ciclo de renacimientos, no el alma que los padecía.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Un primer peldaño", "html": "<p>La tradición <a class=\"t\" href=\"glosario.html#gaudiya\" data-t=\"gaudiya\">gauḍīya</a> distingue tres modos de captar lo absoluto, apoyándose en el <a class=\"t\" href=\"glosario.html#bhagavata-purana\" data-t=\"bhagavata-purana\">Bhāgavata Purāṇa</a>: como brahman impersonal, como Paramātman o Señor interior y como Bhagavān, la persona divina. El estado de brahman de este verso es real y liberador, pero para esta escuela es un peldaño anterior a la devoción plena a Kṛṣṇa, que el libro irá desvelando en los capítulos siguientes.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}, {"titulo": "Nirvāṇa entre brahmanismo y budismo", "html": "<p><em>Nirvāṇa</em> es el término central de la soteriología budista, y la expresión <em>brahma-nirvāṇa</em> ha llamado la atención de los estudiosos modernos. Muchos ven en ella un eco o una respuesta al budismo: la Gītā adoptaría la palabra, pero la anclaría en brahman, de modo que la extinción no lo sería en el vacío, sino en una realidad plena. La cronología relativa de la Gītā y de los textos budistas es discutida, y con ella el sentido exacto de esta relación.</p>", "trad": "critica", "tradNombre": "Lectura histórico-crítica"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "estado-de-brahman"}], "ensenanzas": [{"id": "el-que-habita-el-cuerpo", "desde": 12, "hasta": 13, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El que habita el cuerpo pasa de un cuerpo a otro", "resumen": "<p>Primera tesis de Kṛṣṇa: ni él, ni Arjuna, ni los reyes han dejado nunca de existir, ni dejarán de hacerlo. El que habita el cuerpo atraviesa la niñez, la juventud y la vejez sin dejar de ser el mismo, y del mismo modo pasa a otro cuerpo al morir. Por eso el sabio no se extravía ante la muerte.</p>"}, {"id": "soportar-los-contrarios", "desde": 14, "hasta": 15, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Soportar los contrarios", "resumen": "<p>Frío y calor, placer y dolor nacen del contacto de los sentidos con sus objetos, y vienen y se van. La práctica consiste en soportarlos (<em>titikṣā</em>) sin dejarse arrastrar, hasta ser igual en el placer y en el dolor. Quien lo logra está preparado para la inmortalidad, es decir, para la liberación.</p>"}, {"id": "lo-que-no-muere", "desde": 16, "hasta": 25, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "La naturaleza del sí-mismo: lo que no nace ni muere", "resumen": "<p>Lo que es no deja de ser. El morador del cuerpo es eterno, imperecedero e inconmensurable; no mata ni es muerto, no nace ni muere, y deja los cuerpos como quien cambia de vestido. Ningún elemento puede dañarlo, y escapa a los sentidos y al pensamiento. De ahí la conclusión práctica: no hay razón para afligirse por la muerte.</p>"}, {"id": "ciclo-de-los-seres", "desde": 27, "hasta": 28, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "De lo no manifiesto a lo no manifiesto", "resumen": "<p>Lo que nace muere y lo que muere vuelve a nacer: es inevitable. Los seres sólo son visibles en el tramo intermedio de su existencia; antes de nacer y después de morir están en lo <a class=\"t\" href=\"glosario.html#avyakta\" data-t=\"avyakta\">no manifiesto</a>. Lamentar la muerte es no comprender este ciclo.</p>"}, {"id": "igualar-los-contrarios", "desde": 38, "hasta": 38, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Igualar los contrarios y actuar", "resumen": "<p>Antes de actuar, considerar iguales el placer y el dolor, la ganancia y la pérdida, la victoria y la derrota, y sólo entonces emprender la acción debida. Hecha así, la acción no deja <a class=\"t\" href=\"glosario.html#papa\" data-t=\"papa\">pecado</a>. Es la primera formulación de la <a class=\"t\" href=\"glosario.html#samatva\" data-t=\"samatva\">ecuanimidad</a> que <a class=\"vref\" href=\"capitulo-02.html#v48\" data-v=\"2.48\">2.48</a> llamará yoga.</p>"}, {"id": "entendimiento-resuelto", "desde": 41, "hasta": 41, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El entendimiento resuelto", "resumen": "<p>Kṛṣṇa define el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> propio del yoga: es «resuelto» y uno solo, fijo en una meta. El de quien obra movido por el deseo se ramifica sin fin, como un árbol que no deja de echar ramas. Esa unidad interior es la condición de todo lo que sigue.</p>"}, {"id": "mas-alla-de-los-guna", "desde": 45, "hasta": 45, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Más allá de las tres guṇas", "resumen": "<p>Frente a los ritos que prometen bienes del mundo condicionado, Kṛṣṇa indica cómo situarse por encima de él: no dejarse arrastrar por los pares de opuestos, apoyarse en la claridad de <a class=\"t\" href=\"glosario.html#sattva\" data-t=\"sattva\">sattva</a>, soltar la preocupación por adquirir y conservar, y ser dueño de sí.</p>"}, {"id": "actuar-sin-apego", "desde": 47, "hasta": 48, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Actuar sin apego al fruto", "resumen": "<p>La técnica central del <a class=\"t\" href=\"glosario.html#karma-yoga\" data-t=\"karma-yoga\">karma-yoga</a>: hacer lo que corresponde sin que el resultado sea el motivo, sin refugiarse por ello en la inacción, y mantenerse igual ante el éxito y el fracaso. A esa <a class=\"t\" href=\"glosario.html#samatva\" data-t=\"samatva\">ecuanimidad</a> la llama Kṛṣṇa yoga.</p>"}, {"id": "destreza-en-la-accion", "desde": 49, "hasta": 51, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "El yoga como destreza en la acción", "resumen": "<p>Buscar refugio en el entendimiento ecuánime y no en el cálculo del resultado. Así hecha, la acción deja de atar: no acumula méritos ni deméritos, y el sabio que renuncia al fruto alcanza el estado libre de todo mal.</p>"}, {"id": "entendimiento-inmovil", "desde": 52, "hasta": 53, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El entendimiento inmóvil", "resumen": "<p>La meta del <a class=\"t\" href=\"glosario.html#buddhi-yoga\" data-t=\"buddhi-yoga\">yoga del entendimiento</a>: atravesar el extravío, dejar de esperar nada de las promesas de los ritos y mantener el entendimiento firme en el <a class=\"t\" href=\"glosario.html#samadhi\" data-t=\"samadhi\">samādhi</a>. Es el estado que Kṛṣṇa describirá a continuación en el sabio de sabiduría firme.</p>"}, {"id": "rasgos-sabiduria-firme", "desde": 55, "hasta": 57, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Quién es el de sabiduría firme", "resumen": "<p>A la pregunta de Arjuna, Kṛṣṇa responde con un retrato del <a class=\"t\" href=\"glosario.html#sthitaprajna\" data-t=\"sthitaprajna\">sthita-prajña</a>. Ha soltado todos los deseos que habían entrado en su mente y halla su contento en el sí-mismo (<a class=\"vref\" href=\"capitulo-02.html#v55\" data-v=\"2.55\">2.55</a>). La desdicha no lo turba, el placer no despierta su ansia, y está libre de apego, miedo e ira (<a class=\"vref\" href=\"capitulo-02.html#v56\" data-v=\"2.56\">2.56</a>). Ante lo bueno y lo malo que le llega, ni lo celebra ni lo aborrece (<a class=\"vref\" href=\"capitulo-02.html#v57\" data-v=\"2.57\">2.57</a>).</p>"}, {"id": "retirar-los-sentidos", "desde": 58, "hasta": 61, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Retirar los sentidos, como la tortuga", "resumen": "<p>La técnica tiene tres pasos. Primero, retirar por completo los sentidos de sus objetos, como la tortuga recoge sus miembros (<a class=\"vref\" href=\"capitulo-02.html#v58\" data-v=\"2.58\">2.58</a>). Después, saber que la abstinencia no basta: el gusto por los objetos sólo se extingue al ver lo supremo (<a class=\"vref\" href=\"capitulo-02.html#v59\" data-v=\"2.59\">2.59</a>), y los sentidos arrastran incluso al sabio que se esfuerza (<a class=\"vref\" href=\"capitulo-02.html#v60\" data-v=\"2.60\">2.60</a>). Por eso, una vez dominados, hay que sentarse unido en yoga, con la mente puesta en Kṛṣṇa como meta suprema (<a class=\"vref\" href=\"capitulo-02.html#v61\" data-v=\"2.61\">2.61</a>).</p>"}, {"id": "cadena-del-deseo", "desde": 62, "hasta": 63, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Del pensamiento a la ruina: la cadena del deseo", "resumen": "<p>Kṛṣṇa describe, eslabón por eslabón, cómo se pierde el ser humano. Pensar en los objetos de los sentidos engendra apego; el apego, deseo; el deseo, ira; la ira, extravío; el extravío, confusión de la memoria; ésta, la ruina del entendimiento, y con ella se pierde la persona. Todo empieza en la atención: por eso la técnica anterior consiste en retirarla de los objetos.</p>"}, {"id": "sentidos-dominados", "desde": 64, "hasta": 68, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Moverse entre los objetos con los sentidos dominados", "resumen": "<p>Kṛṣṇa no pide huir de los objetos de los sentidos, sino moverse entre ellos con unos sentidos libres de atracción y aversión y gobernados por uno mismo. El fruto es la serenidad (<em>prasāda</em>), en la que se disuelve el sufrimiento y el entendimiento se asienta. Sin esa disciplina no hay entendimiento, ni contemplación, ni paz, ni felicidad; y basta que la mente se vaya tras un solo sentido para que la sabiduría quede a la deriva, como una barca empujada por el viento.</p>"}, {"id": "paz-del-oceano", "desde": 70, "hasta": 71, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "La paz del océano: dejar de perseguir los deseos", "resumen": "<p>Los deseos seguirán llegando, como los ríos al mar; la paz consiste en recibirlos sin desbordarse, desde una plenitud que no depende de ellos. Para eso hay que abandonar el anhelo, la posesión (el «mío») y el sentido del yo como autor de todo, sin por ello dejar de vivir en el mundo.</p>"}, {"id": "estado-de-brahman", "desde": 72, "hasta": 72, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El estado de brahman y la extinción en brahman", "resumen": "<p>El sabio de sabiduría firme vive en el «estado de brahman» (<em>brāhmī sthiti</em>), una permanencia de la que ya no se recae en el extravío. Quien se mantiene en él hasta la muerte alcanza <em>brahma-nirvāṇa</em>, «la extinción en brahman». Qué se extingue y qué permanece es una de las grandes divergencias entre las escuelas.</p>"}]};
